const LEAF_HEADERS = ['Region', 'Team', 'Shift', 'Employee', 'Hours', 'Status']
const DEFAULT_PAGE_SIZE = 12
/** Rows are emitted region-major: 3 teams x 3 shifts per region. */
const REGION_RUN = 9

