    resizerTransform(header: any) {
      if (local.columnResizeMode === 'onEnd' && header.column.getIsResizing()) {
        const delta = table.atoms.columnResizing.get().deltaOffset ?? 0
        const dir = local.columnResizeDirection === 'rtl' ? -1 : 1
