  readonly paginationAtom = createAtom<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  })

  readonly table = injectTable(() => ({
    key: 'basic-external-atoms', // needed for devtools
    debugTable: true,
    features,
    columns,
    data: this.data(),
    atoms: {
      sorting: this.sortingAtom,
      pagination: this.paginationAtom,
    },
  }))

