            <option [value]="value">{{ value }}</option>
          }
        </select>
      }
      @default {
        <datalist [id]="column().id + 'list'">
          @for (value of sortedUniqueValues(); track value) {
            <option [value]="value">{{ value }}</option>
          }
        </datalist>
        <input
          type="text"
          class="filter-select"
          debouncedInput
          [debounce]="500"
          placeholder="Search..."
