        : isFirstRightPinnedColumn
          ? '4px 0 4px -4px gray inset'
          : undefined,
      insetInlineStart:
        isPinned === 'start' ? `${column.getStart('start')}px` : undefined,
      insetInlineEnd:
        isPinned === 'end' ? `${column.getAfter('end')}px` : undefined,
      opacity: isPinned ? 0.97 : 1,
      position: isPinned ? 'sticky' : 'relative',
      zIndex: isPinned ? 1 : 0,
    }
  }

  headerStyles(header: Header<typeof features, Person, unknown>) {
    return {
      ...this.getCommonPinningStyles(header.column),
      whiteSpace: 'nowrap',
    }
  }

  cellStyles(cell: Cell<typeof features, Person, unknown>) {
    return this.getCommonPinningStyles(cell.column)
  }

  cellClass(cell: Cell<typeof features, Person, unknown>) {
    const groupingActive = this.table.atoms.grouping.get().length > 0
    const hasAggregation = !!cell.column.columnDef.aggregationFn
    return !groupingActive
      ? undefined
      : cell.getIsGrouped()
        ? 'cell-grouped'
        : hasAggregation && cell.getIsAggregated()
          ? 'cell-aggregated'
          : cell.getIsPlaceholder()
            ? 'cell-placeholder'
            : undefined
  }

  pinnedRowStyles(row: Row<typeof features, Person>) {
    const bottomRows = this.table.getBottomRows()
    return {
      position: 'sticky',
      top:
        row.getIsPinned() === 'top'
          ? `${row.getPinnedIndex() * 32 + 48}px`
          : undefined,
      bottom:
        row.getIsPinned() === 'bottom'
          ? `${(bottomRows.length - 1 - row.getPinnedIndex()) * 32}px`
          : undefined,
      zIndex: 1,
    }
  }
}

import { Directive, HostListener, input, output } from '@angular/core'

@Directive({
  standalone: true,
  selector: 'input[debouncedInput]',
})
export class DebouncedInput {
  readonly debounce = input<number>(300)
  readonly changeEvent = output<Event>()

  private timeout: ReturnType<typeof setTimeout> | undefined

  @HostListener('input', ['$event'])
  onInput(event: Event) {
    clearTimeout(this.timeout)
    this.timeout = setTimeout(() => {
      this.changeEvent.emit(event)
    }, this.debounce())
  }
}

import { faker } from '@faker-js/faker'

export type Person = {
  firstName: string
  lastName: string
  age: number
  visits: number
  progress: number
  status: 'relationship' | 'complicated' | 'single'
  subRows?: Array<Person>
}

const range = (len: number) => {
  const arr: Array<number> = []
  for (let i = 0; i < len; i++) {
    arr.push(i)
  }
  return arr
}

const newPerson = (): Person => {
  return {
    firstName: faker.person.firstName(),
    lastName: faker.person.lastName(),
    age: faker.number.int(40),
    visits: faker.number.int(1000),
    progress: faker.number.int(100),
    status: faker.helpers.shuffle<Person['status']>([
      'relationship',
      'complicated',
      'single',
    ])[0],
  }
}

export function makeData(...lens: Array<number>) {
  const makeDataLevel = (depth = 0): Array<Person> => {
    const len = lens[depth]
    return range(len).map((_): Person => {
      return {
        ...newPerson(),
        subRows: lens[depth + 1] ? makeDataLevel(depth + 1) : undefined,
      }
    })
  }

  return makeDataLevel()
}

