import {
  DestroyRef,
  Injectable,
  computed,
  inject,
  isDevMode,
  signal,
} from '@angular/core'
import { TRADING_COLUMN_COUNT } from '../table/table-config/trading-column-types'
import { MarketFeedService } from '../feed/market-feed.service'
import {
  FORCED_VIRTUALIZATION_ROW_COUNT,
  resolveVirtualScrollMode,
} from '../table/trading-row-virtualizer'
import {
  BenchmarkMonitor,
  exposeTradingBenchmarkSnapshot,
  initialMetrics,
} from './benchmark-monitor'
import type {
  VirtualScrollMode,
  VirtualScrollPreference,
} from '../table/trading-row-virtualizer'
import type { FeedMetrics } from './benchmark-monitor'
import type { RendererMode } from '../table/table-config/trading-column-types'

@Injectable({ providedIn: 'root' })
export class TradingBenchmarkController {
  readonly #destroyRef = inject(DestroyRef)
  readonly #monitor = new BenchmarkMonitor()
  readonly #feed = inject(MarketFeedService)
  readonly #longAnimationFrameObserver: PerformanceObserver | null

  readonly devMode = isDevMode()
  readonly longAnimationFramesSupported =
    PerformanceObserver.supportedEntryTypes.includes('long-animation-frame')
  readonly tableWorkerEnabled = signal(false)
  readonly renderedRowCount = signal(0)
  readonly rendererMode = signal<RendererMode>('stable')
  readonly requestedVirtualScrollMode = signal<VirtualScrollPreference>('auto')
  readonly selectedSymbol = signal<string | null>(null)
  readonly metrics = signal<FeedMetrics>(initialMetrics)
  readonly displayQuotes = this.#feed.quotes
  readonly selectedQuote = computed(() => {
    const symbol = this.selectedSymbol()
    return symbol
      ? (this.displayQuotes().find((quote) => quote.symbol === symbol) ?? null)
      : null
  })
  readonly virtualScrollForced = computed(
    () => this.#feed.instrumentCount() >= FORCED_VIRTUALIZATION_ROW_COUNT,
  )
  readonly virtualScrollMode = computed<VirtualScrollMode>(() =>
    resolveVirtualScrollMode(
      this.requestedVirtualScrollMode(),
      this.#feed.instrumentCount(),
    ),
  )
  readonly mountedCells = computed(
    () => this.renderedRowCount() * TRADING_COLUMN_COUNT,
  )
  readonly liveComponents = computed(() => {
    const metrics = this.metrics()
    return metrics.componentsCreated - metrics.componentsDestroyed
  })

  #animationFrameId: number | null = null

  constructor() {
    const stopObservingFeed = this.#feed.observe({
      messageReceived: () => this.#monitor.recordWorkerMessage(),
      mutationStarted: () => this.#monitor.markRenderPending(),
      batchApplied: ({ tickCount, updateCount, supersededUpdateCount }) =>
        this.#monitor.recordBatch(
          tickCount,
          updateCount,
          supersededUpdateCount,
        ),
      renderCommitted: () => this.#monitor.recordCompletedRender(),
    })
    this.#longAnimationFrameObserver = this.longAnimationFramesSupported
      ? new PerformanceObserver(this.#recordLongAnimationFrames)
      : null
    this.#longAnimationFrameObserver?.observe({
      type: 'long-animation-frame',
    })
    this.#animationFrameId = requestAnimationFrame(this.#benchmarkFrame)
    this.#destroyRef.onDestroy(() => {
      stopObservingFeed()
      if (this.#animationFrameId !== null) {
        cancelAnimationFrame(this.#animationFrameId)
      }
      this.#longAnimationFrameObserver?.disconnect()
    })
  }

  setRendererMode(shouldSwap: boolean): void {
    this.rendererMode.set(shouldSwap ? 'swap' : 'stable')
  }

  setTableWorkerEnabled(enabled: boolean): void {
    this.tableWorkerEnabled.set(enabled)
  }

  setVirtualScrollEnabled(enabled: boolean): void {
    if (this.virtualScrollForced()) return
    this.requestedVirtualScrollMode.set(enabled ? 'tanstack' : 'none')
  }

  setRenderedRowCount(count: number): void {
    this.renderedRowCount.set(count)
  }

  recordDomMutations(count: number): void {
    this.#monitor.recordDomMutations(count)
  }

  resetDomMutations(): void {
    this.#monitor.resetDomMutations()
  }

  resetViewState(): void {
    this.selectedSymbol.set(null)
    this.requestedVirtualScrollMode.set('auto')
  }

  resetMarket(): void {
    this.#monitor.reset()
    this.resetViewState()
    this.metrics.set(initialMetrics)
    this.#feed.reset()
  }

  readonly #benchmarkFrame = (now: number): void => {
    this.#monitor.recordAnimationFrame(now)
    if (this.#monitor.shouldPublish(now)) {
      const metrics = this.#monitor.publish(now)
      this.metrics.set(metrics)
      exposeTradingBenchmarkSnapshot(metrics, {
        mountedCells: this.mountedCells(),
        liveComponents: this.liveComponents(),
      })
    }
    this.#animationFrameId = requestAnimationFrame(this.#benchmarkFrame)
  }

  readonly #recordLongAnimationFrames = (
    entries: PerformanceObserverEntryList,
  ): void => {
    for (const entry of entries.getEntries()) {
      this.#monitor.recordLongAnimationFrame(entry.duration, entry.startTime)
    }
  }
}

import {
  DestroyRef,
  Injectable,
  afterEveryRender,
  inject,
  signal,
} from '@angular/core'
import { normalizeFeedSampleRate } from './feed-sample-rates'
import { initialMarketFeedConfig } from './market-feed-config'
import { applyMarketUpdates, hydrateMarketQuotes } from './market-data'
import type {
  MarketFeedCommand,
  MarketFeedEvent,
} from './worker/market-feed-protocol'
import type { MarketQuote } from './market-data'

export interface MarketFeedBatch {
  tickCount: number
  updateCount: number
  supersededUpdateCount: number
}

export interface MarketFeedObserver {
  messageReceived?: () => void
  mutationStarted?: () => void
  batchApplied?: (batch: MarketFeedBatch) => void
  renderCommitted?: () => void
}

@Injectable({ providedIn: 'root' })
export class MarketFeedService {
  readonly #destroyRef = inject(DestroyRef)
  readonly #worker = new Worker(
    new URL('./worker/market-feed.worker', import.meta.url),
    { type: 'module' },
  )
  readonly #observers = new Set<MarketFeedObserver>()

  readonly workerReady = signal(false)
  readonly running = signal(!new URLSearchParams(location.search).has('paused'))
  readonly instrumentCount = signal(initialMarketFeedConfig.instrumentCount)
  readonly targetTicksPerSecond = signal(
    initialMarketFeedConfig.targetSamplesPerSecond,
  )
  readonly publishIntervalMs = signal(initialMarketFeedConfig.publishIntervalMs)
  readonly updateSparklines = signal(initialMarketFeedConfig.updateSparklines)
  readonly sparklineSampleIntervalMs = signal(
    initialMarketFeedConfig.sparklineSampleIntervalMs,
  )
  readonly quotes = signal<Array<MarketQuote>>([])

  #feedSessionId = 0
  #renderPending = false

  constructor() {
    afterEveryRender(() => this.completeRender())
    this.#worker.addEventListener('message', this.#handleWorkerMessage)
    this.#worker.addEventListener('error', this.#handleWorkerError)
    this.#post({
      type: 'start',
      rowCount: this.instrumentCount(),
      running: this.running(),
      ticksPerSecond: this.targetTicksPerSecond(),
      publishIntervalMs: this.publishIntervalMs(),
      updateSparklines: this.updateSparklines(),
      sparklineSampleIntervalMs: this.sparklineSampleIntervalMs(),
    })
    this.#destroyRef.onDestroy(() => {
      this.#worker.removeEventListener('message', this.#handleWorkerMessage)
      this.#worker.removeEventListener('error', this.#handleWorkerError)
      this.#worker.terminate()
      this.#observers.clear()
    })
  }

  observe(observer: MarketFeedObserver): () => void {
    this.#observers.add(observer)
    return () => this.#observers.delete(observer)
  }

  completeRender(): void {
    if (!this.#renderPending) return

    this.#renderPending = false
    for (const observer of this.#observers) {
      observer.renderCommitted?.()
    }
  }

  toggle(): void {
    const running = !this.running()
    this.running.set(running)
    this.#post({ type: 'set-running', running })
  }

  setInstrumentCount(count: number): void {
    this.instrumentCount.set(count)
    this.reset()
  }

  setTargetRate(rate: number): void {
    const sampleRate = normalizeFeedSampleRate(rate)
    this.targetTicksPerSecond.set(sampleRate)
    this.#post({ type: 'set-rate', ticksPerSecond: sampleRate })
  }

  setPublishInterval(publishIntervalMs: number): void {
    this.publishIntervalMs.set(publishIntervalMs)
    this.#post({ type: 'set-publish-interval', intervalMs: publishIntervalMs })
  }

  setSparklineUpdates(enabled: boolean): void {
    this.updateSparklines.set(enabled)
    this.#post({ type: 'set-sparklines', enabled })
  }

  setSparklineSampleInterval(intervalMs: number): void {
    this.sparklineSampleIntervalMs.set(intervalMs)
    this.#post({ type: 'set-sparkline-interval', intervalMs })
  }

  runBurst(): void {
    this.#post({ type: 'burst', tickCount: 25_000 })
  }

  reset(): void {
    this.workerReady.set(false)
    this.#post({ type: 'reset', rowCount: this.instrumentCount() })
  }

  readonly #handleWorkerMessage = ({
    data,
  }: MessageEvent<MarketFeedEvent>): void => {
    if (data.type === 'snapshot') {
      this.#feedSessionId = data.sessionId
      this.#startMutation()
      this.quotes.set(hydrateMarketQuotes(data.quotes))
      this.workerReady.set(true)
      return
    }

    if (data.sessionId !== this.#feedSessionId) return

    for (const observer of this.#observers) {
      observer.messageReceived?.()
    }
    this.#startMutation()
    this.quotes.update((quotes) => applyMarketUpdates(quotes, data.updates))
    const batch = {
      tickCount: data.tickCount,
      updateCount: data.updates.length,
      supersededUpdateCount: data.coalescedUpdateCount,
    }
    for (const observer of this.#observers) {
      observer.batchApplied?.(batch)
    }
  }

  readonly #handleWorkerError = (error: ErrorEvent): void => {
    this.workerReady.set(false)
    this.running.set(false)
    console.error('Market feed worker failed', error)
  }

  #startMutation(): void {
    this.#renderPending = true
    for (const observer of this.#observers) {
      observer.mutationStarted?.()
    }
  }

  #post(command: MarketFeedCommand): void {
    this.#worker.postMessage(command)
  }
}

import { globalInstruments } from '../market-instruments'
import type {
  MarketQuoteSnapshot,
  MarketQuoteUpdate,
} from './market-feed-protocol'

const INITIAL_MARKET_SEED = 0x4d41524b
const LIVE_FEED_SEED = 0x5449434b

export class MarketFeedEngine {
  #quotes: Array<MarketQuoteSnapshot> = []
  #lastHistorySampledAt = new Uint32Array(0)
  #random = createRandom(2_026)
  #rowCursor = 0
  #tickIndex = 0

  reset(count: number): Array<MarketQuoteSnapshot> {
    const random = createRandom(INITIAL_MARKET_SEED ^ count)
    const createdAt = Date.now()

    this.#quotes = Array.from({ length: count }, (_, index) => {
      const [baseSymbol, company, market] =
        globalInstruments[index % globalInstruments.length]
      const series = Math.floor(index / globalInstruments.length)
      const symbol = series === 0 ? baseSymbol : `${baseSymbol}${series}`
      const previousClose = roundPrice(20 + random() * 480)
      const open = roundPrice(previousClose * (1 + (random() - 0.5) * 0.016))
      const spread = Math.max(0.01, open * (0.0002 + random() * 0.0004))
      const history = Array.from({ length: 24 }, (_, historyIndex) =>
        roundPrice(
          open *
            (1 + Math.sin(historyIndex / 4) * 0.002 + (random() - 0.5) * 0.001),
        ),
      )
      const volume = Math.floor(50_000 + random() * 2_000_000)
      const lastSize = Math.floor(10 + random() * 5_000)

      return {
        id: `instrument-${index}`,
        symbol,
        company,
        venue: market,
        previousClose,
        open,
        high: open,
        low: open,
        price: open,
        bid: roundPrice(open - spread / 2),
        ask: roundPrice(open + spread / 2),
        bidSize: Math.floor(100 + random() * 25_000),
        askSize: Math.floor(100 + random() * 25_000),
        lastSize,
        lastMove: 0,
        lastUpdatedAt: createdAt,
        volume,
        turnover: roundMoney(open * volume),
        history,
      }
    })

    this.#random = createRandom(LIVE_FEED_SEED ^ count)
    this.#rowCursor = 0
    this.#lastHistorySampledAt = new Uint32Array(count)
    this.#lastHistorySampledAt.fill(createdAt >>> 0)

    return this.#quotes.map((quote) => ({
      ...quote,
      history: [...quote.history],
    }))
  }

  applyTicks(
    tickCount: number,
    updateSparklines: boolean,
    sparklineSampleIntervalMs: number,
  ): Array<MarketQuoteUpdate> {
    if (this.#quotes.length === 0 || tickCount <= 0) return []

    const updatedAt = Date.now()
    const sampledAt = updatedAt >>> 0
    const sampleIntervalMs = Math.max(16, sparklineSampleIntervalMs)
    const updatedQuotes = new Map<number, MarketQuoteUpdate>()
    const stride = 97

    this.#tickIndex = 0
    while (this.#tickIndex < tickCount) {
      this.#rowCursor = (this.#rowCursor + stride) % this.#quotes.length
      const quote = this.#quotes[this.#rowCursor]
      const lastSampledAt = this.#lastHistorySampledAt[this.#rowCursor]
      const shouldUpdateHistory =
        updateSparklines &&
        (sampledAt - lastSampledAt) >>> 0 >= sampleIntervalMs

      if (shouldUpdateHistory) {
        this.#lastHistorySampledAt[this.#rowCursor] = sampledAt
      }

      this.#applyTick(quote, shouldUpdateHistory, updatedAt)

      const previousUpdate = updatedQuotes.get(this.#rowCursor)
      updatedQuotes.set(this.#rowCursor, {
        index: this.#rowCursor,
        price: quote.price,
        bid: quote.bid,
        ask: quote.ask,
        bidSize: quote.bidSize,
        askSize: quote.askSize,
        lastSize: quote.lastSize,
        lastMove: quote.lastMove,
        lastUpdatedAt: quote.lastUpdatedAt,
        high: quote.high,
        low: quote.low,
        volume: quote.volume,
        turnover: quote.turnover,
        ...(shouldUpdateHistory || previousUpdate?.history
          ? { history: [...quote.history] }
          : {}),
      })
      this.#tickIndex++
    }

    return [...updatedQuotes.values()]
  }

  #applyTick(
    quote: MarketQuoteSnapshot,
    updateHistory: boolean,
    updatedAt: number,
  ): void {
    const previousPrice = quote.price
    const volatility = 0.00015 + this.#random() * 0.0012
    const move = previousPrice * (this.#random() - 0.495) * volatility
    const nextPrice = roundPrice(Math.max(0.1, previousPrice + move))
    const spread = Math.max(
      0.01,
      nextPrice * (0.00015 + this.#random() * 0.0005),
    )

    quote.lastMove = nextPrice - previousPrice
    quote.price = nextPrice
    quote.high = Math.max(quote.high, nextPrice)
    quote.low = Math.min(quote.low, nextPrice)
    quote.bid = roundPrice(nextPrice - spread / 2)
    quote.ask = roundPrice(nextPrice + spread / 2)
    quote.bidSize = Math.floor(100 + this.#random() * 25_000)
    quote.askSize = Math.floor(100 + this.#random() * 25_000)
    quote.lastSize = Math.floor(10 + this.#random() * 5_000)
    quote.lastUpdatedAt = updatedAt
    quote.volume += quote.lastSize
    quote.turnover = roundMoney(quote.turnover + nextPrice * quote.lastSize)

    if (updateHistory) {
      quote.history = [...quote.history.slice(-23), nextPrice]
    }
  }
}

function createRandom(seed: number): () => number {
  const runtime = { state: seed >>> 0 }
  return () => {
    runtime.state += 0x6d2b79f5
    const stateValue = runtime.state
    const firstMix = Math.imul(stateValue ^ (stateValue >>> 15), stateValue | 1)
    const secondMix =
      firstMix + Math.imul(firstMix ^ (firstMix >>> 7), firstMix | 61)
    const value = firstMix ^ secondMix
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296
  }
}

function roundPrice(value: number): number {
  return Math.round(value * 100) / 100
}

function roundMoney(value: number): number {
  return Math.round(value * 100) / 100
}

