          placeholder="Min"
          [value]="getMinValue()"
          (input)="updateMinFilterValue(min.value)"
        />
        <input
          #max
          type="number"
          class="filter-select"
          placeholder="max"
          [value]="getMaxValue()"
          (input)="updateMaxFilterValue(max.value)"
        />
      </div>
    } @else {
      <input
        #search
        type="text"
        class="filter-select"
        placeholder="Search..."
        [value]="column().getFilterValue() ?? ''"
        (input)="column().setFilterValue(search.value)"
      />
    }
