export const longAnimationFramesSupported =
  PerformanceObserver.supportedEntryTypes.includes('long-animation-frame')

function readHeapSizeMb(): number | null {
  const memory = (
    performance as Performance & {
      memory?: { usedJSHeapSize: number }
    }
  ).memory
  return memory ? memory.usedJSHeapSize / 1_048_576 : null
}

function calculateInvocationRates(
  current: Record<string, number>,
  previous: Record<string, number>,
  sampleDuration: number,
): ReadonlyArray<NamedInvocationRate> {
  return Object.entries(current).map(([name, calls]) => ({
    name,
    callsPerSecond:
      sampleDuration === 0
        ? 0
        : ((calls - (previous[name] ?? 0)) / sampleDuration) * 1_000,
  }))
}

export function exposeTradingBenchmarkSnapshot(
  metrics: FeedMetrics,
  extras: { mountedCells: number; liveComponents: number },
): void {
  Object.assign(globalThis, {
    __TANSTACK_TRADING_BENCHMARK__: {
      capturedAt: performance.now(),
      metrics,
      ...extras,
    },
  })
}

import { cached, tracked } from '@glimmer/tracking'
import { TRADING_COLUMN_COUNT } from '../table/trading-table'
import {
  BenchmarkMonitor,
  exposeTradingBenchmarkSnapshot,
  initialMetrics,
  longAnimationFramesSupported,
} from './benchmark-monitor'
import type { FeedMetrics } from './benchmark-monitor'
import type { MarketFeedController } from '../feed/market-feed-controller'
import type { RendererMode } from '../table/trading-table'

export interface TradingBenchmarkActions {
  resetViewState: () => void
  setRendererMode: (mode: RendererMode) => void
  setRenderedRowCount: (count: number) => void
  selectSymbol: (symbol: string | null) => void
  resetMarket: () => void
}

export class TradingBenchmarkController {
  @tracked metrics: FeedMetrics = initialMetrics
  @tracked mountedCells = 0
  @tracked selectedSymbol: string | null = null
  @tracked rendererMode: RendererMode = 'stable'
  invalidateTable: (() => void) | null = null
  @cached
  get liveComponents(): number {
    const metrics = this.metrics
    return metrics.componentsCreated - metrics.componentsDestroyed
  }
  readonly longAnimationFramesSupported = longAnimationFramesSupported
  readonly monitor = new BenchmarkMonitor()
  readonly feed: MarketFeedController
  readonly actions: TradingBenchmarkActions

  readonly #runtime = {
    animationFrameId: 0,
    longAnimationFrameObserver: null as PerformanceObserver | null,
    stopObservingFeed: null as (() => void) | null,
  }

  constructor(feed: MarketFeedController) {
    this.feed = feed
    this.actions = {
      resetViewState: () => {
        this.selectedSymbol = null
        this.invalidateTable?.()
      },
      setRendererMode: (mode) => {
        this.rendererMode = mode
      },
      setRenderedRowCount: (count) => {
        const mountedCells = count * TRADING_COLUMN_COUNT
        if (mountedCells !== this.mountedCells) {
          this.mountedCells = mountedCells
        }
      },
      selectSymbol: (symbol) => {
        this.selectedSymbol = symbol
      },
      resetMarket: () => {
        this.monitor.reset()
        this.metrics = { ...initialMetrics }
        this.mountedCells = 0
        this.selectedSymbol = null
        this.feed.actions.reset()
      },
    }
  }

  start(): () => void {
    const longAnimationFrameObserver = longAnimationFramesSupported
      ? new PerformanceObserver((entries) => {
          for (const entry of entries.getEntries()) {
            this.monitor.recordLongAnimationFrame(
              entry.duration,
              entry.startTime,
            )
          }
        })
      : null

    this.#runtime.longAnimationFrameObserver = longAnimationFrameObserver
    this.#runtime.stopObservingFeed = this.feed.observe({
      messageReceived: () => this.monitor.recordWorkerMessage(),
      mutationStarted: () => this.monitor.markRenderPending(),
      batchApplied: ({ tickCount, updateCount, supersededUpdateCount }) =>
        this.monitor.recordBatch(tickCount, updateCount, supersededUpdateCount),
      renderCommitted: () => this.monitor.recordCompletedRender(),
    })
    longAnimationFrameObserver?.observe({
      type: 'long-animation-frame',
    })
    this.#runtime.animationFrameId = requestAnimationFrame(this.#benchmarkFrame)

    return () => this.stop()
  }

  stop(): void {
    cancelAnimationFrame(this.#runtime.animationFrameId)
    this.#runtime.longAnimationFrameObserver?.disconnect()
    this.#runtime.stopObservingFeed?.()
    this.#runtime.longAnimationFrameObserver = null
    this.#runtime.stopObservingFeed = null
  }

  readonly #benchmarkFrame = (now: number): void => {
    this.monitor.recordAnimationFrame(now)
    if (this.monitor.shouldPublish(now)) {
      this.#publishMetrics(this.monitor.publish(now))
    }
    this.#runtime.animationFrameId = requestAnimationFrame(this.#benchmarkFrame)
  }

  #publishMetrics(metrics: FeedMetrics): void {
    this.metrics = metrics
    exposeTradingBenchmarkSnapshot(metrics, {
      mountedCells: this.mountedCells,
      liveComponents: this.liveComponents,
    })
  }
}

export const feedSampleRateOptions = [
  { label: '100', value: 100 },
  { label: '250', value: 250 },
  { label: '500', value: 500 },
  { label: '1K', value: 1_000 },
  { label: '2.5K', value: 2_500 },
  { label: '5K', value: 5_000 },
  { label: '10K', value: 10_000 },
  { label: '25K', value: 25_000 },
  { label: '50K', value: 50_000 },
  { label: '100K', value: 100_000 },
] as const

export function feedSampleRateIndex(rate: number): number {
  return feedSampleRateOptions.reduce((closestIndex, candidate, index) => {
    const closest = feedSampleRateOptions[closestIndex]!
    return Math.abs(candidate.value - rate) < Math.abs(closest.value - rate)
      ? index
      : closestIndex
  }, 0)
}

export function feedSampleRateAt(stepIndex: number): number {
  const index = Math.min(
    feedSampleRateOptions.length - 1,
    Math.max(0, Math.round(stepIndex)),
  )
  return feedSampleRateOptions[index]!.value
}

export function normalizeFeedSampleRate(rate: number): number {
  return feedSampleRateAt(feedSampleRateIndex(rate))
}

import { tracked } from '@glimmer/tracking'
import { normalizeFeedSampleRate } from './feed-sample-rates'
import { initialMarketFeedConfig } from './market-feed-config'
import { applyMarketUpdates, hydrateMarketQuotes } from './market-data'
import type {
  MarketFeedCommand,
  MarketFeedEvent,
} from './worker/market-feed-protocol'
import type { MarketQuote } from './market-data'

export interface MarketFeedBatch {
  tickCount: number
  updateCount: number
  supersededUpdateCount: number
}

export interface MarketFeedObserver {
  messageReceived?: () => void
  mutationStarted?: () => void
  batchApplied?: (batch: MarketFeedBatch) => void
  renderCommitted?: () => void
  viewChanged?: () => void
}

export interface MarketFeedActions {
  toggle: () => void
  setInstrumentCount: (count: number) => void
  setTargetRate: (rate: number) => void
  setPublishInterval: (intervalMs: number) => void
  setSparklineUpdates: (enabled: boolean) => void
  setSparklineSampleInterval: (intervalMs: number) => void
  runBurst: () => void
  reset: () => void
}

export class MarketFeedController {
  @tracked workerReady = false
  @tracked running = !new URLSearchParams(location.search).has('paused')
  instrumentCount = initialMarketFeedConfig.instrumentCount
  @tracked targetTicksPerSecond = initialMarketFeedConfig.targetSamplesPerSecond
  @tracked publishIntervalMs = initialMarketFeedConfig.publishIntervalMs
  @tracked updateSparklines = initialMarketFeedConfig.updateSparklines
  @tracked sparklineSampleIntervalMs =
    initialMarketFeedConfig.sparklineSampleIntervalMs
  quotes: Array<MarketQuote> = []
  readonly actions: MarketFeedActions
  readonly #observers = new Set<MarketFeedObserver>()
  readonly #runtime = {
    worker: null as Worker | null,
    feedSessionId: 0,
    renderPending: false,
    resetWaitingForCommit: false,
    resetSnapshotReady: false,
    quoteIndexBySymbol: new Map<string, number>(),
  }

  constructor() {
    this.actions = {
      toggle: () => {
        const running = !this.running
        this.running = running
        this.#post({ type: 'set-running', running })
      },
      setInstrumentCount: (count) => {
        this.instrumentCount = count
        this.#resetWorker(count)
      },
      setTargetRate: (rate) => {
        const sampleRate = normalizeFeedSampleRate(rate)
        this.targetTicksPerSecond = sampleRate
        this.#post({ type: 'set-rate', ticksPerSecond: sampleRate })
      },
      setPublishInterval: (publishIntervalMs) => {
        this.publishIntervalMs = publishIntervalMs
        this.#post({
          type: 'set-publish-interval',
          intervalMs: publishIntervalMs,
        })
      },
      setSparklineUpdates: (enabled) => {
        this.updateSparklines = enabled
        this.#post({ type: 'set-sparklines', enabled })
      },
      setSparklineSampleInterval: (intervalMs) => {
        this.sparklineSampleIntervalMs = intervalMs
        this.#post({ type: 'set-sparkline-interval', intervalMs })
      },
      runBurst: () => this.#post({ type: 'burst', tickCount: 25_000 }),
      reset: () => this.#resetWorker(this.instrumentCount),
    }
  }

  start(): () => void {
    const worker = new Worker(
      new URL('./worker/market-feed.worker.ts', import.meta.url),
      { type: 'module' },
    )
    this.#runtime.worker = worker
    worker.addEventListener('message', this.#handleWorkerMessage)
    worker.addEventListener('error', this.#handleWorkerError)
    this.#post({
      type: 'start',
      rowCount: this.instrumentCount,
      running: this.running,
      ticksPerSecond: this.targetTicksPerSecond,
      publishIntervalMs: this.publishIntervalMs,
      updateSparklines: this.updateSparklines,
      sparklineSampleIntervalMs: this.sparklineSampleIntervalMs,
    })
    return () => this.stop()
  }

  stop(): void {
    this.#runtime.worker?.removeEventListener(
      'message',
      this.#handleWorkerMessage,
    )
    this.#runtime.worker?.removeEventListener('error', this.#handleWorkerError)
    this.#runtime.worker?.terminate()
    this.#runtime.worker = null
    this.#observers.clear()
  }

  observe(observer: MarketFeedObserver): () => void {
    this.#observers.add(observer)
    return () => this.#observers.delete(observer)
  }

  getQuoteBySymbol(
    quotes: Array<MarketQuote>,
    symbol: string | null,
  ): MarketQuote | null {
    if (symbol === null) return null

    const index = this.#runtime.quoteIndexBySymbol.get(symbol)
    return index === undefined ? null : (quotes[index] ?? null)
  }

  completeRender(): void {
    if (!this.#runtime.renderPending) return

    this.#runtime.renderPending = false
    for (const observer of this.#observers) {
      observer.renderCommitted?.()
    }
    if (
      this.#runtime.resetWaitingForCommit &&
      this.#runtime.resetSnapshotReady
    ) {
      this.#runtime.resetWaitingForCommit = false
      this.#runtime.resetSnapshotReady = false
      this.#post({ type: 'set-running', running: this.running })
    }
  }

  readonly #handleWorkerMessage = ({
    data,
  }: MessageEvent<MarketFeedEvent>): void => {
    if (data.type === 'snapshot') {
      this.#runtime.feedSessionId = data.sessionId
      if (this.#runtime.resetWaitingForCommit) {
        this.#runtime.resetSnapshotReady = true
      }
      this.#startMutation()
      const quotes = hydrateMarketQuotes(data.quotes)
      this.#runtime.quoteIndexBySymbol = new Map(
        quotes.map((quote, index) => [quote.symbol, index]),
      )
      this.quotes = quotes
      this.workerReady = true
      this.#notifyView()
      return
    }

    if (data.sessionId !== this.#runtime.feedSessionId) return

    for (const observer of this.#observers) {
      observer.messageReceived?.()
    }
    this.#startMutation()
    const quotes = applyMarketUpdates(this.quotes, data.updates)
    this.quotes = quotes
    this.#notifyView()
    const feedBatch = {
      tickCount: data.tickCount,
      updateCount: data.updates.length,
      supersededUpdateCount: data.coalescedUpdateCount,
    }
    for (const observer of this.#observers) {
      observer.batchApplied?.(feedBatch)
    }
  }

  readonly #handleWorkerError = (error: ErrorEvent): void => {
    this.workerReady = false
    this.running = false
    console.error('Market feed worker failed', error)
  }

  #resetWorker(rowCount: number): void {
    if (this.running) {
      this.workerReady = false
      this.#runtime.resetWaitingForCommit = true
      this.#runtime.resetSnapshotReady = false
      this.#post({ type: 'set-running', running: false })
    }
    this.#post({ type: 'reset', rowCount })
  }

  #startMutation(): void {
    this.#runtime.renderPending = true
    for (const observer of this.#observers) {
      observer.mutationStarted?.()
    }
  }

  #notifyView(): void {
    for (const observer of this.#observers) {
      observer.viewChanged?.()
    }
  }

  #post(command: MarketFeedCommand): void {
    this.#runtime.worker?.postMessage(command)
  }
}

import { globalInstruments } from '../market-instruments.ts'
import type {
  MarketQuoteSnapshot,
  MarketQuoteUpdate,
} from './market-feed-protocol'

const INITIAL_MARKET_SEED = 0x4d41524b
const LIVE_FEED_SEED = 0x5449434b

export class MarketFeedEngine {
  #quotes: Array<MarketQuoteSnapshot> = []
  #lastHistorySampledAt = new Uint32Array(0)
  #random = createRandom(2_026)
  #rowCursor = 0
  #tickIndex = 0

  reset(count: number): Array<MarketQuoteSnapshot> {
    const random = createRandom(INITIAL_MARKET_SEED ^ count)
    const createdAt = Date.now()

    this.#quotes = Array.from({ length: count }, (_, index) => {
      const [baseSymbol, company, market] =
        globalInstruments[index % globalInstruments.length]!
      const series = Math.floor(index / globalInstruments.length)
      const symbol = series === 0 ? baseSymbol : `${baseSymbol}${series}`
      const previousClose = roundPrice(20 + random() * 480)
      const open = roundPrice(previousClose * (1 + (random() - 0.5) * 0.016))
      const spread = Math.max(0.01, open * (0.0002 + random() * 0.0004))
      const history = Array.from({ length: 24 }, (_, historyIndex) =>
        roundPrice(
          open *
            (1 + Math.sin(historyIndex / 4) * 0.002 + (random() - 0.5) * 0.001),
        ),
      )
      const volume = Math.floor(50_000 + random() * 2_000_000)
      const lastSize = Math.floor(10 + random() * 5_000)

      return {
        id: `instrument-${index}`,
        symbol,
        company,
        venue: market,
        previousClose,
        open,
        high: open,
        low: open,
        price: open,
        bid: roundPrice(open - spread / 2),
        ask: roundPrice(open + spread / 2),
        bidSize: Math.floor(100 + random() * 25_000),
        askSize: Math.floor(100 + random() * 25_000),
        lastSize,
        lastMove: 0,
        lastUpdatedAt: createdAt,
        volume,
        turnover: roundMoney(open * volume),
        history,
      }
    })

    this.#random = createRandom(LIVE_FEED_SEED ^ count)
    this.#rowCursor = 0
    this.#lastHistorySampledAt = new Uint32Array(count)
    this.#lastHistorySampledAt.fill(createdAt >>> 0)

    return this.#quotes.map((quote) => ({
      ...quote,
      history: [...quote.history],
    }))
  }

  applyTicks(
    tickCount: number,
    updateSparklines: boolean,
    sparklineSampleIntervalMs: number,
  ): Array<MarketQuoteUpdate> {
    if (this.#quotes.length === 0 || tickCount <= 0) return []

    const updatedAt = Date.now()
    const sampledAt = updatedAt >>> 0
    const sampleIntervalMs = Math.max(16, sparklineSampleIntervalMs)
    const updatedQuotes = new Map<number, MarketQuoteUpdate>()
    const stride = 97

    this.#tickIndex = 0
    while (this.#tickIndex < tickCount) {
      this.#rowCursor = (this.#rowCursor + stride) % this.#quotes.length
      const quote = this.#quotes[this.#rowCursor]!
      const lastSampledAt = this.#lastHistorySampledAt[this.#rowCursor]!
      const shouldUpdateHistory =
        updateSparklines &&
        (sampledAt - lastSampledAt) >>> 0 >= sampleIntervalMs

      if (shouldUpdateHistory) {
        this.#lastHistorySampledAt[this.#rowCursor] = sampledAt
      }

      this.#applyTick(quote, shouldUpdateHistory, updatedAt)

      const previousUpdate = updatedQuotes.get(this.#rowCursor)
      updatedQuotes.set(this.#rowCursor, {
        index: this.#rowCursor,
        price: quote.price,
        bid: quote.bid,
        ask: quote.ask,
        bidSize: quote.bidSize,
        askSize: quote.askSize,
        lastSize: quote.lastSize,
        lastMove: quote.lastMove,
        lastUpdatedAt: quote.lastUpdatedAt,
        high: quote.high,
        low: quote.low,
        volume: quote.volume,
        turnover: quote.turnover,
        ...(shouldUpdateHistory || previousUpdate?.history
          ? { history: [...quote.history] }
          : {}),
      })
      this.#tickIndex++
    }

    return [...updatedQuotes.values()]
  }

  #applyTick(
    quote: MarketQuoteSnapshot,
    updateHistory: boolean,
    updatedAt: number,
  ): void {
    const previousPrice = quote.price
    const volatility = 0.00015 + this.#random() * 0.0012
    const move = previousPrice * (this.#random() - 0.495) * volatility
    const nextPrice = roundPrice(Math.max(0.1, previousPrice + move))
    const spread = Math.max(
      0.01,
      nextPrice * (0.00015 + this.#random() * 0.0005),
    )

    quote.lastMove = nextPrice - previousPrice
    quote.price = nextPrice
    quote.high = Math.max(quote.high, nextPrice)
    quote.low = Math.min(quote.low, nextPrice)
    quote.bid = roundPrice(nextPrice - spread / 2)
    quote.ask = roundPrice(nextPrice + spread / 2)
    quote.bidSize = Math.floor(100 + this.#random() * 25_000)
    quote.askSize = Math.floor(100 + this.#random() * 25_000)
    quote.lastSize = Math.floor(10 + this.#random() * 5_000)
    quote.lastUpdatedAt = updatedAt
    quote.volume += quote.lastSize
    quote.turnover = roundMoney(quote.turnover + nextPrice * quote.lastSize)

    if (updateHistory) {
      quote.history = [...quote.history.slice(-23), nextPrice]
    }
  }
}

function createRandom(seed: number): () => number {
  const runtime = { state: seed >>> 0 }
  return () => {
    runtime.state += 0x6d2b79f5
    const stateValue = runtime.state
    const firstMix = Math.imul(stateValue ^ (stateValue >>> 15), stateValue | 1)
    const secondMix =
      firstMix + Math.imul(firstMix ^ (firstMix >>> 7), firstMix | 61)
    const value = firstMix ^ secondMix
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296
  }
}

function roundPrice(value: number): number {
  return Math.round(value * 100) / 100
}

function roundMoney(value: number): number {
  return Math.round(value * 100) / 100
}

export type CellDirection = 'up' | 'down' | 'left' | 'right'

interface RowSelectionTable {
  resetRowSelection: (defaultState?: boolean) => void
}

interface SelectableRow {
  getIsSelected: () => boolean
  getToggleSelectedHandler: (options?: {
    selectChildren?: boolean
  }) => (event: unknown) => void
}

interface SelectableGridCell {
  row: SelectableGridRow
  getSelectionStartHandler: (
    contextDocument?: Document,
  ) => (event: unknown) => void
  getSelectionExtendHandler: () => (event: unknown) => void
}

interface SelectableGridRow extends SelectableRow {
  original: { symbol: string }
  getAllCellsByColumnId: () => Record<string, SelectableGridCell>
}

interface TradingGridTable extends RowSelectionTable {
  getRowModel: () => {
    rowsById: Record<string, SelectableGridRow>
  }
}

interface SelectionCellTarget {
  element: HTMLTableCellElement
  cell: SelectableGridCell
}

interface CellNavigationTable {
  extendCellSelection: (direction: CellDirection) => void
  moveCellSelection: (direction: CellDirection) => void
  resetCellSelection: (defaultState?: boolean) => void
  selectAllCells: () => void
}

const keyDirections: Partial<Record<string, CellDirection>> = {
  ArrowUp: 'up',
  ArrowDown: 'down',
  ArrowLeft: 'left',
  ArrowRight: 'right',
}

export function reorderColumnIds(
  columnIds: Array<string>,
  sourceId: string,
  targetId: string,
): Array<string> {
  if (sourceId === targetId || !columnIds.includes(sourceId)) return columnIds

  const withoutSource = columnIds.filter((id) => id !== sourceId)
  const targetIndex = withoutSource.indexOf(targetId)
  if (targetIndex < 0) return columnIds

  return [
    ...withoutSource.slice(0, targetIndex),
    sourceId,
    ...withoutSource.slice(targetIndex),
  ]
}

export function selectRowFromPointer(
  table: RowSelectionTable,
  row: SelectableRow,
  event: MouseEvent,
): void {
  const additive = event.ctrlKey || event.metaKey
  const checked = additive ? !row.getIsSelected() : true

  if (!event.shiftKey && !additive) table.resetRowSelection(true)

  row.getToggleSelectedHandler({ selectChildren: false })({
    target: { checked },
    shiftKey: event.shiftKey,
    ctrlKey: event.ctrlKey,
    metaKey: event.metaKey,
  })
}

export class TradingGridPointerController {
  #lastPointerCell: HTMLTableCellElement | null = null

  handleMouseDown(
    table: TradingGridTable,
    event: MouseEvent,
    selectSymbol: (symbol: string) => void,
  ): void {
    if (event.button !== 0) return

    const target = this.#findCellTarget(table, event.composedPath())
    if (!target) return

    event.preventDefault()
    this.#lastPointerCell = target.element
    selectSymbol(target.cell.row.original.symbol)
    target.cell.getSelectionStartHandler(target.element.ownerDocument)(event)
  }

  handlePointerOver(table: TradingGridTable, event: MouseEvent): void {
    if ((event.buttons & 1) === 0) {
      this.resetPointerCell()
      return
    }

    const target = this.#findCellTarget(table, event.composedPath())
    if (!target || target.element === this.#lastPointerCell) return

    this.#lastPointerCell = target.element
    target.cell.getSelectionExtendHandler()(event)
  }

  handleClick(table: TradingGridTable, event: MouseEvent): void {
    const target = this.#findCellTarget(table, event.composedPath())
    if (!target) return
    selectRowFromPointer(table, target.cell.row, event)
  }

  resetPointerCell(): void {
    this.#lastPointerCell = null
  }

  #findCellTarget(
    table: TradingGridTable,
    path: Array<EventTarget>,
  ): SelectionCellTarget | null {
    for (const target of path) {
      if (!(target instanceof HTMLTableCellElement)) continue

      const columnId = target.dataset['columnId']
      const rowId =
        target.closest<HTMLTableRowElement>('tr[data-row-id]')?.dataset['rowId']
      if (!columnId || !rowId) return null

      const row = table.getRowModel().rowsById[rowId]
      if (!row) return null
      const cell = row.getAllCellsByColumnId()[columnId]
      if (!cell) return null
      return { element: target, cell }
    }

    return null
  }
}

export function handleCellNavigation(
  table: CellNavigationTable,
  event: KeyboardEvent,
): void {
  if (event.key === 'Escape') {
    event.preventDefault()
    table.resetCellSelection(true)
    return
  }

  if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'a') {
    event.preventDefault()
    table.selectAllCells()
    return
  }

  const direction = keyDirections[event.key]
  if (!direction) return

  event.preventDefault()
  if (event.shiftKey) table.extendCellSelection(direction)
  else table.moveCellSelection(direction)
}

export function sortIndicator(direction: false | 'asc' | 'desc'): string {
  if (direction === 'asc') return '↑'
  if (direction === 'desc') return '↓'
  return '↕'
}

export function sortAriaValue(
  direction: false | 'asc' | 'desc',
): 'ascending' | 'descending' | 'none' {
  if (direction === 'asc') return 'ascending'
  if (direction === 'desc') return 'descending'
  return 'none'
}

