          ${this.table.subscribe(
            this.table.store,
            (state) => state.globalFilter,
            (globalFilter) => html`
              <input
                type="text"
                .value=${globalFilter ?? ''}
                @input=${(e: InputEvent) =>
                  this.table.setGlobalFilter(
