                                    : null
                                }
                              `
                        }
                      </th>
                    `,
                  )}
                </tr>
              `,
            )}
          </thead>

          <!-- Row model subscribe - re-render tbody only when filtering/pagination changes -->
          ${this.table.subscribe(
            this.table.store,
            this.getBodyState,
            () => html`
              <tbody>
                ${repeat(
                  this.table.getRowModel().rows,
                  (row) => row.id,
                  (row) => html`
                    <tr>
