                    )}
                  </tr>
                `,
              )}
            </tbody>
          </table>
          <!-- Center (unpinned) table -->
          <table class="outlined-table">
            <thead>
              ${repeat(
                table.getCenterHeaderGroups(),
                (headerGroup) => headerGroup.id,
                (headerGroup) => html`
                  <tr>
                    ${repeat(
