                  <tr>
                    ${repeat(
                      row.getCenterVisibleCells(),
                      (cell) => cell.id,
                      (cell) => html` <td>${FlexRender({ cell })}</td> `,
                    )}
                  </tr>
                `,
              )}
            </tbody>
          </table>
          <!-- Right pinned table -->
          <table class="outlined-table">
            <thead>
              ${repeat(
                table.getEndHeaderGroups(),
                (headerGroup) => headerGroup.id,
                (headerGroup) => html`
                  <tr>
                    ${repeat(
