import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

/** Leaf columns in render order. The toggle panel labels each by column id. */
const LEAF_COLUMNS = [
  'firstName',
  'lastName',
  'age',
  'visits',
  'status',
  'progress',
]

/** Leaf header text differs from column id wherever a custom header is set. */
const LEAF_HEADERS = [
  'firstName',
  'Last Name',
  'Age',
  'Visits',
  'Status',
  'Profile Progress',
]

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return errors
}

function columnToggle(page: Page, label: string) {
  return page.getByLabel(label, { exact: true })
}

/** Header rows run group to leaf, so the leaf row is last. */
function leafHeaderCells(page: Page) {
  return page.locator('thead tr').last().locator('th')
}

/** Footer groups are the header groups reversed, so the leaf row is first. */
function leafFooterCells(page: Page) {
  return page.locator('tfoot tr').first().locator('th')
}

function groupHeaderCells(page: Page) {
  return page.locator('thead tr').first().locator('th')
}

function firstBodyRowCells(page: Page) {
  return page.locator('tbody tr').first().locator('td')
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readColumnVisibility(page: Page) {
  const text = await page.getByTestId('table-state').textContent()
  const state = JSON.parse(text ?? '{}') as {
    columnVisibility?: Record<string, boolean>
  }

  return state.columnVisibility ?? {}
}

async function expectColumnVisibility(
  page: Page,
  expected: Record<string, boolean>,
) {
  await expect.poll(() => readColumnVisibility(page)).toEqual(expected)
}

async function getFirstBodyRowText(page: Page) {
  const text = await page.locator('tbody tr').first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  // Two nested column groups produce three header rows.
  await expect(page.locator('thead tr')).toHaveCount(3)
  await expect(groupHeaderCells(page)).toHaveText(['Name', 'Info'])
  await expect(leafHeaderCells(page)).toHaveText(LEAF_HEADERS)
  await expect(leafFooterCells(page)).toHaveText(LEAF_COLUMNS)
  await expect(page.locator('tbody tr')).toHaveCount(20)
  await expect(firstBodyRowCells(page)).toHaveCount(6)
  await expectColumnVisibility(page, {})

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(page.locator('tbody tr').first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(page.locator('tbody tr')).toHaveCount(20)

  expect(errors).toEqual([])
})

test('renders a toggle for every leaf column', async ({ page }) => {
  const errors = await openExample(page)

  // One checkbox per leaf column plus the panel's Toggle All.
  await expect(page.locator('.column-toggle-panel input')).toHaveCount(7)
  await expect(page.locator('.column-toggle-row label')).toHaveText(
    LEAF_COLUMNS,
  )

  await expect(columnToggle(page, 'Toggle All')).toBeChecked()

  for (const column of LEAF_COLUMNS) {
    await expect(columnToggle(page, column)).toBeChecked()
  }

  expect(errors).toEqual([])
})

test('hides and shows an individual column', async ({ page }) => {
  const errors = await openExample(page)

  await columnToggle(page, 'visits').uncheck()

  await expectColumnVisibility(page, { visits: false })
  await expect(leafHeaderCells(page)).toHaveText(
    LEAF_HEADERS.filter((header) => header !== 'Visits'),
  )
  await expect(firstBodyRowCells(page)).toHaveCount(5)
  await expect(leafFooterCells(page)).toHaveCount(5)
  // Toggle All is driven by `getIsAllColumnsVisible`, so it clears too.
  await expect(columnToggle(page, 'Toggle All')).not.toBeChecked()

  await columnToggle(page, 'visits').check()

  // Re-showing records `true` rather than dropping the key.
  await expectColumnVisibility(page, { visits: true })
  await expect(leafHeaderCells(page)).toHaveText(LEAF_HEADERS)
  await expect(firstBodyRowCells(page)).toHaveCount(6)
  await expect(columnToggle(page, 'Toggle All')).toBeChecked()

  expect(errors).toEqual([])
})

test('removes a header group when all of its columns are hidden', async ({
  page,
}) => {
  const errors = await openExample(page)

  await expect(groupHeaderCells(page)).toHaveText(['Name', 'Info'])

  await columnToggle(page, 'firstName').uncheck()
  await expect(groupHeaderCells(page)).toHaveText(['Name', 'Info'])

  // The group header only disappears once its last child is hidden.
  await columnToggle(page, 'lastName').uncheck()
  await expect(groupHeaderCells(page)).toHaveText(['Info'])
  await expect(leafHeaderCells(page)).toHaveText([
    'Age',
    'Visits',
    'Status',
    'Profile Progress',
  ])
  await expect(firstBodyRowCells(page)).toHaveCount(4)

  await columnToggle(page, 'firstName').check()
  await expect(groupHeaderCells(page)).toHaveText(['Name', 'Info'])

  expect(errors).toEqual([])
})

test('hides and shows every column with Toggle All', async ({ page }) => {
  const errors = await openExample(page)

  await columnToggle(page, 'Toggle All').uncheck()

  await expectColumnVisibility(
    page,
    Object.fromEntries(LEAF_COLUMNS.map((column) => [column, false])),
  )
  await expect(leafHeaderCells(page)).toHaveCount(0)
  await expect(firstBodyRowCells(page)).toHaveCount(0)
  // The rows survive; they simply have no visible cells left to render.
  await expect(page.locator('tbody tr')).toHaveCount(20)

  for (const column of LEAF_COLUMNS) {
    await expect(columnToggle(page, column)).not.toBeChecked()
  }

  await columnToggle(page, 'Toggle All').check()

  await expectColumnVisibility(
    page,
    Object.fromEntries(LEAF_COLUMNS.map((column) => [column, true])),
  )
  await expect(leafHeaderCells(page)).toHaveText(LEAF_HEADERS)
  await expect(firstBodyRowCells(page)).toHaveCount(6)

  expect(errors).toEqual([])
})

test('keeps column visibility when data is regenerated', async ({ page }) => {
  const errors = await openExample(page)

  await columnToggle(page, 'age').uncheck()
  await expect(firstBodyRowCells(page)).toHaveCount(5)

  // Visibility lives in table state, so replacing the rows must not reset it.
  await page.getByRole('button', { name: /^Regenerate Data$/i }).click()

  await expectColumnVisibility(page, { age: false })
  await expect(columnToggle(page, 'age')).not.toBeChecked()
  await expect(firstBodyRowCells(page)).toHaveCount(5)
  await expect(leafHeaderCells(page)).toHaveText(
    LEAF_HEADERS.filter((header) => header !== 'Age'),
  )

  expect(errors).toEqual([])
})

import { html } from 'lit'
import type { Cell, RowData } from '@tanstack/lit-table'
import type { features } from '../hooks/table'

// Cell components are plain functions that receive the cell instance as their
// first argument (bound automatically by AppCell in createTableHook).
// In column definitions, call them as: cell: ({ cell }) => cell.TextCell()

export function TextCell(cell: Cell<typeof features, RowData, string>) {
  return html`<span>${String(cell.getValue() ?? '')}</span>`
}

export function NumberCell(cell: Cell<typeof features, RowData, number>) {
  return html`<span>${Number(cell.getValue() ?? 0).toLocaleString()}</span>`
}

export function StatusCell(cell: Cell<typeof features, RowData, string>) {
  const status = String(cell.getValue() ?? '')
  const statusClass =
    status === 'single'
      ? 'single'
      : status === 'complicated'
        ? 'complicated'
        : 'relationship'
  return html`<span class="status-badge ${statusClass}">${status}</span>`
}

export function ProgressCell(cell: Cell<typeof features, RowData, number>) {
  const value = Number(cell.getValue() ?? 0)
  return html`
    <div class="progress-bar">
      <div class="progress-bar-fill" style="width: ${value}%"></div>
    </div>
  `
}

export function RowActionsCell(cell: Cell<typeof features, RowData, unknown>) {
  const row = cell.row.original as {
    firstName?: string
    name?: string
  }
  const name = row.firstName ?? row.name ?? 'row'
  return html`
    <div class="row-actions">
      <button @click=${() => alert(`View ${name}`)}>View</button>
      <button @click=${() => alert(`Edit ${name}`)}>Edit</button>
      <button @click=${() => alert(`Delete ${name}`)}>Delete</button>
    </div>
  `
}

export function PriceCell(cell: Cell<typeof features, RowData, number>) {
  const value = Number(cell.getValue() ?? 0)
  return html`<span class="price"
    >$${value.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}</span
  >`
}

export function CategoryCell(cell: Cell<typeof features, RowData, string>) {
  const category = String(cell.getValue() ?? '')
  return html`<span class="category-badge ${category}">${category}</span>`
}

import { html, nothing } from 'lit'
import type { Header, RowData } from '@tanstack/lit-table'
import type { features } from '../hooks/table'

// Header components are plain functions that receive the header instance as
// their first argument (bound automatically by AppHeader/AppFooter in createTableHook).
// In column definitions, call them as: header.SortIndicator()

export function SortIndicator(
  header: Header<typeof features, RowData, unknown>,
) {
  const sorted = header.column.getIsSorted()
  if (!sorted) return nothing
  return html`<span class="sort-indicator"
    >${sorted === 'asc' ? '🔼' : '🔽'}</span
  >`
}

export function ColumnFilter(
  header: Header<typeof features, RowData, unknown>,
) {
  if (!header.column.getCanFilter()) return nothing
  const value = (header.column.getFilterValue() ?? '') as string
  return html`
    <div class="column-filter" @click=${(e: Event) => e.stopPropagation()}>
      <input
        type="text"
        .value=${value}
        @input=${(e: InputEvent) =>
          header.column.setFilterValue((e.target as HTMLInputElement).value)}
        placeholder="Filter ${header.column.id}..."
      />
    </div>
  `
}

export function FooterColumnId(
  header: Header<typeof features, RowData, unknown>,
) {
  return html`<span>${header.column.id}</span>`
}

export function FooterSum(header: Header<typeof features, RowData, unknown>) {
  const table = header.getContext().table
  const rows = table.getFilteredRowModel().rows
  const sum = rows.reduce((acc, row) => {
    const value = row.getValue(header.column.id)
    return acc + (typeof value === 'number' ? value : 0)
  }, 0)
  return html`<span>${sum > 0 ? sum.toLocaleString() : '—'}</span>`
}

import { LitElement, html, nothing } from 'lit'
import { customElement, state } from 'lit/decorators.js'
import { createAppColumnHelper, useAppTable } from '../hooks/table'
import { makeProductData } from '../makeData'
import type { Product } from '../makeData'
// Import table-level custom elements so they are registered
import './table-components'

// Create the column helper pre-bound with features — only need the data type!
const productColumnHelper = createAppColumnHelper<Product>()

// Define columns — different structure than Users table, same reusable components
const columns = productColumnHelper.columns([
  productColumnHelper.display({
    id: 'select',
    header: ({ table }) => html`
      <input
        type="checkbox"
        @change=${table.getToggleAllRowsSelectedHandler()}
        .checked=${table.getIsAllRowsSelected()}
        .indeterminate=${table.getIsSomeRowsSelected()}
      />
    `,
    cell: ({ row }) => html`
      <input
        type="checkbox"
        @click=${row.getToggleSelectedHandler()}
        .checked=${row.getIsSelected()}
        ?disabled=${!row.getCanSelect()}
        .indeterminate=${row.getIsSomeSelected()}
      />
    `,
  }),
  productColumnHelper.accessor('name', {
    header: 'Product Name',
    footer: (props) => props.column.id,
    cell: ({ cell }) => cell.TextCell(),
  }),
  productColumnHelper.accessor('category', {
    header: 'Category',
    footer: (props) => props.column.id,
    cell: ({ cell }) => cell.CategoryCell(),
  }),
  productColumnHelper.accessor('price', {
    header: 'Price',
    footer: (props) => props.column.id,
    cell: ({ cell }) => cell.PriceCell(),
  }),
  productColumnHelper.accessor('stock', {
    header: 'In Stock',
    footer: (props) => props.column.id,
    cell: ({ cell }) => cell.NumberCell(),
  }),
  productColumnHelper.accessor('rating', {
    header: 'Rating',
    footer: (props) => props.column.id,
    cell: ({ cell }) => cell.ProgressCell(),
  }),
])

@customElement('products-table')
export class ProductsTable extends LitElement {
  @state()
  private data = makeProductData(500)

  // Create the table using the same useAppTable hook
  // NOTE: Capture `this` as `host` to avoid infinite recursion in the getter
  private appTable = (() => {
    const host = this
    return useAppTable(this, {
      debugTable: true,
      columns,
      get data() {
        return host.data
      },
      enableRowSelection: true,
    })
  })()

  private refreshData = () => {
    this.data = makeProductData(500)
  }

  createRenderRoot() {
    return this
  }

  protected render() {
    const table = this.appTable.table()
    const { sorting, columnFilters } = table.state

    return html`
      <div class="table-container">
        <!-- Table toolbar using the same context-based custom element -->
        <table-toolbar
          .title=${'Products Table'}
          .onRefresh=${this.refreshData}
          .onStressTest=${() => {
            this.data = makeProductData(1_000_000)
          }}
        ></table-toolbar>

        <!-- Table element -->
        <div class="table-scroll">
          <table>
            <thead>
              ${table.getHeaderGroups().map(
                (headerGroup) => html`
                  <tr>
                    ${headerGroup.headers.map((h) =>
                      table.AppHeader(
                        h,
                        (header) => html`
                          <th
                            colspan=${header.colSpan}
                            class=${
                              header.column.getCanSort()
                                ? 'sortable-header'
                                : ''
                            }
                            @click=${header.column.getToggleSortingHandler()}
                          >
                            ${
                              header.isPlaceholder
                                ? nothing
                                : html`
                                    ${header.FlexRender()}
                                    ${header.SortIndicator()}
                                    ${header.ColumnFilter()}
                                    ${
                                      sorting.length > 1 &&
                                      sorting.findIndex(
                                        (s) => s.id === header.column.id,
                                      ) > -1
                                        ? html`<span class="sort-order"
                                            >${
                                              sorting.findIndex(
                                                (s) =>
                                                  s.id === header.column.id,
                                              ) + 1
                                            }</span
                                          >`
                                        : nothing
                                    }
                                  `
                            }
                          </th>
                        `,
                      ),
                    )}
                  </tr>
                `,
              )}
            </thead>
            <tbody>
              ${table.getRowModel().rows.map(
                (row) => html`
                  <tr>
                    ${row
                      .getAllCells()
                      .map((c) =>
                        table.AppCell(
                          c,
                          (cell) => html` <td>${cell.FlexRender()}</td> `,
                        ),
                      )}
                  </tr>
                `,
              )}
            </tbody>
            <tfoot>
              ${table.getFooterGroups().map(
                (footerGroup) => html`
                  <tr>
                    ${footerGroup.headers.map((f) =>
                      table.AppFooter(f, (footer) => {
                        const columnId = footer.column.id
                        const hasFilter = columnFilters.some(
                          (cf) => cf.id === columnId,
                        )
                        return html`
                          <td colspan=${footer.colSpan}>
                            ${
                              footer.isPlaceholder
                                ? nothing
                                : columnId === 'price' ||
                                    columnId === 'stock' ||
                                    columnId === 'rating'
                                  ? html`
                                      ${footer.FooterSum()}
                                      ${
                                        hasFilter
                                          ? html`<span
                                              class="filtered-indicator"
                                            >
                                              (filtered)</span
                                            >`
                                          : nothing
                                      }
                                    `
                                  : columnId === 'select'
                                    ? nothing
                                    : html`
                                        ${footer.FooterColumnId()}
                                        ${
                                          hasFilter
                                            ? html`<span
                                                class="filtered-indicator"
                                              >
                                                ✓</span
                                              >`
                                            : nothing
                                        }
                                      `
                            }
                          </td>
                        `
                      }),
                    )}
                  </tr>
                `,
              )}
            </tfoot>
          </table>
