@customElement('users-table')
export class UsersTable extends LitElement {
  @state()
  private data = makeData(1000)

  // Create the table — features and rowModels are already configured!
  // NOTE: We capture `this` (the LitElement) as `host` because inside the
  // object literal's getter, `this` would refer to the options object itself
  // (causing infinite recursion if we wrote `get data() { return this.data }`).
  private appTable = (() => {
    const host = this
    return useAppTable(this, {
      columns,
      get data() {
        return host.data
      },
      enableRowSelection: true,
      debugTable: true,
    })
  })()

  private refreshData = () => {
    this.data = makeData(1000)
  }

  createRenderRoot() {
    return this
  }

  protected render() {
    const table = this.appTable.table()
    const { sorting, columnFilters } = table.state

    return html`
      <div class="table-container">
        <!-- Table toolbar using context-based custom element -->
        <table-toolbar
          .title=${'Users Table'}
          .onRefresh=${this.refreshData}
          .onStressTest=${() => {
            this.data = makeData(1_000_000)
          }}
        ></table-toolbar>

        <!-- Table element -->
        <div class="table-scroll">
          <table>
            <thead>
              ${table.getHeaderGroups().map(
                (headerGroup) => html`
                  <tr>
                    ${headerGroup.headers.map((h) =>
                      table.AppHeader(
                        h,
                        (header) => html`
                          <th
                            colspan=${header.colSpan}
                            class=${
                              header.column.getCanSort()
                                ? 'sortable-header'
                                : ''
                            }
                            @click=${header.column.getToggleSortingHandler()}
                          >
                            ${
                              header.isPlaceholder
                                ? nothing
                                : html`
                                    ${header.FlexRender()}
                                    ${header.SortIndicator()}
                                    ${header.ColumnFilter()}
                                    ${
                                      sorting.length > 1 &&
                                      sorting.findIndex(
                                        (s) => s.id === header.column.id,
                                      ) > -1
                                        ? html`<span class="sort-order"
                                            >${
                                              sorting.findIndex(
                                                (s) =>
                                                  s.id === header.column.id,
                                              ) + 1
                                            }</span
                                          >`
                                        : nothing
                                    }
                                  `
                            }
                          </th>
                        `,
                      ),
                    )}
                  </tr>
                `,
              )}
            </thead>
            <tbody>
              ${table.getRowModel().rows.map(
                (row) => html`
                  <tr>
                    ${row
                      .getAllCells()
                      .map((c) =>
                        table.AppCell(
                          c,
                          (cell) => html` <td>${cell.FlexRender()}</td> `,
                        ),
                      )}
                  </tr>
                `,
              )}
            </tbody>
            <tfoot>
              ${table.getFooterGroups().map(
                (footerGroup) => html`
                  <tr>
                    ${footerGroup.headers.map((f) =>
                      table.AppFooter(f, (footer) => {
                        const columnId = footer.column.id
                        const hasFilter = columnFilters.some(
                          (cf) => cf.id === columnId,
                        )
                        return html`
                          <td colspan=${footer.colSpan}>
                            ${
                              footer.isPlaceholder
                                ? nothing
                                : columnId === 'age' ||
                                    columnId === 'visits' ||
                                    columnId === 'progress'
                                  ? html`
                                      ${footer.FooterSum()}
                                      ${
                                        hasFilter
                                          ? html`<span
                                              class="filtered-indicator"
                                            >
                                              (filtered)</span
                                            >`
                                          : nothing
                                      }
                                    `
                                  : columnId === 'actions' ||
                                      columnId === 'select'
                                    ? nothing
                                    : html`
                                        ${footer.FooterColumnId()}
                                        ${
                                          hasFilter
                                            ? html`<span
                                                class="filtered-indicator"
                                              >
                                                ✓</span
                                              >`
                                            : nothing
                                        }
                                      `
                            }
                          </td>
                        `
                      }),
                    )}
                  </tr>
                `,
              )}
            </tfoot>
          </table>
        </div>

        <!-- Pagination and row count using context-based custom elements -->
        <pagination-controls></pagination-controls>
        <row-count></row-count>
      </div>
    `
  }
}

