function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return errors
}

/** `<` is a prefix of `<<`, so every page button match has to be exact. */
function pageButton(page: Page, label: '<<' | '<' | '>' | '>>') {
  return page.getByRole('button', { name: label, exact: true })
}

/** The `{pageIndex + 1} of {pageCount}` readout. */
function pageStatus(page: Page) {
  return page.locator('.controls strong')
}

function goToPageInput(page: Page) {
  return page.getByRole('spinbutton')
}

function pageSizeSelect(page: Page) {
  return page.locator('.controls select')
}

function rowCountLine(page: Page) {
  return page.getByText(/Showing [\s\S]* Rows/)
}

function bodyRows(page: Page) {
  return page.locator('tbody tr')
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readPagination(page: Page) {
  const text = await page.getByTestId('table-state').textContent()
  const state = JSON.parse(text ?? '{}') as {
    pagination?: { pageIndex: number; pageSize: number }
  }

  return state.pagination
}

async function expectPagination(
  page: Page,
  expected: { pageIndex: number; pageSize: number },
) {
  await expect.poll(() => readPagination(page)).toEqual(expected)
}

async function getFirstBodyRowText(page: Page) {
  const text = await bodyRows(page).first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  await expect(table.locator('thead th')).toHaveCount(7)
  await expect(bodyRows(page)).toHaveCount(10)
  await expect(rowCountLine(page)).toHaveText('Showing 10 of 1,000 Rows')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(bodyRows(page).first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(bodyRows(page)).toHaveCount(10)

  expect(errors).toEqual([])
})

test('disables the first and previous buttons on the first page', async ({
  page,
}) => {
  const errors = await openExample(page)

  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expect(pageButton(page, '<<')).toBeDisabled()
  await expect(pageButton(page, '<')).toBeDisabled()
  await expect(pageButton(page, '>')).toBeEnabled()
  await expect(pageButton(page, '>>')).toBeEnabled()

  expect(errors).toEqual([])
})

test('advances and rewinds one page at a time', async ({ page }) => {
  const errors = await openExample(page)

  await expect(pageStatus(page)).toHaveText('1 of 100')

  await pageButton(page, '>').click()
  await expect(pageStatus(page)).toHaveText('2 of 100')
  await expectPagination(page, { pageIndex: 1, pageSize: 10 })
  // Reaching page two enables the backwards buttons.
  await expect(pageButton(page, '<<')).toBeEnabled()
  await expect(pageButton(page, '<')).toBeEnabled()
  // The controlled input tracks the page rather than going stale.
  await expect(goToPageInput(page)).toHaveValue('2')

  const secondPageFirstRow = await getFirstBodyRowText(page)

  await pageButton(page, '>').click()
  await expect(pageStatus(page)).toHaveText('3 of 100')

  await pageButton(page, '<').click()
  await expect(pageStatus(page)).toHaveText('2 of 100')
  // Returning to a page shows the same rows, so paging does not reshuffle.
  expect(await getFirstBodyRowText(page)).toBe(secondPageFirstRow)

  // The page window slides but its size and the total do not.
  await expect(bodyRows(page)).toHaveCount(10)
  await expect(rowCountLine(page)).toHaveText('Showing 10 of 1,000 Rows')

  expect(errors).toEqual([])
})

test('jumps to the last and first pages', async ({ page }) => {
  const errors = await openExample(page)

  await pageButton(page, '>>').click()
  await expect(pageStatus(page)).toHaveText('100 of 100')
  await expectPagination(page, { pageIndex: 99, pageSize: 10 })
  await expect(bodyRows(page)).toHaveCount(10)
  await expect(pageButton(page, '>')).toBeDisabled()
  await expect(pageButton(page, '>>')).toBeDisabled()
  await expect(pageButton(page, '<<')).toBeEnabled()
  await expect(pageButton(page, '<')).toBeEnabled()

  await pageButton(page, '<<').click()
  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })
  await expect(pageButton(page, '<<')).toBeDisabled()
  await expect(pageButton(page, '<')).toBeDisabled()

  expect(errors).toEqual([])
})

test('goes to an arbitrary page via the Go to page input', async ({ page }) => {
  const errors = await openExample(page)
  const input = goToPageInput(page)

  await expect(input).toHaveAttribute('min', '1')
  await expect(input).toHaveAttribute('max', '100')
  await expect(input).toHaveValue('1')

  await input.fill('42')
  await expect(pageStatus(page)).toHaveText('42 of 100')
  await expectPagination(page, { pageIndex: 41, pageSize: 10 })

  await input.fill('1')
  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expect(pageButton(page, '<')).toBeDisabled()

  // Clearing the field falls back to the first page rather than NaN.
  await input.fill('7')
  await expect(pageStatus(page)).toHaveText('7 of 100')
  await input.fill('')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })
  await expect(pageStatus(page)).toHaveText('1 of 100')

  expect(errors).toEqual([])
})

test('recomputes the page index when the page size changes', async ({
  page,
}) => {
  const errors = await openExample(page)
  const select = pageSizeSelect(page)

  await expect(select.locator('option')).toHaveText([
    ...PAGE_SIZES.map((size) => `Show ${size}`),
    'Show All',
  ])
  await expect(select).toHaveValue('10')

  await select.selectOption('20')
  await expect(bodyRows(page)).toHaveCount(20)
  await expect(pageStatus(page)).toHaveText('1 of 50')
  await expect(rowCountLine(page)).toHaveText('Showing 20 of 1,000 Rows')
  await expectPagination(page, { pageIndex: 0, pageSize: 20 })

  await select.selectOption('50')
  await expect(bodyRows(page)).toHaveCount(50)
  await expect(pageStatus(page)).toHaveText('1 of 20')
  await expect(rowCountLine(page)).toHaveText('Showing 50 of 1,000 Rows')

  // `setPageSize` keeps the row at the top of the page in view by deriving the
  // new page index from the old top row index, rather than resetting to page 1.
  await select.selectOption('10')
  await goToPageInput(page).fill('5')
  await expect(pageStatus(page)).toHaveText('5 of 100')

  // Top row index is 4 * 10 = 40, so 20 rows per page lands on page 3.
  await select.selectOption('20')
  await expect(pageStatus(page)).toHaveText('3 of 50')
  await expectPagination(page, { pageIndex: 2, pageSize: 20 })

  // Top row index is still 2 * 20 = 40, so 50 rows per page lands on page 1.
  await select.selectOption('50')
  await expect(pageStatus(page)).toHaveText('1 of 20')
  await expectPagination(page, { pageIndex: 0, pageSize: 50 })

  expect(errors).toEqual([])
})

test('shows all rows when the All page size is selected', async ({ page }) => {
  const errors = await openExample(page)
  const select = pageSizeSelect(page)

  await pageButton(page, '>').click()
  await expect(pageStatus(page)).toHaveText('2 of 100')

  await select.selectOption('Infinity')

  await expect(select).toHaveValue('Infinity')
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)
  await expect(pageStatus(page)).toHaveText('1 of 1')
  await expect(rowCountLine(page)).toHaveText(
    `Showing ${TOTAL_ROWS.toLocaleString('en-US')} of ${TOTAL_ROWS.toLocaleString('en-US')} Rows`,
  )
  await expect(pageButton(page, '<<')).toBeDisabled()
  await expect(pageButton(page, '<')).toBeDisabled()
  await expect(pageButton(page, '>')).toBeDisabled()
  await expect(pageButton(page, '>>')).toBeDisabled()

  expect(errors).toEqual([])
})

test('resets to the first page when data is regenerated', async ({ page }) => {
  const errors = await openExample(page)

  await goToPageInput(page).fill('5')
  await expect(pageStatus(page)).toHaveText('5 of 100')

  // `autoResetPageIndex` defaults to true, so new data returns to page one.
  await page.getByRole('button', { name: /^Regenerate Data$/i }).click()

  await expect(pageStatus(page)).toHaveText('1 of 100')
  await expectPagination(page, { pageIndex: 0, pageSize: 10 })
  await expect(rowCountLine(page)).toHaveText(
    `Showing 10 of ${TOTAL_ROWS.toLocaleString('en-US')} Rows`,
  )

  expect(errors).toEqual([])
})

import type { TradingBenchmarkController } from './trading-benchmark-controller'

export function startTableBenchmark(
  controller: TradingBenchmarkController,
): () => void {
  const tableBody = document.querySelector(
    '.market-panel [data-trading-table] tbody',
  )
  if (!tableBody) return () => undefined

  controller.monitor.resetDomMutations()
  const observer = new MutationObserver((records) => {
    controller.monitor.recordDomMutations(records.length)
  })
  observer.observe(tableBody, {
    attributes: true,
    attributeFilter: ['class', 'style'],
    characterData: true,
    childList: true,
    subtree: true,
  })
  return () => observer.disconnect()
}

import { batch, createAtom, createStore } from '@tanstack/store'
import { TRADING_COLUMN_COUNT } from '../table/trading-table'
import { FORCED_VIRTUALIZATION_ROW_COUNT } from '../table/trading-row-virtualizer'
import {
  BenchmarkMonitor,
  exposeTradingBenchmarkSnapshot,
  initialMetrics,
  longAnimationFramesSupported,
} from './benchmark-monitor'
import type { FeedMetrics } from './benchmark-monitor'
import type { MarketFeedController } from '../feed/market-feed-controller'
import type { RendererMode } from '../table/trading-table'
import type { VirtualScrollPreference } from '../table/trading-row-virtualizer'

export interface TradingBenchmarkState {
  requestedVirtualScrollMode: VirtualScrollPreference
  metrics: FeedMetrics
  mountedCells: number
  liveComponents: number
  longAnimationFramesSupported: boolean
}

export interface TradingBenchmarkActions {
  resetViewState: () => void
  setRendererMode: (mode: RendererMode) => void
  setVirtualScrollEnabled: (enabled: boolean) => void
  setRenderedRowCount: (count: number) => void
  selectSymbol: (symbol: string | null) => void
  resetMarket: () => void
}

const initialState: TradingBenchmarkState = {
  requestedVirtualScrollMode: 'auto',
  metrics: initialMetrics,
  mountedCells: 0,
  liveComponents: 0,
  longAnimationFramesSupported,
}

export class TradingBenchmarkController {
  readonly store = createStore<TradingBenchmarkState>(initialState)
  readonly renderAtoms = {
    selectedSymbol: createAtom<string | null>(null),
    rendererMode: createAtom<RendererMode>('stable'),
  }
  readonly monitor = new BenchmarkMonitor()
  readonly feed: MarketFeedController
  readonly actions: TradingBenchmarkActions

  readonly #runtime = {
    animationFrameId: 0,
    longAnimationFrameObserver: null as PerformanceObserver | null,
    stopObservingFeed: null as (() => void) | null,
  }

  constructor(feed: MarketFeedController) {
    this.feed = feed
    this.actions = {
      resetViewState: () => {
        this.renderAtoms.selectedSymbol.set(null)
        this.#patch({ requestedVirtualScrollMode: 'auto' })
      },
      setRendererMode: (mode) => {
        this.renderAtoms.rendererMode.set(mode)
      },
      setVirtualScrollEnabled: (enabled) => {
        if (
          this.feed.instrumentCount.get() >= FORCED_VIRTUALIZATION_ROW_COUNT
        ) {
          return
        }
        this.#patch({
          requestedVirtualScrollMode: enabled ? 'tanstack' : 'none',
        })
      },
      setRenderedRowCount: (count) => {
        const mountedCells = count * TRADING_COLUMN_COUNT
        if (mountedCells !== this.store.get().mountedCells) {
          this.#patch({ mountedCells })
        }
      },
      selectSymbol: (symbol) => {
        this.renderAtoms.selectedSymbol.set(symbol)
      },
      resetMarket: () => {
        batch(() => {
          this.monitor.reset()
          this.store.setState((state) => ({
            ...state,
            metrics: { ...initialMetrics },
            mountedCells: 0,
            liveComponents: 0,
          }))
          this.renderAtoms.selectedSymbol.set(null)
          this.feed.actions.reset()
        })
      },
    }
  }

  start(): () => void {
    const longAnimationFrameObserver = longAnimationFramesSupported
      ? new PerformanceObserver((entries) => {
          for (const entry of entries.getEntries()) {
            this.monitor.recordLongAnimationFrame(
              entry.duration,
              entry.startTime,
            )
          }
        })
      : null

    this.#runtime.longAnimationFrameObserver = longAnimationFrameObserver
    this.#runtime.stopObservingFeed = this.feed.observe({
      messageReceived: () => this.monitor.recordWorkerMessage(),
      mutationStarted: () => this.monitor.markCommitPending(),
      batchApplied: ({ tickCount, updateCount, supersededUpdateCount }) =>
        this.monitor.recordBatch(tickCount, updateCount, supersededUpdateCount),
      renderCommitted: () => this.monitor.recordDomCommit(),
    })
    longAnimationFrameObserver?.observe({
      type: 'long-animation-frame',
    })
    this.#runtime.animationFrameId = requestAnimationFrame(this.#benchmarkFrame)

    return () => this.stop()
  }

  stop(): void {
    cancelAnimationFrame(this.#runtime.animationFrameId)
    this.#runtime.longAnimationFrameObserver?.disconnect()
    this.#runtime.stopObservingFeed?.()
    this.#runtime.longAnimationFrameObserver = null
    this.#runtime.stopObservingFeed = null
  }

  readonly #benchmarkFrame = (now: number): void => {
    this.monitor.recordAnimationFrame(now)
    if (this.monitor.shouldPublish(now)) {
      this.#publishMetrics(this.monitor.publish(now))
    }
    this.#runtime.animationFrameId = requestAnimationFrame(this.#benchmarkFrame)
  }

  #patch(patch: Partial<TradingBenchmarkState>): void {
    this.store.setState((state) => ({ ...state, ...patch }))
  }

  #publishMetrics(metrics: FeedMetrics): void {
    const liveComponents =
      metrics.componentsCreated - metrics.componentsDestroyed
    this.#patch({
      metrics,
      liveComponents,
    })
    exposeTradingBenchmarkSnapshot(metrics, {
      mountedCells: this.store.get().mountedCells,
      liveComponents,
    })
  }
}

import { LitElement, html } from 'lit'
import { customElement } from 'lit/decorators.js'
import { TradingBenchmarkController } from './benchmark/trading-benchmark-controller'
import { MarketFeedController } from './feed/market-feed-controller'
import './shell/TradingShell'
import './index.css'

@customElement('realtime-trading-app')
export class RealtimeTradingApp extends LitElement {
  readonly #feed = new MarketFeedController()
  readonly #benchmark = new TradingBenchmarkController(this.#feed)
  readonly #stop = {
    feed: null as (() => void) | null,
    benchmark: null as (() => void) | null,
  }
  protected createRenderRoot() {
    return this
  }
  connectedCallback() {
    super.connectedCallback()
    this.#stop.feed = this.#feed.start()
    this.#stop.benchmark = this.#benchmark.start()
  }
  disconnectedCallback() {
    this.#stop.benchmark?.()
    this.#stop.feed?.()
    super.disconnectedCallback()
  }
  protected render() {
    return html`<trading-shell
      .controller=${this.#benchmark}
      .feed=${this.#feed}
    ></trading-shell>`
  }
}

import { html } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { repeat } from 'lit/directives/repeat.js'
import {
  feedSampleRateAt,
  feedSampleRateIndex,
  feedSampleRateOptions,
} from '../feed/feed-sample-rates'
import {
  FORCED_VIRTUALIZATION_ROW_COUNT,
  resolveVirtualScrollMode,
} from '../table/trading-row-virtualizer'
import { configuratorOptions } from './configurator-options'
import { ControllerElement } from './controller-element'
import './Diagnostics'
import './MetricsStrip'
import './SelectedInstrument'
import type { MarketFeedController } from '../feed/market-feed-controller'
import type { TradingBenchmarkController } from '../benchmark/trading-benchmark-controller'

const rate = new Intl.NumberFormat('en-US', {
  notation: 'compact',
  maximumFractionDigits: 1,
})
const value = (event: Event) =>
  (event.target as HTMLInputElement | HTMLSelectElement).value
const number = (event: Event) => Number(value(event))
const checked = (event: Event) => (event.target as HTMLInputElement).checked
const options = (
  items: ReadonlyArray<{
    readonly label: string
    readonly value: number | string
  }>,
  selectedValue: number | string,
) =>
  repeat(
    items,
    (item) => item.value,
    (item) =>
      html`<option
        value=${item.value}
        ?selected=${String(item.value) === String(selectedValue)}
      >
        ${item.label}
      </option>`,
  )

@customElement('trading-configurator')
export class Configurator extends ControllerElement {
  @property({ attribute: false }) controller!: TradingBenchmarkController
  @property({ attribute: false }) feed!: MarketFeedController
  protected firstUpdated() {
    this.observe(this.controller.store)
    this.observe(this.controller.renderAtoms.rendererMode)
    this.observe(this.feed.running)
    this.observe(this.feed.instrumentCount)
    this.observe(this.feed.targetTicksPerSecond)
    this.observe(this.feed.publishIntervalMs)
    this.observe(this.feed.updateSparklines)
    this.observe(this.feed.sparklineSampleIntervalMs)
  }
  protected render() {
    const feedState = {
      running: this.feed.running.get(),
      instrumentCount: this.feed.instrumentCount.get(),
      targetTicksPerSecond: this.feed.targetTicksPerSecond.get(),
      publishIntervalMs: this.feed.publishIntervalMs.get(),
      updateSparklines: this.feed.updateSparklines.get(),
      sparklineSampleIntervalMs: this.feed.sparklineSampleIntervalMs.get(),
    }
    const benchmark = this.controller.store.get()
    const forced = feedState.instrumentCount >= FORCED_VIRTUALIZATION_ROW_COUNT
    const virtualMode = resolveVirtualScrollMode(
      benchmark.requestedVirtualScrollMode,
      feedState.instrumentCount,
    )
    return html`<aside
      id="benchmark-configurator"
      class="configurator"
      aria-label="Benchmark configurator"
    >
      <header><span>CONFIGURATOR</span><small>RUN PARAMETERS</small></header>
      <trading-metrics-strip
        .controller=${this.controller}
      ></trading-metrics-strip>
      <section class="config-section" aria-labelledby="feed-settings">
        <h2 id="feed-settings">FEED</h2>
        <button
          class="primary-action"
          type="button"
          data-testid="feed-toggle"
          @click=${this.feed.actions.toggle}
        >
          ${feedState.running ? 'PAUSE FEED' : 'START FEED'}
        </button>
        <label class="field"
          ><span>Instruments (rows)</span
          ><select
            data-testid="instrument-count-select"
            .value=${String(feedState.instrumentCount)}
            @change=${(event: Event) => {
              this.controller.actions.resetViewState()
              this.feed.actions.setInstrumentCount(number(event))
            }}
          >
            ${options(
              configuratorOptions.instrumentCounts,
              feedState.instrumentCount,
            )}
          </select></label
        >
        <label class="field rate-field"
          ><span
            >Synthetic quote workload
            <strong data-testid="target-sample-rate"
              >${rate.format(feedState.targetTicksPerSecond)} samples/s</strong
            ></span
          ><input
            data-testid="target-rate-slider"
            type="range"
            min="0"
            max=${feedSampleRateOptions.length - 1}
            step="1"
            .value=${String(feedSampleRateIndex(feedState.targetTicksPerSecond))}
            @input=${(event: Event) => this.feed.actions.setTargetRate(feedSampleRateAt(number(event)))}
            @change=${(event: Event) => this.feed.actions.setTargetRate(feedSampleRateAt(number(event)))}
          /><small
            >Fixed worker-side workload levels. Samples are coalesced; this is
            not the message delivery rate.</small
          ></label
        >
        <label class="field"
          ><span>Worker delivery interval</span
          ><select
            data-testid="publish-interval-select"
            .value=${String(feedState.publishIntervalMs)}
            @change=${(event: Event) => this.feed.actions.setPublishInterval(number(event))}
          >
            ${options(
              configuratorOptions.workerDeliveryIntervals,
              feedState.publishIntervalMs,
            )}</select
          ><small
            >One coalesced worker message at this target cadence.</small
          ></label
        >
      </section>
      <section class="config-section" aria-labelledby="render-settings">
        <h2 id="render-settings">RENDER PATH</h2>
        <label class="field" data-testid="virtual-scroll-mode"
          ><span>Row rendering</span
          ><select
            data-testid="virtual-scroll-select"
            .value=${virtualMode}
            ?disabled=${forced}
            @change=${(event: Event) => this.controller.actions.setVirtualScrollEnabled(value(event) === 'tanstack')}
          >
            ${options(configuratorOptions.rowRenderingModes, virtualMode)}</select
          ><small
            >${forced ? 'TanStack Virtual is required and locked at 1,500 or more rows.' : 'Full DOM is the default below 200 rows; TanStack Virtual is the default from 200 rows and remains selectable.'}</small
          ></label
        >
        <label class="toggle-field"
          ><input
            type="checkbox"
            .checked=${this.controller.renderAtoms.rendererMode.get() === 'swap'}
            @change=${(event: Event) => this.controller.actions.setRendererMode(checked(event) ? 'swap' : 'stable')}
          /><span
            >Swap Tick component A ↔ B<small
              >destroy and recreate when direction changes</small
            ></span
          ></label
        >
        <label class="toggle-field"
          ><input
            type="checkbox"
            .checked=${feedState.updateSparklines}
            @change=${(event: Event) => this.feed.actions.setSparklineUpdates(checked(event))}
          /><span
            >Update intraday charts<small
              >sample rolling prices independently</small
            ></span
          ></label
        >
        <label class="field"
          ><span>Intraday chart sampling</span
          ><select
            data-testid="sparkline-sample-interval-select"
            .value=${String(feedState.sparklineSampleIntervalMs)}
            @change=${(event: Event) => this.feed.actions.setSparklineSampleInterval(number(event))}
          >
            ${options(
              configuratorOptions.intradaySamplingIntervals,
              feedState.sparklineSampleIntervalMs,
            )}
          </select></label
        >
      </section>
      <section class="config-section" aria-labelledby="stress-actions">
        <h2 id="stress-actions">STRESS ACTIONS</h2>
        <div class="action-grid">
          <button type="button" @click=${this.feed.actions.runBurst}>
            RUN 25K BURST</button
          ><button type="button" @click=${this.controller.actions.resetMarket}>
            RESET SESSION
          </button>
        </div>
      </section>
      <trading-diagnostics .controller=${this.controller}></trading-diagnostics
      ><trading-selected-instrument
        .controller=${this.controller}
        .feed=${this.feed}
      ></trading-selected-instrument>
    </aside>`
  }
}

import { html } from 'lit'
import { customElement, property } from 'lit/decorators.js'
import { ControllerElement } from './controller-element'
import type { TradingBenchmarkController } from '../benchmark/trading-benchmark-controller'

const integer = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 })
@customElement('trading-market-statusbar')
export class MarketStatusbar extends ControllerElement {
  @property({ attribute: false }) controller!: TradingBenchmarkController
  protected firstUpdated() {
    this.observe(this.controller.store)
  }
  protected render() {
    const state = this.controller.store.get()
    return html`<footer class="market-statusbar">
      <span
        >MESSAGE SAMPLES
        <strong>${integer.format(state.metrics.lastBatchSize)}</strong></span
      ><span
        >CHANGED ROWS
        <strong>${integer.format(state.metrics.lastUpdateCount)}</strong></span
      ><span>HOSTS <strong>${integer.format(state.mountedCells)}</strong></span
      ><span
        >COMPONENTS
        <strong>${integer.format(state.liveComponents)}</strong></span
      >
    </footer>`
  }
}

