import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

const TOTAL_ROWS = 10

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return errors
}

function bodyRows(page: Page) {
  return page.locator('tbody tr')
}

/** Every data row carries an expander in its first cell. */
function rowExpander(page: Page, index: number) {
  return bodyRows(page).nth(index).getByRole('button')
}

/** The sub component renders the row's own data as JSON inside a `<pre>`. */
function subComponents(page: Page) {
  return page.locator('tbody pre')
}

async function readSubComponentJson(page: Page, index: number) {
  const text = await subComponents(page).nth(index).textContent()
  return JSON.parse(text ?? '{}') as Record<string, unknown>
}

async function getFirstBodyRowText(page: Page) {
  const text = await bodyRows(page).first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)
  // Nothing is expanded, so no sub component rows exist yet.
  await expect(subComponents(page)).toHaveCount(0)
  await expect(rowExpander(page, 0)).toHaveText('👉')

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(bodyRows(page).first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)

  expect(errors).toEqual([])
})

test('expands a row to reveal its sub component', async ({ page }) => {
  const errors = await openExample(page)

  await rowExpander(page, 0).click()

  await expect(rowExpander(page, 0)).toHaveText('👇')
  await expect(subComponents(page)).toHaveCount(1)
  // The sub component adds a full width row directly beneath its parent.
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS + 1)
  await expect(bodyRows(page).nth(1).locator('td')).toHaveCount(1)

  await rowExpander(page, 0).click()

  await expect(rowExpander(page, 0)).toHaveText('👉')
  await expect(subComponents(page)).toHaveCount(0)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS)

  expect(errors).toEqual([])
})

test('renders the expanded row own data in the sub component', async ({
  page,
}) => {
  const errors = await openExample(page)

  // Read a value straight out of the row before opening it, so the sub
  // component can be checked against its own parent rather than any row.
  const ageCell = await bodyRows(page)
    .first()
    .locator('td')
    .nth(3)
    .textContent()

  await rowExpander(page, 0).click()
  await expect(subComponents(page)).toHaveCount(1)

  const original = await readSubComponentJson(page, 0)
  expect(original['age']).toBe(Number(ageCell?.trim()))
  expect(original).toHaveProperty('firstName')
  expect(original).toHaveProperty('status')

  expect(errors).toEqual([])
})

test('keeps several sub components open at once', async ({ page }) => {
  const errors = await openExample(page)

  await rowExpander(page, 0).click()
  await expect(subComponents(page)).toHaveCount(1)

  // Row 1 is now the first sub component row, so the next data row is row 2.
  await rowExpander(page, 2).click()

  await expect(subComponents(page)).toHaveCount(2)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS + 2)
  await expect(rowExpander(page, 0)).toHaveText('👇')
  await expect(rowExpander(page, 2)).toHaveText('👇')

  // Collapsing one leaves the other open.
  await rowExpander(page, 0).click()

  await expect(subComponents(page)).toHaveCount(1)
  await expect(bodyRows(page)).toHaveCount(TOTAL_ROWS + 1)

  expect(errors).toEqual([])
})

import { customElement, state } from 'lit/decorators.js'
import { LitElement, html } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import {
  FlexRender,
  TableController,
  columnResizingFeature,
  columnSizingFeature,
  columnVisibilityFeature,
  createSortedRowModel,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_text,
  tableFeatures,
} from '@tanstack/lit-table'
import { styleMap } from 'lit/directives/style-map.js'
import { Ref, createRef, ref } from 'lit/directives/ref.js'
import { VirtualizerController } from '@tanstack/lit-virtual'
import { Person, makeColumns, makeData } from './makeData.ts'
import type { ColumnDef } from '@tanstack/lit-table'

const features = tableFeatures({
  columnResizingFeature,
  columnSizingFeature,
  columnVisibilityFeature,
  rowSortingFeature,
  sortedRowModel: createSortedRowModel(),
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    text: sortFn_text,
  },
})

const DEFAULT_ROW_COUNT = 1_000
const DEFAULT_COLUMN_COUNT = 1_000
const STRESS_ROW_COUNT = 10_000
const STRESS_COLUMN_COUNT = 10_000

const createColumns = (columnCount: number) =>
  makeColumns(columnCount) as Array<ColumnDef<typeof features, Person>>

@customElement('lit-table-example')
class LitTableExample extends LitElement {
  private tableController = new TableController<typeof features, Person>(this)

  private tableContainerRef: Ref = createRef()

  @state()
  private _columns = createColumns(DEFAULT_COLUMN_COUNT)

  @state()
  private _data = makeData(DEFAULT_ROW_COUNT, this._columns)

  private columnVirtualizerController?: VirtualizerController<Element, Element>
  private rowVirtualizerController?: VirtualizerController<Element, Element>

  private _sizingSub?: { unsubscribe: () => void }

  connectedCallback() {
    super.connectedCallback()
  }

  disconnectedCallback() {
    super.disconnectedCallback()
    this._sizingSub?.unsubscribe()
    this._sizingSub = undefined
  }

  private _ensureVirtualizers(
    visibleColumnCount: number,
    rowCount: number,
    visibleColumns: Array<any>,
  ) {
    // Create column virtualizer once we have the scroll element
    if (!this.columnVirtualizerController) {
      this.columnVirtualizerController = new VirtualizerController(this, {
        count: visibleColumnCount,
        estimateSize: (index: number) =>
          visibleColumns[index]?.getSize() ?? 150,
        getScrollElement: () => this.tableContainerRef.value!,
        horizontal: true,
        overscan: 3,
      })
    }

    if (!this.rowVirtualizerController) {
      this.rowVirtualizerController = new VirtualizerController(this, {
        count: rowCount,
        estimateSize: () => 33,
        getScrollElement: () => this.tableContainerRef.value!,
        overscan: 5,
      })
    }
  }

  private _refreshData() {
    const nextColumns = createColumns(DEFAULT_COLUMN_COUNT)
    this._columns = nextColumns
    this._data = makeData(DEFAULT_ROW_COUNT, nextColumns)
  }

  private _stressTestRows() {
    this._data = makeData(STRESS_ROW_COUNT, this._columns)
  }

  private _stressTestColumns() {
    const nextColumns = createColumns(STRESS_COLUMN_COUNT)
    this._columns = nextColumns
    this._data = makeData(this._data.length, nextColumns)
  }

  protected render() {
    const table = this.tableController.table(
      {
        features,
        columns: this._columns,
        data: this._data,
        columnResizeMode: 'onChange',
      },
      // header/cell widths render via header.getSize(), so the host must
      // re-render when column sizing changes
      (state) => ({ columnSizing: state.columnSizing }),
    )

    const visibleColumns = table.getVisibleLeafColumns()
    const { rows } = table.getRowModel()

    this._ensureVirtualizers(visibleColumns.length, rows.length, visibleColumns)

    const columnVirtualizer = this.columnVirtualizerController?.getVirtualizer()
    const rowVirtualizer = this.rowVirtualizerController?.getVirtualizer()

    if (!columnVirtualizer || !rowVirtualizer) {
      return html`<div>Loading...</div>`
    }

    // re-measure virtual column widths when a column is resized so the
    // virtualizer's scroll math stays in sync with the rendered widths
    if (!this._sizingSub) {
      this._sizingSub = table.atoms.columnSizing.subscribe(() => {
        this.columnVirtualizerController?.getVirtualizer().measure()
      })
    }

    // Update virtualizer counts
    columnVirtualizer.setOptions({
      ...columnVirtualizer.options,
      count: visibleColumns.length,
      estimateSize: (index: number) => visibleColumns[index]?.getSize() ?? 150,
    })
    rowVirtualizer.setOptions({
      ...rowVirtualizer.options,
      count: rows.length,
    })

    const virtualColumns = columnVirtualizer.getVirtualItems()
    const virtualRows = rowVirtualizer.getVirtualItems()

    let virtualPaddingLeft: number | undefined
    let virtualPaddingRight: number | undefined

    if (virtualColumns.length > 0) {
      virtualPaddingLeft = virtualColumns[0]?.start ?? 0
      virtualPaddingRight =
        columnVirtualizer.getTotalSize() -
        (virtualColumns[virtualColumns.length - 1]?.end ?? 0)
    }

    return html`
      <div class="app">
        <div>(${this._columns.length.toLocaleString()} columns)</div>
        <div>(${this._data.length.toLocaleString()} rows)</div>
        <button @click="${() => this._refreshData()}">Regenerate Data</button>
        <button @click="${() => this._stressTestRows()}">
          Stress Test (10k rows)
        </button>
        <button @click="${() => this._stressTestColumns()}">
          Stress Test (10k columns)
        </button>
        <div
          class="container"
          ${ref(this.tableContainerRef)}
          style="${styleMap({
            overflow: 'auto',
            position: 'relative',
            height: '800px',
          })}"
        >
          <table style="display: grid">
            <thead
              style="${styleMap({
                display: 'grid',
                position: 'sticky',
                top: '0',
                zIndex: '1',
              })}"
            >
              ${repeat(
                table.getHeaderGroups(),
                (headerGroup) => headerGroup.id,
                (headerGroup) => html`
                  <tr style="${styleMap({ display: 'flex', width: '100%' })}">
                    ${
                      virtualPaddingLeft
                        ? html`<th
                            style="${styleMap({
                              display: 'flex',
                              width: `${virtualPaddingLeft}px`,
                            })}"
                          ></th>`
                        : null
                    }
                    ${repeat(
                      virtualColumns,
                      (vc) => vc.index,
                      (virtualColumn) => {
                        const header = headerGroup.headers[virtualColumn.index]
                        return html`
                          <th
                            style="${styleMap({
                              display: 'flex',
                              position: 'relative',
                              width: `${header.getSize()}px`,
                            })}"
                          >
                            <div
                              class="${
                                header.column.getCanSort()
                                  ? 'sortable-header'
                                  : ''
                              }"
                              @click="${header.column.getToggleSortingHandler()}"
                            >
                              ${FlexRender({ header })}
                              ${
                                {
                                  asc: ' 🔼',
                                  desc: ' 🔽',
                                }[header.column.getIsSorted() as string] ?? null
                              }
                            </div>
                            <div
                              @dblclick="${() => header.column.resetSize()}"
                              @mousedown="${header.getResizeHandler()}"
                              @touchstart="${header.getResizeHandler()}"
                              class="resizer ${
                                header.column.getIsResizing()
                                  ? 'isResizing'
                                  : ''
                              }"
                            ></div>
                          </th>
                        `
                      },
                    )}
                    ${
                      virtualPaddingRight
                        ? html`<th
                            style="${styleMap({
                              display: 'flex',
                              width: `${virtualPaddingRight}px`,
                            })}"
                          ></th>`
                        : null
                    }
                  </tr>
                `,
              )}
            </thead>
            <tbody
              style="${styleMap({
                display: 'grid',
                height: `${rowVirtualizer.getTotalSize()}px`,
                position: 'relative',
              })}"
            >
              ${repeat(
                virtualRows,
                (item) => item.key,
                (virtualRow) => {
                  const row = rows[virtualRow.index]
                  const visibleCells = row.getVisibleCells()
                  return html`
                    <tr
                      data-index="${virtualRow.index}"
                      style="${styleMap({
                        display: 'flex',
                        position: 'absolute',
                        transform: `translateY(${virtualRow.start}px)`,
                        width: '100%',
                      })}"
                      ${ref((node) =>
                        rowVirtualizer.measureElement(node ?? null),
                      )}
                    >
                      ${
                        virtualPaddingLeft
                          ? html`<td
                              style="${styleMap({
                                display: 'flex',
                                width: `${virtualPaddingLeft}px`,
                              })}"
                            ></td>`
                          : null
                      }
                      ${repeat(
                        virtualColumns,
                        (vc) => vc.index,
                        (virtualColumn) => {
                          const cell = visibleCells[virtualColumn.index]
                          return html`
                            <td
                              style="${styleMap({
                                display: 'flex',
                                width: `${cell.column.getSize()}px`,
                              })}"
                            >
                              ${FlexRender({ cell })}
                            </td>
                          `
                        },
                      )}
                      ${
                        virtualPaddingRight
                          ? html`<td
                              style="${styleMap({
                                display: 'flex',
                                width: `${virtualPaddingRight}px`,
                              })}"
                            ></td>`
                          : null
                      }
                    </tr>
                  `
                },
              )}
            </tbody>
          </table>
        </div>
      </div>

      <style>
        html {
          font-family: sans-serif;
          font-size: 14px;
        }

        table {
          font-family: arial, sans-serif;
          table-layout: fixed;
        }

        thead {
          background: lightgray;
        }

        tr {
          border-bottom: 1px solid lightgray;
        }

        th {
          border-bottom: 1px solid lightgray;
          border-right: 1px solid lightgray;
          padding: 2px 4px;
          text-align: left;
        }

        td {
          padding: 6px;
        }

        .container {
          border: 1px solid lightgray;
          margin: 1rem auto;
        }

        .resizer {
          position: absolute;
          top: 0;
          height: 100%;
          right: 0;
          width: 5px;
          background: rgba(0, 0, 0, 0.5);
          cursor: col-resize;
          user-select: none;
          touch-action: none;
        }

        .resizer.isResizing {
          background: blue;
          opacity: 1;
        }

        @media (hover: hover) {
          .resizer {
            opacity: 0;
          }

          *:hover > .resizer {
            opacity: 1;
