import { faker } from '@faker-js/faker'

export const makeColumns = (num: number) =>
  [...Array(num)].map((_, i) => ({
    accessorKey: i.toString(),
    header: 'Column ' + i.toString(),
    size: Math.floor(Math.random() * 150) + 100,
  }))

export const makeData = (num: number, columns: Array<any>) =>
  [...Array(num)].map(() => ({
    ...Object.fromEntries(
      columns.map((col: any) => [col.accessorKey, faker.person.firstName()]),
    ),
  }))

export type Person = ReturnType<typeof makeData>[0]

import { customElement, state } from 'lit/decorators.js'
import { LitElement, html } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import {
  FlexRender,
  TableController,
  columnSizingFeature,
  createSortedRowModel,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_datetime,
  sortFn_text,
  tableFeatures,
} from '@tanstack/lit-table'
import { styleMap } from 'lit/directives/style-map.js'
import { Ref, createRef, ref } from 'lit/directives/ref.js'
import { VirtualizerController } from '@tanstack/lit-virtual'
import { fetchData } from './makeData.ts'
import type { Person } from './makeData.ts'
import type { ColumnDef, SortingState } from '@tanstack/lit-table'

const fetchSize = 50

const features = tableFeatures({
  columnSizingFeature,
  rowSortingFeature,
  sortedRowModel: createSortedRowModel(),
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    datetime: sortFn_datetime,
    text: sortFn_text,
  },
})

const columns: Array<ColumnDef<typeof features, Person>> = [
  {
    accessorKey: 'id',
    header: 'ID',
    size: 60,
  },
  {
    accessorKey: 'firstName',
    cell: (info) => info.getValue(),
  },
  {
    accessorFn: (row) => row.lastName,
    id: 'lastName',
    cell: (info) => info.getValue(),
    header: () => html`<span>Last Name</span>`,
  },
  {
    accessorKey: 'age',
    header: () => 'Age',
    size: 50,
  },
  {
    accessorKey: 'visits',
    header: () => html`<span>Visits</span>`,
    size: 50,
  },
  {
    accessorKey: 'status',
    header: 'Status',
  },
  {
    accessorKey: 'progress',
    header: 'Profile Progress',
    size: 80,
  },
  {
    accessorKey: 'createdAt',
    header: 'Created At',
    cell: (info) => info.getValue<Date>().toLocaleString(),
    size: 200,
  },
]

@customElement('lit-table-example')
class LitTableExample extends LitElement {
  private tableController = new TableController<typeof features, Person>(this)

  private tableContainerRef: Ref = createRef()

  private rowVirtualizerController!: VirtualizerController<Element, Element>

  @state()
  private _data: Array<Person> = []

  @state()
  private _isFetching = false

  @state()
  private _totalRowCount = 0

  @state()
  private _sorting: SortingState = []

  connectedCallback() {
    super.connectedCallback()
    // Fetch initial data
    this._fetchMoreData()
  }

  private async _fetchMoreData() {
    if (this._isFetching) return

    this._isFetching = true

    try {
      const response = await fetchData(
        this._data.length,
        fetchSize,
        this._sorting,
      )
      this._data = [...this._data, ...response.data]
      this._totalRowCount = response.meta.totalRowCount
    } finally {
      this._isFetching = false
    }
  }

  private async _refetchData() {
    this._isFetching = true
    this._data = []

    try {
      const response = await fetchData(0, fetchSize, this._sorting)
      this._data = response.data
      this._totalRowCount = response.meta.totalRowCount
    } finally {
      this._isFetching = false
    }
  }

  private _handleScroll(e: Event) {
    const target = e.currentTarget as HTMLDivElement
    const { scrollHeight, scrollTop, clientHeight } = target
    if (
      scrollHeight - scrollTop - clientHeight < 500 &&
      !this._isFetching &&
      this._data.length < this._totalRowCount
    ) {
      this._fetchMoreData()
    }
  }

  protected render() {
    const table = this.tableController.table(
      {
        features,
        columns,
        data: this._data,
        state: {
          sorting: this._sorting,
        },
        manualSorting: true,
        onSortingChange: (updater) => {
          const newSorting =
            typeof updater === 'function' ? updater(this._sorting) : updater
          this._sorting = newSorting
          // Reset data and refetch when sorting changes
          this._refetchData()
          // Scroll back to top
          if (this.tableContainerRef.value) {
            this.tableContainerRef.value.scrollTop = 0
          }
        },
      },
      () => ({}),
    )

    const { rows } = table.getRowModel()

    if (!this.rowVirtualizerController) {
      this.rowVirtualizerController = new VirtualizerController(this, {
        count: rows.length,
        estimateSize: () => 33,
        getScrollElement: () => this.tableContainerRef.value!,
        overscan: 5,
      })
    }

    const virtualizer = this.rowVirtualizerController.getVirtualizer()

    // Update count when rows change
    virtualizer.setOptions({
      ...virtualizer.options,
      count: rows.length,
    })

    const virtualRows = virtualizer.getVirtualItems()

    return html`
      <div class="app">
        (${this._data.length.toLocaleString()} of
        ${this._totalRowCount.toLocaleString()} rows fetched)
        <div
          class="container"
          ${ref(this.tableContainerRef)}
          @scroll="${this._handleScroll}"
          style="${styleMap({
            overflow: 'auto',
            position: 'relative',
            height: '600px',
          })}"
        >
