import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

/** Leaf columns in their declared order. The toggle panel labels each by id. */
const LEAF_COLUMNS = [
  'firstName',
  'lastName',
  'age',
  'visits',
  'status',
  'progress',
]

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.goto(server.url)

  return errors
}

function shuffleButton(page: Page) {
  return page.getByRole('button', { name: 'Shuffle Columns' })
}

function columnToggle(page: Page, label: string) {
  return page.getByLabel(label, { exact: true })
}

/** Header rows run group to leaf, so the leaf row holds the visible columns. */
function leafHeaderCells(page: Page) {
  return page.locator('thead tr').last().locator('th')
}

async function readHeaderOrder(page: Page) {
  const texts = await leafHeaderCells(page).allTextContents()
  return texts.map((text) => text.trim())
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readState(page: Page) {
  const text = await page.getByTestId('table-state').textContent()

  return JSON.parse(text ?? '{}') as {
    columnOrder?: Array<string>
    columnVisibility?: Record<string, boolean>
  }
}

async function getFirstBodyRowText(page: Page) {
  const text = await page.locator('tbody tr').first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  await expect(leafHeaderCells(page)).toHaveCount(LEAF_COLUMNS.length)
  await expect(page.locator('tbody tr')).toHaveCount(20)
  await expect(shuffleButton(page)).toBeVisible()
  // No explicit order yet, so the columns render as declared.
  await expect
    .poll(async () => (await readState(page)).columnOrder ?? [])
    .toEqual([])

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(page.locator('tbody tr').first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(page.locator('tbody tr')).toHaveCount(20)

  expect(errors).toEqual([])
})

test('shuffles the columns into a new order', async ({ page }) => {
  const errors = await openExample(page)
  const before = await readHeaderOrder(page)

  await shuffleButton(page).click()

  await expect
    .poll(async () => (await readState(page)).columnOrder ?? [])
    .toHaveLength(LEAF_COLUMNS.length)

  const after = await readHeaderOrder(page)

  // Shuffling permutes the columns: same set, different sequence.
  expect([...after].sort()).toEqual([...before].sort())
  expect(after).not.toEqual(before)

  const order = (await readState(page)).columnOrder ?? []
  expect([...order].sort()).toEqual([...LEAF_COLUMNS].sort())

  expect(errors).toEqual([])
})

test('reorders the body cells to match the headers', async ({ page }) => {
  const errors = await openExample(page)

  await shuffleButton(page).click()
  await expect
    .poll(async () => (await readState(page)).columnOrder ?? [])
    .toHaveLength(LEAF_COLUMNS.length)

  const order = (await readState(page)).columnOrder ?? []
  const footerOrder = (
    await page.locator('tfoot tr').first().locator('th').allTextContents()
  ).map((text) => text.trim())

  // The footer renders raw column ids, so it must match the shuffled order
  // exactly. That proves the cells moved with their headers.
  expect(footerOrder).toEqual(order)

  expect(errors).toEqual([])
})

test('keeps the shuffled order when a column is hidden', async ({ page }) => {
  const errors = await openExample(page)

  await shuffleButton(page).click()
  await expect
    .poll(async () => (await readState(page)).columnOrder ?? [])
    .toHaveLength(LEAF_COLUMNS.length)

  const order = (await readState(page)).columnOrder ?? []

  await columnToggle(page, 'age').uncheck()

  await expect
    .poll(async () => (await readState(page)).columnVisibility ?? {})
    .toEqual({ age: false })
  await expect(leafHeaderCells(page)).toHaveCount(LEAF_COLUMNS.length - 1)

  // Hiding removes a column from the render without disturbing the rest.
  const footerOrder = (
    await page.locator('tfoot tr').first().locator('th').allTextContents()
  ).map((text) => text.trim())
  expect(footerOrder).toEqual(order.filter((id) => id !== 'age'))

  expect(errors).toEqual([])
})

test('keeps the shuffled order when data is regenerated', async ({ page }) => {
  const errors = await openExample(page)

  await shuffleButton(page).click()
  await expect
    .poll(async () => (await readState(page)).columnOrder ?? [])
    .toHaveLength(LEAF_COLUMNS.length)

  const order = await readHeaderOrder(page)

  // Column order lives in table state, so replacing the rows must not reset it.
  await page.getByRole('button', { name: /^Regenerate Data$/i }).click()

  await expect(page.locator('tbody tr')).toHaveCount(20)
  expect(await readHeaderOrder(page)).toEqual(order)

  expect(errors).toEqual([])
})

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

const LEAF_COUNT = 6

/** The three tables render the start pinned, unpinned and end pinned columns. */
const START_TABLE = 0
const CENTER_TABLE = 1
const END_TABLE = 2

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.goto(server.url)

  return errors
}

function tableAt(page: Page, index: number) {
  return page.locator('table.outlined-table').nth(index)
}

/** Header rows run group to leaf, so the leaf row holds the data columns. */
function leafHeaderCells(page: Page, tableIndex: number) {
  return tableAt(page, tableIndex).locator('thead tr').last().locator('th')
}

function leafHeader(page: Page, tableIndex: number, name: string) {
  return leafHeaderCells(page, tableIndex).filter({ hasText: name })
}

/** An unpinned header offers `<=` and `=>`; a pinned one swaps in `X`. */
function pinButton(
  page: Page,
  tableIndex: number,
  name: string,
  label: '<=' | 'X' | '=>',
) {
  return leafHeader(page, tableIndex, name).getByRole('button', {
    name: label,
    exact: true,
  })
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readColumnPinning(page: Page) {
  const text = await page.getByTestId('table-state').textContent()
  const state = JSON.parse(text ?? '{}') as {
    columnPinning?: { start?: Array<string>; end?: Array<string> }
  }

  return {
    start: state.columnPinning?.start ?? [],
    end: state.columnPinning?.end ?? [],
  }
}

async function leafCount(page: Page, tableIndex: number) {
  return leafHeaderCells(page, tableIndex).count()
}

async function getFirstBodyRowText(page: Page) {
  const text = await tableAt(page, CENTER_TABLE)
    .locator('tbody tr')
    .first()
    .textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)

  // One table per pinning region, even when two of them are empty.
  await expect(page.locator('table.outlined-table')).toHaveCount(3)
  expect(await readColumnPinning(page)).toEqual({ start: [], end: [] })
  // Nothing is pinned, so every column lives in the centre table.
  expect(await leafCount(page, START_TABLE)).toBe(0)
  expect(await leafCount(page, CENTER_TABLE)).toBe(LEAF_COUNT)
  expect(await leafCount(page, END_TABLE)).toBe(0)

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(
    tableAt(page, CENTER_TABLE).locator('tbody tr').first(),
  ).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)

  expect(errors).toEqual([])
})

test('moves a column into the start table when pinned', async ({ page }) => {
  const errors = await openExample(page)

  await pinButton(page, CENTER_TABLE, 'Visits', '<=').click()

  await expect
    .poll(async () => (await readColumnPinning(page)).start)
    .toEqual(['visits'])
  // The column leaves the centre table and appears in the start table, so the
  // split is driven by pinning state rather than by a separate column list.
  await expect.poll(() => leafCount(page, START_TABLE)).toBe(1)
  expect(await leafCount(page, CENTER_TABLE)).toBe(LEAF_COUNT - 1)
  await expect(leafHeaderCells(page, START_TABLE)).toContainText(['Visits'])
  await expect(leafHeaderCells(page, CENTER_TABLE)).not.toContainText([
    'Visits',
  ])

  expect(errors).toEqual([])
})

test('moves a column into the end table when pinned', async ({ page }) => {
  const errors = await openExample(page)

  await pinButton(page, CENTER_TABLE, 'Age', '=>').click()

  await expect
    .poll(async () => (await readColumnPinning(page)).end)
    .toEqual(['age'])
  await expect.poll(() => leafCount(page, END_TABLE)).toBe(1)
  expect(await leafCount(page, CENTER_TABLE)).toBe(LEAF_COUNT - 1)
  await expect(leafHeaderCells(page, END_TABLE)).toContainText(['Age'])

  expect(errors).toEqual([])
})

test('returns a column to the centre table when unpinned', async ({ page }) => {
  const errors = await openExample(page)

  await pinButton(page, CENTER_TABLE, 'Visits', '<=').click()
  await expect.poll(() => leafCount(page, START_TABLE)).toBe(1)

  await pinButton(page, START_TABLE, 'Visits', 'X').click()

  await expect
    .poll(() => readColumnPinning(page))
    .toEqual({ start: [], end: [] })
  await expect.poll(() => leafCount(page, START_TABLE)).toBe(0)
  expect(await leafCount(page, CENTER_TABLE)).toBe(LEAF_COUNT)

  expect(errors).toEqual([])
})

test('keeps every table showing the same rows', async ({ page }) => {
  const errors = await openExample(page)

  await pinButton(page, CENTER_TABLE, 'Visits', '<=').click()
  await expect.poll(() => leafCount(page, START_TABLE)).toBe(1)
  await pinButton(page, CENTER_TABLE, 'Age', '=>').click()
  await expect.poll(() => leafCount(page, END_TABLE)).toBe(1)

  // The three tables are one table split three ways, so their bodies must stay
  // row for row aligned or the split would visibly tear.
  const rowCounts = await Promise.all(
    [START_TABLE, CENTER_TABLE, END_TABLE].map((index) =>
      tableAt(page, index).locator('tbody tr').count(),
    ),
  )

  expect(rowCounts[0]).toBeGreaterThan(0)
  expect(rowCounts[1]).toBe(rowCounts[0])
  expect(rowCounts[2]).toBe(rowCounts[0])

  expect(errors).toEqual([])
})

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.goto(server.url)

  return errors
}

/** Header rows run group to leaf, so the leaf row holds the data columns. */
function leafHeaderCells(page: Page) {
  return page.locator('thead tr').last().locator('th')
}

function leafHeader(page: Page, name: string) {
  return leafHeaderCells(page).filter({ hasText: name })
}

/** An unpinned header offers `<=` and `=>`; a pinned one swaps in `X`. */
function pinButton(page: Page, name: string, label: '<=' | 'X' | '=>') {
  return leafHeader(page, name).getByRole('button', {
    name: label,
    exact: true,
  })
}

function scrollContainer(page: Page) {
  return page.locator('.table-container')
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readColumnPinning(page: Page) {
  const text = await page.getByTestId('table-state').textContent()
  const state = JSON.parse(text ?? '{}') as {
    columnPinning?: { start?: Array<string>; end?: Array<string> }
  }

  return {
    start: state.columnPinning?.start ?? [],
    end: state.columnPinning?.end ?? [],
  }
}

/**
 * Scrolls the container as far right as it goes and returns the distance
 * travelled. How much room there is depends on the viewport, so the tests work
 * from the real value rather than assuming one.
 */
async function scrollToEnd(page: Page) {
  const maxScroll = await scrollContainer(page).evaluate(
    (element) => element.scrollWidth - element.clientWidth,
  )

  expect(maxScroll).toBeGreaterThan(50)

  await scrollContainer(page).evaluate((element) => {
    element.scrollLeft = element.scrollWidth
    element.dispatchEvent(new Event('scroll'))
  })

  await expect
    .poll(() => scrollContainer(page).evaluate((element) => element.scrollLeft))
    .toBeGreaterThan(maxScroll - 2)

  return maxScroll
}

async function getFirstBodyRowText(page: Page) {
  const text = await page.locator('tbody tr').first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)

  await expect(page.locator('table').first()).toBeVisible()
  await expect(page.locator('tbody tr')).toHaveCount(20)
  await expect(scrollContainer(page)).toBeVisible()
  expect(await readColumnPinning(page)).toEqual({ start: [], end: [] })
  // Unpinned columns scroll with the rest, so they are not sticky.
  await expect(leafHeaderCells(page).first()).toHaveCSS('position', 'relative')

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(page.locator('tbody tr').first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(page.locator('tbody tr')).toHaveCount(20)

  expect(errors).toEqual([])
})

test('makes a pinned column sticky', async ({ page }) => {
  const errors = await openExample(page)

  await pinButton(page, 'Visits', '<=').click()

  await expect
    .poll(async () => (await readColumnPinning(page)).start)
    .toEqual(['visits'])
  // Pinning switches the cell from relative to sticky and gives it an offset,
  // which is what actually holds it in place while the rest scrolls.
  await expect(leafHeader(page, 'Visits')).toHaveCSS('position', 'sticky')
  await expect(leafHeader(page, 'Visits')).toHaveCSS('left', '0px')

  expect(errors).toEqual([])
})

test('holds a start pinned column in place while scrolling', async ({
  page,
}) => {
  const errors = await openExample(page)

  await pinButton(page, 'Visits', '<=').click()
  await expect(leafHeader(page, 'Visits')).toHaveCSS('position', 'sticky')

  const pinnedBefore = await leafHeader(page, 'Visits').boundingBox()
  const unpinnedBefore = await leafHeader(page, 'Status').boundingBox()

  const scrolled = await scrollToEnd(page)

  const pinnedAfter = await leafHeader(page, 'Visits').boundingBox()
  const unpinnedAfter = await leafHeader(page, 'Status').boundingBox()

  // The pinned header stays put while its unpinned neighbour travels left by
  // the full scroll distance. That difference is the whole point of sticky.
  expect(Math.abs((pinnedAfter?.x ?? 0) - (pinnedBefore?.x ?? 0))).toBeLessThan(
    2,
  )
  expect((unpinnedBefore?.x ?? 0) - (unpinnedAfter?.x ?? 0)).toBeGreaterThan(
    scrolled - 2,
  )

  expect(errors).toEqual([])
})

test('unpins a column back into the scrolling area', async ({ page }) => {
  const errors = await openExample(page)

  await pinButton(page, 'Visits', '<=').click()
  await expect(leafHeader(page, 'Visits')).toHaveCSS('position', 'sticky')

  await pinButton(page, 'Visits', 'X').click()

  await expect
    .poll(() => readColumnPinning(page))
    .toEqual({ start: [], end: [] })
  await expect(leafHeader(page, 'Visits')).toHaveCSS('position', 'relative')

  expect(errors).toEqual([])
})

