function RowSubmitTableRow({
  row,
  onSave,
}: {
  row: Row<typeof appFeatures, FormRow>
  onSave: (originalRow: FormRow, value: FormRow) => void
}) {
  const form = useAppForm({
    defaultValues: row.original,
    onSubmit: ({ value }) => {
      onSave(row.original, value)
      form.reset(value)
    },
    validators: {
      onChange: personSchema,
    },
  })

  useEffect(() => {
    form.reset(row.original)
  }, [form, row.original])

  const renderCell = (columnId: string) => {
    switch (columnId) {
      case 'firstName':
        return (
          <form.AppField name="firstName">
            {(field) => <field.TextField />}
          </form.AppField>
        )
      case 'lastName':
        return (
          <form.AppField name="lastName">
            {(field) => <field.TextField />}
          </form.AppField>
        )
      case 'age':
        return (
          <form.AppField name="age">
            {(field) => <field.NumberField />}
          </form.AppField>
        )
      case 'visits':
        return (
          <form.AppField name="visits">
            {(field) => <field.NumberField />}
          </form.AppField>
        )
      case 'status':
        return (
          <form.AppField name="status">
            {(field) => <field.SelectField />}
          </form.AppField>
        )
      case 'progress':
        return (
          <form.AppField name="progress">
            {(field) => <field.NumberField />}
          </form.AppField>
        )
      case 'save':
        return (
          <form.Subscribe
            selector={(state) => ({
              canSubmit: state.canSubmit,
              isDirty: state.isDirty,
              isSubmitting: state.isSubmitting,
            })}
          >
            {({ canSubmit, isDirty, isSubmitting }) => (
              <div className="row-action-cell">
                {isDirty ? (
                  <button
                    type="button"
                    disabled={!canSubmit || isSubmitting}
                    onClick={() => form.handleSubmit()}
                    className="demo-button demo-button-sm primary-action"
                  >
                    {isSubmitting ? 'Saving...' : 'Save'}
                  </button>
                ) : null}
              </div>
            )}
          </form.Subscribe>
        )
      default:
        return null
    }
  }

  return (
    <tr>
      {row.getAllCells().map((cell) => (
        <td key={cell.id}>{renderCell(cell.column.id)}</td>
      ))}
    </tr>
  )
}

