/**
 * Header-level components that use useHeaderContext
 *
 * These components can be used via the pre-bound headerComponents
 * in AppHeader children, e.g., <header.SortIndicator />
 */
import { shallow, useSelector } from '@tanstack/react-store'
import { useHeaderContext, useTableContext } from '../hooks/table'

/**
 * Sort indicator showing current sort direction
 */
export function SortIndicator() {
  const header = useHeaderContext()
  const sorted = header.column.getIsSorted()

  if (!sorted) return null

  return (
    <span className="sort-indicator">{sorted === 'asc' ? '🔼' : '🔽'}</span>
  )
}

/**
 * Column filter input
 *
 * Subscribes to `table.store` for this column’s filter value so the controlled input
 * stays in sync under the React compiler (a stable `header` from context alone is not enough).
 */
export function ColumnFilter() {
  const header = useHeaderContext()
  const table = useTableContext()
  const columnId = header.column.id

  const columnFilterValue = useSelector(
    table.store,
    (state) =>
      state.columnFilters.find((f) => f.id === columnId)?.value as
        string | undefined,
    { compare: shallow },
  )

  if (!header.column.getCanFilter()) return null

  return (
    <div className="column-filter" onClick={(e) => e.stopPropagation()}>
      <input
        type="text"
        value={columnFilterValue ?? ''}
        onChange={(e) => header.column.setFilterValue(e.target.value)}
        placeholder={`Filter ${header.column.id}...`}
      />
    </div>
  )
}

/**
 * Footer showing the column ID
 */
export function FooterColumnId() {
  const header = useHeaderContext()
  return <span className="footer-column-id">{header.column.id}</span>
}

/**
 * Footer showing a summary/aggregation for numeric columns
 */
export function FooterSum() {
  const header = useHeaderContext()
  const table = header.getContext().table
  const rows = table.getFilteredRowModel().rows

  // Calculate sum for numeric columns
  const sum = rows.reduce((acc, row) => {
    const value = row.getValue(header.column.id)
    return acc + (typeof value === 'number' ? value : 0)
  }, 0)

  return (
    <span className="footer-sum">{sum > 0 ? sum.toLocaleString() : '—'}</span>
  )
}

/**
 * Indeterminate checkbox used by the row-selection column
 * (both the select-all header and the per-row select cell).
 */
import { useEffect, useRef } from 'react'
import type { HTMLProps } from 'react'

export function IndeterminateCheckbox({
  indeterminate,
  className = '',
  ...rest
}: { indeterminate?: boolean } & HTMLProps<HTMLInputElement>) {
  const ref = useRef<HTMLInputElement>(null!)

  useEffect(() => {
    if (typeof indeterminate === 'boolean') {
      ref.current.indeterminate = !rest.checked && indeterminate
    }
  }, [ref, indeterminate, rest.checked])

  return <input type="checkbox" ref={ref} className={className} {...rest} />
}

/**
 * Table-level components that use useTableContext
 *
 * These components can be used via the pre-bound tableComponents
 * directly on the table object, e.g., <table.PaginationControls />
 */
import { useTableContext } from '../hooks/table'

