export function ColumnHeader({
  title,
  className,
}: {
  title?: string
  className?: string
}): React.ReactNode {
  const header = useHeaderContext()
  const table = useTableContext()
  const column = header.column

  const displayTitle = column.columnDef.meta?.label ?? title ?? column.id

  const canSort = column.getCanSort()
  const canHide = column.getCanHide()
  const canPin = column.getCanPin()
  const canGroup = column.getCanGroup()

  if (!canSort && !canHide && !canPin && !canGroup) {
    return <div className={cn(className)}>{displayTitle}</div>
  }

  return (
    <div className={cn('flex items-center gap-2', className)}>
      <Subscribe
        source={table.store}
        selector={(s) => ({
          sorting: s.sorting,
          grouping: s.grouping,
          columnPinning: s.columnPinning,
        })}
      >
        {() => {
          const sorted = canSort ? column.getIsSorted() : false
          const pinned = canPin ? column.getIsPinned() : false
          const grouped = canGroup ? column.getIsGrouped() : false

          return (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  size="sm"
                  className="group -ml-3 h-8 data-[state=open]:bg-accent"
                >
                  <span>{displayTitle}</span>
                  {sorted === 'desc' ? (
                    <ArrowDown className="ml-2 size-4" />
                  ) : sorted === 'asc' ? (
                    <ArrowUp className="ml-2 size-4" />
                  ) : canSort ? (
                    <ChevronsUpDown className="ml-2 size-4 opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100 group-data-[state=open]:opacity-100" />
                  ) : null}
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start">
                {canSort && (
                  <>
                    <DropdownMenuItem
                      onClick={() => column.toggleSorting(false)}
                    >
                      <ArrowUp className="mr-2 size-3.5 text-muted-foreground/70" />
                      Asc
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => column.toggleSorting(true)}
                    >
                      <ArrowDown className="mr-2 size-3.5 text-muted-foreground/70" />
                      Desc
                    </DropdownMenuItem>
                  </>
                )}
                {canGroup && (
                  <>
                    {canSort ? <DropdownMenuSeparator /> : null}
                    <DropdownMenuItem
                      onClick={column.getToggleGroupingHandler()}
                    >
                      {grouped ? (
                        <>
                          <Ungroup className="mr-2 size-3.5 text-muted-foreground/70" />
                          Ungroup
                        </>
                      ) : (
                        <>
                          <Group className="mr-2 size-3.5 text-muted-foreground/70" />
                          Group by
                        </>
                      )}
                    </DropdownMenuItem>
                  </>
                )}
                {canPin && (
                  <>
                    {canSort || canGroup ? <DropdownMenuSeparator /> : null}
                    <DropdownMenuItem
                      onClick={() => column.pin('start')}
                      disabled={pinned === 'start'}
                    >
                      <Pin className="mr-2 size-3.5 text-muted-foreground/70" />
                      Pin left
                    </DropdownMenuItem>
                    <DropdownMenuItem
                      onClick={() => column.pin('end')}
                      disabled={pinned === 'end'}
                    >
                      <Pin className="mr-2 size-3.5 rotate-180 text-muted-foreground/70" />
                      Pin right
                    </DropdownMenuItem>
                    {pinned ? (
                      <DropdownMenuItem onClick={() => column.pin(false)}>
                        <PinOff className="mr-2 size-3.5 text-muted-foreground/70" />
                        Unpin
                      </DropdownMenuItem>
                    ) : null}
                  </>
                )}
                {canHide && (
                  <>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem
                      onClick={() => column.toggleVisibility(false)}
                    >
                      <EyeOff className="mr-2 size-3.5 text-muted-foreground/70" />
                      Hide
                    </DropdownMenuItem>
                  </>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          )
        }}
      </Subscribe>
    </div>
  )
}

'use client'

import * as React from 'react'
import { format } from 'date-fns'
import {
  CalendarIcon,
  Check,
  ChevronsUpDown,
  ListFilter,
  Trash2,
} from 'lucide-react'
import type {
  ExtendedColumnFilter,
  FilterOperator,
  JoinOperator,
} from '@/types'
import type { Column, RowData } from '@tanstack/react-table'
import type { features } from '@/hooks/features'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Calendar } from '@/components/ui/calendar'
import { getFilterOperators } from '@/lib/data-table'
import { cn } from '@/lib/utils'
import {
  Faceted,
  FacetedBadgeList,
  FacetedContent,
  FacetedEmpty,
  FacetedGroup,
  FacetedInput,
  FacetedItem,
  FacetedList,
  FacetedTrigger,
} from '@/components/ui/faceted'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { useTableContext } from '@/hooks/table'

function getColumnOptions({
  column,
}: {
  column: Column<typeof features, RowData>
}): Array<{ label: string; value: string; count?: number }> {
  const customOptions = column.columnDef.meta?.options

  if (customOptions) return customOptions

  const uniqueValues = column.getFacetedUniqueValues()

  return Array.from(uniqueValues.entries()).map(([value, count]) => ({
    label: String(value),
    value: String(value),
    count,
  }))
}

export function DataTableFilterList(): React.ReactNode {
  const table = useTableContext()
  const columnFilters = table.state.columnFilters as Array<ExtendedColumnFilter>

  // Write through the raw controlled-state handler instead of
  // `table.setColumnFilters`: the table API auto-removes filters with empty
  // values, but a just-added filter row legitimately starts with `value: ''`
  // while the user is still building it.
  const setColumnFilters = (filters: Array<ExtendedColumnFilter>) => {
    table.options.onColumnFiltersChange?.(filters)
  }

  const id = React.useId()
  const labelId = React.useId()
  const descriptionId = React.useId()
  const listId = React.useId()
  const [open, setOpen] = React.useState(false)

  const filterableColumns = React.useMemo(
    () => table.getAllColumns().filter((column) => column.getCanFilter()),
    [table],
  )

  const getColumnFilterVariant = React.useCallback(
    (column: Column<typeof features, RowData>) => {
      if (column.columnDef.meta?.variant) {
        return column.columnDef.meta.variant
      }

      const firstValue = table
        .getPreFilteredRowModel()
        .flatRows[0]?.getValue(column.id)

      if (Array.isArray(firstValue)) return 'multi-select'
      if (typeof firstValue === 'number') return 'number'
      if (firstValue instanceof Date) return 'date'
      if (column.columnDef.meta?.variant === 'select') return 'select'

      return 'text'
    },
    [table],
  )

  const onFilterAddImpl = React.useCallback(
    (columnId: string): ExtendedColumnFilter | null => {
      const column = filterableColumns.find((col) => col.id === columnId)
      if (!column) return null

      const filterVariant = getColumnFilterVariant(column)
      const operators = getFilterOperators(filterVariant ?? 'text')
      const defaultOperator = operators[0].value

      return {
        id: columnId,
        value: filterVariant === 'multi-select' ? [] : '',
        operator: defaultOperator,
        filterId: crypto.randomUUID(),
        joinOperator: 'and',
      }
    },
    [filterableColumns, getColumnFilterVariant],
  )

  const onFilterAdd = React.useCallback(() => {
    const firstFilterableColumn = filterableColumns[0]

    const newFilter = onFilterAddImpl(firstFilterableColumn.id)
    if (newFilter) {
      setColumnFilters([...columnFilters, newFilter])
    }
  }, [columnFilters, onFilterAddImpl, filterableColumns, table])

  const onFilterUpdate = React.useCallback(
    (
      filterId: string,
      updates: Partial<Omit<ExtendedColumnFilter, 'filterId'>>,
    ) => {
      const newFilters = columnFilters.map((filter) => {
        if (filter.filterId === filterId) {
          if (updates.id) {
            const newColumn = filterableColumns.find(
              (col) => col.id === updates.id,
            )
            if (newColumn) {
              const filterVariant = getColumnFilterVariant(newColumn)
              const operators = getFilterOperators(filterVariant ?? 'text')
              const defaultOperator = operators[0].value
              return {
                ...filter,
                ...updates,
                operator: defaultOperator,
                value: filterVariant === 'multi-select' ? [] : '',
              }
            }
          }

          if (updates.operator && filter.value) {
            const column = filterableColumns.find((col) => col.id === filter.id)
            if (column && getColumnFilterVariant(column) === 'date') {
              const currentValue = filter.value
              if (
                updates.operator === 'inRange' &&
                !Array.isArray(currentValue)
              ) {
                return {
                  ...filter,
                  ...updates,
                  value: [currentValue, undefined],
                }
              } else if (
                updates.operator !== 'inRange' &&
                Array.isArray(currentValue)
              ) {
                return {
                  ...filter,
                  ...updates,
                  value: currentValue[0] ?? '',
                }
              }
            }
          }

          return { ...filter, ...updates }
        }
        return filter
      })
      setColumnFilters(newFilters)
    },
    [
      columnFilters,
      filterableColumns,
      getColumnFilterVariant,
      getFilterOperators,
      table,
    ],
  )

  const onFilterRemove = React.useCallback(
    (filterId: string) => {
      const newFilters = columnFilters.filter((filter) => {
        return filter.filterId !== filterId
      })
      setColumnFilters(newFilters)
    },
    [columnFilters, table],
  )

  const onFilterInputRender = React.useCallback(
    ({
      column,
      operator,
      filterId,
      inputId,
    }: {
      column: Column<typeof features, RowData>
      operator: FilterOperator
      filterId: string
      inputId: string
    }) => {
      const filterVariant = getColumnFilterVariant(column) ?? 'text'
      const currentFilter = columnFilters.find(
        (filter) => filter.filterId === filterId,
      )
      const columnLabel = column.columnDef.meta?.label ?? column.id

      switch (filterVariant) {
        case 'date':
          if (operator === 'inRange') {
            const currentValue = Array.isArray(currentFilter?.value)
              ? currentFilter.value
              : [currentFilter?.value, undefined]

            const dateRange =
              currentValue[0] || currentValue[1]
                ? {
                    from: currentValue[0]
                      ? new Date(currentValue[0])
                      : undefined,
                    to: currentValue[1] ? new Date(currentValue[1]) : undefined,
                  }
                : undefined

            return (
              <div className="flex items-center gap-2">
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      id={inputId}
                      aria-controls={`${inputId}-calendar`}
                      aria-label={`${columnLabel} date range filter`}
                      variant="outline"
                      size="sm"
                      className={cn(
                        'w-full justify-start text-left font-normal [&>svg]:size-3.5',
                        !dateRange && 'text-muted-foreground',
                      )}
                      onPointerDown={(event) => {
                        const target = event.target
                        if (!(target instanceof HTMLElement)) return
                        if (target.hasPointerCapture(event.pointerId)) {
                          target.releasePointerCapture(event.pointerId)
                        }

                        if (
                          event.button === 0 &&
                          event.ctrlKey === false &&
                          event.pointerType === 'mouse'
                        ) {
                          event.preventDefault()
                        }
                      }}
                    >
                      <CalendarIcon />
                      {dateRange?.from ? (
                        dateRange.to ? (
                          <>
                            {format(dateRange.from, 'LLL dd, y')} -{' '}
                            {format(dateRange.to, 'LLL dd, y')}
                          </>
                        ) : (
                          format(dateRange.from, 'LLL dd, y')
                        )
                      ) : (
                        <span>Select date range</span>
                      )}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent
                    id={`${inputId}-calendar`}
                    className="w-auto p-0"
                    align="start"
                    onCloseAutoFocus={() => {
                      document.getElementById(inputId)?.focus({
                        preventScroll: true,
                      })
                    }}
                  >
                    <Calendar
                      mode="range"
                      aria-label={`Select ${columnLabel} date range`}
                      selected={dateRange}
                      defaultMonth={dateRange?.from}
                      onSelect={(date) => {
                        if (filterId) {
                          onFilterUpdate(filterId, {
                            value: [
                              date?.from ? date.from.toISOString() : undefined,
                              date?.to ? date.to.toISOString() : undefined,
                            ],
                            operator,
                          })
                        }
                      }}
                      numberOfMonths={2}
                      autoFocus
                    />
                  </PopoverContent>
                </Popover>
              </div>
            )
          }

          const selectedDate = currentFilter?.value
            ? new Date(currentFilter.value as string)
            : undefined

          return (
            <Popover>
              <PopoverTrigger asChild>
                <Button
                  id={inputId}
                  aria-controls={`${inputId}-calendar`}
                  aria-label={`${columnLabel} date filter`}
                  variant="outline"
                  size="sm"
                  className={cn(
                    'w-full justify-start text-left font-normal [&>svg]:size-3.5',
                    !currentFilter?.value && 'text-muted-foreground',
                  )}
                  onPointerDown={(event) => {
                    const target = event.target
                    if (!(target instanceof HTMLElement)) return
                    if (target.hasPointerCapture(event.pointerId)) {
                      target.releasePointerCapture(event.pointerId)
                    }

                  if (
                    event.button === 0 &&
                    event.ctrlKey === false &&
                    event.pointerType === 'mouse'
                  ) {
                    event.preventDefault()
                  }
                }}
              >
                <CalendarIcon />
                {currentFilter?.value ? (
                  format(new Date(currentFilter.value as string), 'PP')
                ) : (
                  <span className="text-muted-foreground">Pick a date</span>
                )}
              </Button>
            </PopoverTrigger>
            <PopoverContent
              id={`${inputId}-calendar`}
              className="w-auto p-0"
              align="start"
              onCloseAutoFocus={() => {
                document.getElementById(inputId)?.focus({
                  preventScroll: true,
                })
              }}
            >
              <Calendar
                mode="single"
                aria-label={`Select ${columnLabel} date`}
                selected={selectedDate}
                defaultMonth={selectedDate}
                onSelect={(date) => {
                  if (filterId) {
                    onFilterUpdate(filterId, {
                      value: date ? date.toISOString() : undefined,
                      operator,
                    })
                  }
                }}
                autoFocus
              />
            </PopoverContent>
          </Popover>
        )
      case 'number':
        if (operator === 'inRange') {
          const currentValue = Array.isArray(currentFilter?.value)
            ? currentFilter.value
            : [currentFilter?.value, undefined]

          return (
            <div className="flex items-center gap-2">
              <Input
                id={`${inputId}-min`}
                type="number"
                aria-label={`${columnLabel} minimum value`}
                value={currentValue[0] ?? ''}
                placeholder="Min"
                className="h-8"
                onChange={(event) => {
                  if (filterId) {
                    onFilterUpdate(filterId, {
                      value: [
                        event.target.value === ''
                          ? undefined
                          : Number(event.target.value),
                        currentValue[1] ?? undefined,
                      ],
                      operator,
                    })
                  }
                }}
              />
              <Input
                id={`${inputId}-max`}
                type="number"
                aria-label={`${columnLabel} maximum value`}
                value={currentValue[1] ?? ''}
                placeholder="Max"
                className="h-8"
                onChange={(event) => {
                  if (filterId) {
                    onFilterUpdate(filterId, {
                      value: [
                        currentValue[0] ?? undefined,
                        event.target.value === ''
                          ? undefined
                          : Number(event.target.value),
                      ],
                      operator,
                    })
                  }
                }}
              />
            </div>
          )
        }

        return (
          <Input
            id={inputId}
            type="number"
            aria-label={`${columnLabel} filter value`}
            value={(currentFilter?.value ?? '') as string}
            placeholder={`Enter number...`}
            className="h-8"
            onChange={(event) => {
              if (filterId) {
                onFilterUpdate(filterId, {
                  value:
                    event.target.value === ''
                      ? ''
                      : Number(event.target.value),
                  operator,
                })
              }
            }}
          />
        )
      case 'select':
        const selectOptions = getColumnOptions({ column })

        return (
          <Faceted
            value={
              typeof currentFilter?.value === 'string'
                ? currentFilter.value
                : undefined
            }
            onValueChange={(value) => {
              if (filterId) {
                onFilterUpdate(filterId, { value })
              }
            }}
          >
            <FacetedTrigger asChild>
              <Button
                id={inputId}
                aria-controls={`${inputId}-listbox`}
                aria-label={`${columnLabel} filter value`}
                variant="outline"
                size="sm"
                className="h-8 w-full justify-start text-left font-normal"
              >
                <FacetedBadgeList
                  options={selectOptions}
                  placeholder={`Select ${column.columnDef.meta?.label ?? column.id}...`}
                />
              </Button>
            </FacetedTrigger>
            <FacetedContent id={`${inputId}-listbox`}>
              <FacetedInput
                aria-label={`Search ${columnLabel} options`}
                placeholder={`Search ${column.columnDef.meta?.label ?? column.id}...`}
              />
              <FacetedList>
                <FacetedEmpty>No options found.</FacetedEmpty>
                <FacetedGroup>
                  {selectOptions.map((option) => (
                    <FacetedItem key={option.value} value={option.value}>
                      <span>{option.label}</span>
                      {option.count && (
                        <span className="ml-auto flex size-4 items-center justify-center font-mono text-xs">
                          {option.count}
                        </span>
                      )}
                    </FacetedItem>
                  ))}
                </FacetedGroup>
              </FacetedList>
            </FacetedContent>
          </Faceted>
        )

      case 'multi-select':
        const multiSelectOptions = getColumnOptions({ column })
        const selectedValues = Array.isArray(currentFilter?.value)
          ? currentFilter.value
          : []

        return (
          <Faceted
            multiple
            value={selectedValues}
            onValueChange={(value) => {
              if (filterId) {
                onFilterUpdate(filterId, { value })
              }
            }}
          >
            <FacetedTrigger asChild>
              <Button
                id={inputId}
                aria-controls={`${inputId}-listbox`}
                aria-label={`${columnLabel} filter values`}
                variant="outline"
                size="sm"
                className="h-8 w-full justify-start text-left font-normal"
              >
                <FacetedBadgeList
                  options={multiSelectOptions}
                  placeholder={`Select ${column.columnDef.meta?.label ?? column.id}...`}
                />
              </Button>
            </FacetedTrigger>
            <FacetedContent id={`${inputId}-listbox`}>
              <FacetedInput
                aria-label={`Search ${columnLabel} options`}
                placeholder={`Search ${column.columnDef.meta?.label ?? column.id}...`}
              />
              <FacetedList>
                <FacetedEmpty>No options found.</FacetedEmpty>
                <FacetedGroup>
                  {multiSelectOptions.map((option) => (
                    <FacetedItem key={option.value} value={option.value}>
                      <span>{option.label}</span>
                      {option.count && (
                        <span className="ml-auto flex size-4 items-center justify-center font-mono text-xs">
                          {option.count}
                        </span>
                      )}
                    </FacetedItem>
                  ))}
                </FacetedGroup>
              </FacetedList>
            </FacetedContent>
          </Faceted>
        )

      default:
        if (operator === 'isEmpty' || operator === 'isNotEmpty') {
          return (
            <div
              role="status"
              id={inputId}
              aria-live="polite"
              aria-label={`${columnLabel} filter is ${
                operator === 'isEmpty' ? 'empty' : 'not empty'
              }`}
              className="h-8 w-full rounded-md border border-dashed"
            />
          )
        }

        return (
          <Input
            id={inputId}
            type="text"
            aria-label={`${columnLabel} filter value`}
            value={(currentFilter?.value ?? '') as string}
            placeholder={`Search ${
              column.columnDef.meta?.label ?? column.id
            }...`}
            className="h-8"
            onChange={(event) => {
              if (filterId) {
                onFilterUpdate(filterId, {
                  value: event.target.value,
                  operator,
                })
              }
            }}
          />
        )
    }
  },
  [getColumnFilterVariant, columnFilters, onFilterUpdate],
)

const onFilterRender = React.useCallback(
  ({ filter, index }: { filter: ExtendedColumnFilter; index: number }) => {
    const column = table.getColumn(filter.id)
    if (!column || !filter.filterId) return null

    const filterVariant = getColumnFilterVariant(column) ?? 'text'
    const operators = getFilterOperators(filterVariant)
    const filterItemId = `${id}-filter-${filter.filterId}`
    const triggerId = `${filterItemId}-trigger`
    const joinOperatorListboxId = `${filterItemId}-join-operator-listbox`
    const fieldListboxId = `${filterItemId}-field-listbox`
    const operatorListboxId = `${filterItemId}-operator-listbox`
    const inputId = `${filterItemId}-input`

      return (
        <div
          role="listitem"
          id={filterItemId}
          className="grid items-center grid-cols-[70px_135px_125px_minmax(0,200px)_32px] gap-2"
        >
          {index === 0 ? (
            <span className="text-sm text-center text-muted-foreground">
              Where
            </span>
          ) : index === 1 ? (
            <Select
              value={filter.joinOperator}
              onValueChange={(value: JoinOperator) => {
                if (columnFilters.length > 0) {
                  const updatedFilters = columnFilters.map((f) => ({
                    ...f,
                    joinOperator: value,
                  }))
                  setColumnFilters(updatedFilters)
                }
              }}
            >
              <SelectTrigger
                className="h-8"
                aria-label="Select join operator"
                aria-controls={joinOperatorListboxId}
              >
                <SelectValue placeholder="Join" />
              </SelectTrigger>
              <SelectContent
                id={joinOperatorListboxId}
                className="min-w-[var(--radix-select-trigger-width)]"
              >
                <SelectItem value="and">and</SelectItem>
                <SelectItem value="or">or</SelectItem>
              </SelectContent>
            </Select>
          ) : (
            <span className="text-sm text-center text-muted-foreground">
              {filter.joinOperator}
            </span>
          )}
          <Popover>
            <PopoverTrigger asChild>
              <Button
                role="combobox"
                id={triggerId}
                aria-controls={fieldListboxId}
                aria-label={`Select filter field. Current: ${column.columnDef.meta?.label ?? column.id}`}
                variant="outline"
                size="sm"
                className="h-8 justify-between font-normal focus:outline-none focus:ring-1 focus:ring-ring"
                onPointerDown={(event) => {
                  const target = event.target
                  if (!(target instanceof HTMLElement)) return
                  if (target.hasPointerCapture(event.pointerId)) {
                    target.releasePointerCapture(event.pointerId)
                  }

                  if (
                    event.button === 0 &&
                    event.ctrlKey === false &&
                    event.pointerType === 'mouse'
                  ) {
                    event.preventDefault()
                  }
                }}
              >
                <span className="truncate">
                  {column.columnDef.meta?.label ?? column.id}
                </span>
                <ChevronsUpDown className="opacity-50" />
              </Button>
            </PopoverTrigger>
            <PopoverContent
              id={fieldListboxId}
              className="w-[var(--radix-popover-trigger-width)] p-0"
              onCloseAutoFocus={() =>
                document
                  .getElementById(triggerId)
                  ?.focus({ preventScroll: true })
              }
            >
              <Command>
                <CommandInput
                  placeholder="Search columns..."
                  aria-label="Search filterable columns"
                />
                <CommandList>
                  <CommandEmpty>No column found.</CommandEmpty>
                  <CommandGroup>
                    {filterableColumns.map((col) => (
                      <CommandItem
                        key={col.id}
                        value={col.id}
                        onSelect={(value) => {
                          if (!filter.filterId) return
                          onFilterUpdate(filter.filterId, { id: value })
                        }}
                      >
                        <span className="truncate">
                          {col.columnDef.meta?.label ?? col.id}
                        </span>
                        <Check
                          className={cn(
                            'ml-auto size-4',
                            col.id === filter.id ? 'opacity-100' : 'opacity-0',
                          )}
                          aria-hidden="true"
                        />
                      </CommandItem>
                    ))}
                  </CommandGroup>
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>
          <Select
            value={filter.operator ?? 'contains'}
            onValueChange={(value: FilterOperator) => {
              if (!filter.filterId) return

              onFilterUpdate(filter.filterId, {
                operator: value,
              })
            }}
          >
            <SelectTrigger
              className="h-8"
              aria-label="Select filter operator"
              aria-controls={operatorListboxId}
            >
              <SelectValue placeholder="Select operator" />
            </SelectTrigger>
            <SelectContent id={operatorListboxId}>
              {operators.map((op) => (
                <SelectItem key={op.value} value={op.value}>
                  {op.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {onFilterInputRender({
            column,
            operator: filter.operator ?? 'includesString',
            filterId: filter.filterId,
            inputId,
          })}
          <Button
            variant="outline"
            size="icon"
            className="size-8 [&_svg]:size-3.5"
            aria-label={`Remove ${column.columnDef.meta?.label ?? column.id} filter`}
            onClick={() => {
              if (!filter.filterId) return

              onFilterRemove(filter.filterId)
            }}
          >
            <Trash2 />
          </Button>
        </div>
      )
    },
    [
      table,
      filterableColumns,
      getColumnFilterVariant,
      onFilterInputRender,
      onFilterUpdate,
      onFilterRemove,
    ],
  )

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className="[&_svg]:size-3"
          onClick={(event) => event.currentTarget.focus()}
          onPointerDown={(event) => {
            const target = event.target
            if (!(target instanceof HTMLElement)) return
            if (target.hasPointerCapture(event.pointerId)) {
              target.releasePointerCapture(event.pointerId)
            }

            if (
              event.button === 0 &&
              event.ctrlKey === false &&
              event.pointerType === 'mouse'
            ) {
              event.preventDefault()
            }
          }}
        >
          <ListFilter />
          Filter
          {columnFilters.length > 0 && (
            <Badge
