import { faker } from '@faker-js/faker'

export type Person = {
  id: string
  firstName: string
  lastName: string
  email: string
  age: number
  jobTitle: string
  city: string
  state: string
  salary: number
  status: 'active' | 'inactive' | 'pending'
  startDate: Date
  subRows?: Array<Person>
}

const STATUSES: Array<Person['status']> = ['active', 'inactive', 'pending']

const newPerson = (): Person => {
  const sex = faker.person.sex() as 'female' | 'male'
  const firstName = faker.person.firstName(sex)
  const lastName = faker.person.lastName()
  return {
    id: faker.string.uuid(),
    firstName,
    lastName,
    email: faker.internet
      .email({ firstName, lastName, provider: 'example.com' })
      .toLowerCase(),
    age: faker.number.int({ min: 18, max: 75 }),
    jobTitle: faker.person.jobTitle(),
    city: faker.location.city(),
    state: faker.location.state({ abbreviated: true }),
    salary: faker.number.int({ min: 35_000, max: 250_000 }),
    status: faker.helpers.arrayElement(STATUSES),
    startDate: faker.date.past({ years: 8 }),
  }
}

export function makeData(...lens: Array<number>): Array<Person> {
  const makeDataLevel = (depth = 0): Array<Person> => {
    const len = lens[depth]
    return Array.from({ length: len }, (): Person => {
      return {
        ...newPerson(),
        subRows: lens[depth + 1] ? makeDataLevel(depth + 1) : undefined,
      }
    })
  }
  return makeDataLevel()
}

import { useMantineReactTable } from '../hooks/useMantineReactTable'
import { MRT_TablePaper } from './table/MRT_TablePaper'
import type {
  MRT_RowData,
  MRT_TableInstance,
  MRT_TableOptions,
  Xor,
} from '../types'

type TableInstanceProp<TData extends MRT_RowData> = {
  table: MRT_TableInstance<TData>
}

type Props<TData extends MRT_RowData> = Xor<
  TableInstanceProp<TData>,
  MRT_TableOptions<TData>
>

const isTableInstanceProp = <TData extends MRT_RowData>(
  props: Props<TData>,
): props is TableInstanceProp<TData> =>
  (props as TableInstanceProp<TData>).table !== undefined

export const MantineReactTable = <TData extends MRT_RowData>(
  props: Props<TData>,
) => {
  let table: MRT_TableInstance<TData>

  if (isTableInstanceProp(props)) {
    table = props.table
  } else {
    table = useMantineReactTable(props)
  }

  return <MRT_TablePaper table={table} />
}

import clsx from 'clsx'

import { memo, useMemo } from 'react'

import { TableTbody } from '@mantine/core'

import { useMRT_Rows } from '../../hooks/useMRT_Rows'
import { useMRT_RowVirtualizer } from '../../hooks/useMRT_RowVirtualizer'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_TableBodyRow, Memo_MRT_TableBodyRow } from './MRT_TableBodyRow'
import { MRT_TableBodyEmptyRow } from './MRT_TableBodyEmptyRow'
import classes from './MRT_TableBody.module.css'
import type {
  MRT_ColumnVirtualizer,
  MRT_Row,
  MRT_RowData,
  MRT_TableInstance,
  MRT_VirtualItem,
} from '../../types'
import type { TableProps, TableTbodyProps } from '@mantine/core'

export interface MRT_TableBodyProps<
  TData extends MRT_RowData,
> extends TableTbodyProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
  table: MRT_TableInstance<TData>
  tableProps: Partial<TableProps>
}

export const MRT_TableBody = <TData extends MRT_RowData>({
  columnVirtualizer,
  table,
  tableProps,
  ...rest
}: MRT_TableBodyProps<TData>) => {
  const {
    getBottomRows,
    getIsSomeRowsPinned,
    getRowModel,
    state,
    getTopRows,
    options: {
      enableStickyFooter,
      enableStickyHeader,
      layoutMode,
      mantineTableBodyProps,
      memoMode,
      renderDetailPanel,
      rowPinningDisplayMode,
    },
    refs: { tableFooterRef, tableHeadRef },
  } = table
  const { isFullScreen, rowPinning } = state

  const tableBodyProps = {
    ...parseFromValuesOrFunc(mantineTableBodyProps, { table }),
    ...rest,
  }

  const tableHeadHeight =
    ((enableStickyHeader || isFullScreen) &&
      tableHeadRef.current?.clientHeight) ||
    0
  const tableFooterHeight =
    (enableStickyFooter && tableFooterRef.current?.clientHeight) || 0

  const pinnedRowIds = useMemo(() => {
    if (!rowPinning.bottom?.length && !rowPinning.top?.length) return []
    return getRowModel()
      .rows.filter((row) => row.getIsPinned())
      .map((r) => r.id)
  }, [rowPinning, getRowModel().rows])

  const rows = useMRT_Rows(table)

  const rowVirtualizer = useMRT_RowVirtualizer(table, rows)

  const { virtualRows } = rowVirtualizer ?? {}

  const commonRowProps = {
    columnVirtualizer,
    numRows: rows.length,
    table,
    tableProps,
  }

  return (
    <>
      {!rowPinningDisplayMode?.includes('sticky') &&
        getIsSomeRowsPinned('top') && (
          <TableTbody
            {...tableBodyProps}
            __vars={{
              '--mrt-table-head-height': `${tableHeadHeight}`,
              ...tableBodyProps?.__vars,
            }}
            className={clsx(
              classes.pinned,
              layoutMode?.startsWith('grid') && classes['root-grid'],
              tableBodyProps?.className,
            )}
          >
            {getTopRows().map((row, renderedRowIndex) => {
              const rowProps = {
                ...commonRowProps,
                renderedRowIndex,
                row,
              }
              return memoMode === 'rows' ? (
                <Memo_MRT_TableBodyRow key={row.id} {...rowProps} />
              ) : (
                <MRT_TableBodyRow key={row.id} {...rowProps} />
              )
            })}
          </TableTbody>
        )}
      <TableTbody
        {...tableBodyProps}
        __vars={{
          '--mrt-table-body-height': rowVirtualizer
            ? `${rowVirtualizer.getTotalSize()}px`
            : undefined,
          ...tableBodyProps?.__vars,
        }}
        className={clsx(
          classes.root,
          layoutMode?.startsWith('grid') && classes['root-grid'],
          !rows.length && classes['root-no-rows'],
          rowVirtualizer && classes['root-virtualized'],
          tableBodyProps?.className,
        )}
      >
        {tableBodyProps?.children ??
          (!rows.length ? (
            <MRT_TableBodyEmptyRow {...commonRowProps} />
          ) : (
            <>
              {(virtualRows ?? rows).map(
                (rowOrVirtualRow, renderedRowIndex) => {
                  if (rowVirtualizer) {
                    if (renderDetailPanel) {
                      if (rowOrVirtualRow.index % 2 === 1) {
                        return null
                      } else {
                        renderedRowIndex = rowOrVirtualRow.index / 2
                      }
                    } else {
                      renderedRowIndex = rowOrVirtualRow.index
                    }
                  }
                  const row = rowVirtualizer
                    ? rows[renderedRowIndex]
                    : (rowOrVirtualRow as MRT_Row<TData>)
                  const props = {
                    ...commonRowProps,
                    pinnedRowIds,
                    renderedRowIndex,
                    row,
                    rowVirtualizer,
                    virtualRow: rowVirtualizer
                      ? (rowOrVirtualRow as MRT_VirtualItem)
                      : undefined,
                  }
                  const key = `${row.id}-${row.index}`
                  return memoMode === 'rows' ? (
                    <Memo_MRT_TableBodyRow key={key} {...props} />
                  ) : (
                    <MRT_TableBodyRow key={key} {...props} />
                  )
                },
              )}
            </>
          ))}
      </TableTbody>
      {!rowPinningDisplayMode?.includes('sticky') &&
        getIsSomeRowsPinned('bottom') && (
          <TableTbody
            {...tableBodyProps}
            __vars={{
              '--mrt-table-footer-height': `${tableFooterHeight}`,
              ...tableBodyProps?.__vars,
            }}
            className={clsx(
              classes.pinned,
              layoutMode?.startsWith('grid') && classes['root-grid'],
              tableBodyProps?.className,
            )}
          >
            {getBottomRows().map((row, renderedRowIndex) => {
              const props = {
                ...commonRowProps,
                renderedRowIndex,
                row,
              }
              return memoMode === 'rows' ? (
                <Memo_MRT_TableBodyRow key={row.id} {...props} />
              ) : (
                <MRT_TableBodyRow key={row.id} {...props} />
              )
            })}
          </TableTbody>
        )}
    </>
  )
}

export const Memo_MRT_TableBody = memo(
  MRT_TableBody,
  (prev, next) => prev.table.options.data === next.table.options.data,
) as typeof MRT_TableBody

import clsx from 'clsx'

import { memo, useEffect, useRef, useState } from 'react'

import { Skeleton, TableTd, useDirection } from '@mantine/core'

import { parseCSSVarId } from '../../utils/style.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_CopyButton } from '../buttons/MRT_CopyButton'
import { MRT_EditCellTextInput } from '../inputs/MRT_EditCellTextInput'
import { MRT_TableBodyCellValue } from './MRT_TableBodyCellValue'
import classes from './MRT_TableBodyCell.module.css'
import type {
  MRT_Cell,
  MRT_CellValue,
  MRT_RowData,
  MRT_TableInstance,
  MRT_VirtualItem,
} from '../../types'
import type { CSSProperties, DragEvent, MouseEvent, RefObject } from 'react'
import type { TableTdProps } from '@mantine/core'

interface Props<
  TData extends MRT_RowData,
  TValue = MRT_CellValue,
> extends TableTdProps {
  cell: MRT_Cell<TData, TValue>
  numRows?: number
  renderedColumnIndex?: number
  renderedRowIndex?: number
  rowRef: RefObject<HTMLTableRowElement | null>
  table: MRT_TableInstance<TData>
  virtualCell?: MRT_VirtualItem
}

export const MRT_TableBodyCell = <TData extends MRT_RowData>({
  cell,
  numRows = 1,
  renderedColumnIndex = 0,
  renderedRowIndex = 0,
  rowRef,
  table,
  virtualCell,
  ...rest
}: Props<TData>) => {
  const direction = useDirection()

  const {
    state,
    options: {
      columnResizeDirection,
      columnResizeMode,
      createDisplayMode,
      editDisplayMode,
      enableClickToCopy,
      enableColumnOrdering,
      enableColumnPinning,
      enableEditing,
      enableGrouping,
      layoutMode,
      mantineSkeletonProps,
      mantineTableBodyCellProps,
    },
    refs: { editInputRefs },
    setEditingCell,
    setHoveredColumn,
  } = table
  const {
    columnResizing,
    creatingRow,
    density,
    draggingColumn,
    editingCell,
    editingRow,
    hoveredColumn,
    isLoading,
    showSkeletons,
  } = state
  const { column, row } = cell
  const { columnDef } = column
  const { columnDefType } = columnDef

  const args = {
    cell,
    column,
    renderedColumnIndex,
    renderedRowIndex,
    row,
    table,
  }
  const tableCellProps = {
    ...parseFromValuesOrFunc(mantineTableBodyCellProps, args),
    ...parseFromValuesOrFunc(columnDef.mantineTableBodyCellProps, args),
    ...rest,
  }

  const skeletonProps = parseFromValuesOrFunc(mantineSkeletonProps, args)

  const [skeletonWidth, setSkeletonWidth] = useState(100)
  useEffect(() => {
    if ((!isLoading && !showSkeletons) || skeletonWidth !== 100) return
    const size = column.getSize()
    setSkeletonWidth(
      columnDefType === 'display'
        ? size / 2
        : Math.round(Math.random() * (size - size / 3) + size / 3),
    )
  }, [isLoading, showSkeletons])

  const widthStyles: CSSProperties = {
    minWidth: `max(calc(var(--col-${parseCSSVarId(
      column?.id,
    )}-size) * 1px), ${columnDef.minSize ?? 30}px)`,
    width: `calc(var(--col-${parseCSSVarId(column.id)}-size) * 1px)`,
  }
  if (layoutMode === 'grid') {
    widthStyles.flex = `${
      [0, false].includes(columnDef.grow!)
        ? 0
        : `var(--col-${parseCSSVarId(column.id)}-size)`
    } 0 auto`
  } else if (layoutMode === 'grid-no-grow') {
    widthStyles.flex = `${+(columnDef.grow || 0)} 0 auto`
  }
  const isDraggingColumn = draggingColumn?.id === column.id
  const isHoveredColumn = hoveredColumn?.id === column.id
  const isColumnPinned =
    enableColumnPinning &&
    columnDef.columnDefType !== 'group' &&
    column.getIsPinned()

  const isEditable =
    !cell.getIsPlaceholder() &&
    parseFromValuesOrFunc(enableEditing, row) &&
    parseFromValuesOrFunc(columnDef.enableEditing, row) !== false

  const isEditing =
    isEditable &&
    !['custom', 'modal'].includes(editDisplayMode as string) &&
    (editDisplayMode === 'table' ||
      editingRow?.id === row.id ||
      editingCell?.id === cell.id) &&
    !row.getIsGrouped()

  const isCreating =
    isEditable && createDisplayMode === 'row' && creatingRow?.id === row.id

  const showClickToCopyButton =
    parseFromValuesOrFunc(enableClickToCopy, cell) ||
    (parseFromValuesOrFunc(columnDef.enableClickToCopy, cell) &&
      parseFromValuesOrFunc(columnDef.enableClickToCopy, cell) !== false)

  const handleDoubleClick = (event: MouseEvent<HTMLTableCellElement>) => {
    tableCellProps?.onDoubleClick?.(event)
    if (isEditable && editDisplayMode === 'cell') {
      setEditingCell(cell)
      setTimeout(() => {
        const textField = editInputRefs.current[cell.id]
        if (textField) {
          textField.focus()
          textField.select?.()
        }
      }, 100)
    }
  }

  const handleDragEnter = (e: DragEvent<HTMLTableCellElement>) => {
    tableCellProps?.onDragEnter?.(e)
    if (enableGrouping && hoveredColumn?.id === 'drop-zone') {
      setHoveredColumn(null)
    }
    if (enableColumnOrdering && draggingColumn) {
      setHoveredColumn(columnDef.enableColumnOrdering !== false ? column : null)
    }
  }

  const cellValueProps = {
    cell,
    renderedColumnIndex,
    renderedRowIndex,
    table,
  }

  const cellHoverRevealDivRef = useRef<any>(null)
  const [isCellContentOverflowing, setIsCellContentOverflowing] =
    useState(false)

  const onMouseEnter = () => {
    if (!columnDef.enableCellHoverReveal) return
    const div = cellHoverRevealDivRef.current
    if (div) {
      const isOverflow = div.scrollWidth > div.clientWidth
      setIsCellContentOverflowing(isOverflow)
    }
  }

  const onMouseLeave = () => {
    if (!columnDef.enableCellHoverReveal) return
    setIsCellContentOverflowing(false)
  }

  const renderCellContent = () => {
    if (cell.getIsPlaceholder()) {
      return columnDef.PlaceholderCell?.({ cell, column, row, table }) ?? null
    }

    if (showSkeletons !== false && (isLoading || showSkeletons)) {
      return <Skeleton height={20} width={skeletonWidth} {...skeletonProps} />
    }

    if (
      columnDefType === 'display' &&
      (['mrt-row-expand', 'mrt-row-numbers', 'mrt-row-select'].includes(
        column.id,
      ) ||
        !row.getIsGrouped())
    ) {
      return columnDef.Cell?.({
        column,
        renderedCellValue: cell.renderValue() as any,
        row,
        rowRef,
        ...cellValueProps,
      })
    }

    if (isCreating || isEditing) {
      return <MRT_EditCellTextInput cell={cell} table={table} />
    }

    if (showClickToCopyButton && columnDef.enableClickToCopy !== false) {
      return (
        <MRT_CopyButton cell={cell} table={table}>
          <MRT_TableBodyCellValue {...cellValueProps} />
        </MRT_CopyButton>
      )
    }

    return <MRT_TableBodyCellValue {...cellValueProps} />
  }

  return (
    <TableTd
      data-column-pinned={isColumnPinned || undefined}
      data-dragging-column={isDraggingColumn || undefined}
      data-first-end-pinned={
        (isColumnPinned === 'end' && column.getIsFirstColumn(isColumnPinned)) ||
        undefined
      }
      data-hovered-column-target={isHoveredColumn || undefined}
      data-index={renderedColumnIndex}
      data-last-start-pinned={
        (isColumnPinned === 'start' &&
          column.getIsLastColumn(isColumnPinned)) ||
        undefined
      }
      data-last-row={renderedRowIndex === numRows - 1 || undefined}
      data-resizing={
        (columnResizeMode === 'onChange' &&
          columnResizing?.isResizingColumn === column.id &&
          columnResizeDirection) ||
        undefined
      }
      {...tableCellProps}
      __vars={{
        '--mrt-cell-align':
          tableCellProps.align ?? (direction.dir === 'rtl' ? 'right' : 'left'),
        '--mrt-table-cell-start':
          isColumnPinned === 'start'
            ? `${column.getStart(isColumnPinned)}`
            : undefined,
        '--mrt-table-cell-end':
          isColumnPinned === 'end'
            ? `${column.getAfter(isColumnPinned)}`
            : undefined,
        ...tableCellProps.__vars,
      }}
      className={clsx(
        classes.root,
        layoutMode?.startsWith('grid') && classes['root-grid'],
        virtualCell && classes['root-virtualized'],
        isEditable &&
          editDisplayMode === 'cell' &&
          classes['root-cursor-pointer'],
        isEditable &&
          ['cell', 'table'].includes(editDisplayMode ?? '') &&
          columnDefType !== 'display' &&
          classes['root-editable-hover'],
        columnDefType === 'data' && classes['root-data-col'],
        density === 'xs' && classes['root-nowrap'],
        columnDef.enableCellHoverReveal && classes['root-cell-hover-reveal'],
        tableCellProps?.className,
      )}
      onDoubleClick={handleDoubleClick}
      onDragEnter={handleDragEnter}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      style={(theme) => ({
        ...widthStyles,
        ...parseFromValuesOrFunc(tableCellProps.style, theme),
      })}
    >
      <>
        {tableCellProps.children ??
          (columnDef.enableCellHoverReveal ? (
            <div
              className={clsx(
                columnDef.enableCellHoverReveal &&
                  !(isCreating || isEditing) &&
                  classes['cell-hover-reveal'],
                isCellContentOverflowing && classes['overflowing'],
              )}
              ref={cellHoverRevealDivRef}
            >
              {renderCellContent()}
              {cell.getIsGrouped() && !columnDef.GroupedCell && (
                <> ({row.subRows?.length})</>
              )}
            </div>
          ) : (
            <>
              {renderCellContent()}
              {cell.getIsGrouped() && !columnDef.GroupedCell && (
                <> ({row.subRows?.length})</>
              )}
            </>
          ))}
      </>
    </TableTd>
  )
}

export const Memo_MRT_TableBodyCell = memo(
  MRT_TableBodyCell,
  (prev, next) => next.cell === prev.cell,
) as typeof MRT_TableBodyCell

import { Highlight } from '@mantine/core'
import { parseFromValuesOrFunc } from '../../utils/utils'
import type { HighlightProps } from '@mantine/core'

import type {
  MRT_Cell,
  MRT_CellValue,
  MRT_RowData,
  MRT_TableInstance,
} from '../../types'

const allowedTypes = ['string', 'number']
const allowedFilterVariants = ['text', 'autocomplete']

interface Props<TData extends MRT_RowData, TValue = MRT_CellValue> {
  cell: MRT_Cell<TData, TValue>
  renderedColumnIndex?: number
  renderedRowIndex?: number
  table: MRT_TableInstance<TData>
}

export const MRT_TableBodyCellValue = <TData extends MRT_RowData>({
  cell,
  renderedColumnIndex = 0,
  renderedRowIndex = 0,
  table,
}: Props<TData>) => {
  const {
    state,
    options: {
      enableFilterMatchHighlighting,
      mantineHighlightProps = { size: 'sm' },
    },
  } = table
  const { column, row } = cell
  const { columnDef } = column
  const { globalFilter, globalFilterFn } = state
  const filterValue = column.getFilterValue()

  const highlightProps = parseFromValuesOrFunc(mantineHighlightProps, {
    cell,
    column,
    row,
    table,
  }) as Partial<HighlightProps>

  let renderedCellValue =
    cell.getIsAggregated() && columnDef.AggregatedCell
      ? columnDef.AggregatedCell({
          cell,
          column,
          row,
          table,
        })
      : row.getIsGrouped() && !cell.getIsGrouped()
        ? null
        : cell.getIsGrouped() && columnDef.GroupedCell
          ? columnDef.GroupedCell({
              cell,
              column,
              row,
              table,
            })
          : undefined

  const isGroupedValue = renderedCellValue !== undefined

  if (!isGroupedValue) {
    renderedCellValue = cell.renderValue() as number | string
  }

  if (
    enableFilterMatchHighlighting &&
    columnDef.enableFilterMatchHighlighting !== false &&
    renderedCellValue &&
    allowedTypes.includes(typeof renderedCellValue) &&
    ((filterValue &&
      allowedTypes.includes(typeof filterValue) &&
      allowedFilterVariants.includes(columnDef.filterVariant as string)) ||
      (globalFilter &&
        allowedTypes.includes(typeof globalFilter) &&
        column.getCanGlobalFilter()))
  ) {
    let highlight: string | Array<string> = (
      column.getFilterValue() ??
      globalFilter ??
      ''
    ).toString() as string
    if ((filterValue ? columnDef._filterFn : globalFilterFn) === 'fuzzy') {
      highlight = highlight.split(' ')
    }

    renderedCellValue = (
      <Highlight color="yellow.3" highlight={highlight} {...highlightProps}>
        {renderedCellValue?.toString()}
      </Highlight>
    )
  }

  if (columnDef.Cell && !isGroupedValue) {
    renderedCellValue = columnDef.Cell({
      cell,
      column,
      renderedCellValue,
      renderedColumnIndex,
      renderedRowIndex,
      row,
      table,
    })
  }

  return renderedCellValue
}

