  columnVirtualizer,
  table,
  ...rest
}: Props<TData>) => {
  const {
    getHeaderGroups,
    getSelectedRowModel,
    state,
    options: {
      enableStickyHeader,
      layoutMode,
      mantineTableHeadProps,
      positionToolbarAlertBanner,
    },
    refs: { tableHeadRef },
  } = table
  const { isFullScreen, showAlertBanner } = state

  const tableHeadProps = {
    ...parseFromValuesOrFunc(mantineTableHeadProps, {
      table,
    }),
    ...rest,
  }

  const stickyHeader = enableStickyHeader || isFullScreen

  return (
    <TableThead
      {...tableHeadProps}
      className={clsx(
        classes.root,
        layoutMode?.startsWith('grid')
          ? classes['root-grid']
          : classes['root-table-row-group'],
        stickyHeader && classes['root-sticky'],
        tableHeadProps?.className,
      )}
      pos={
        stickyHeader && layoutMode?.startsWith('grid') ? 'sticky' : 'relative'
      }
      ref={(ref: HTMLTableSectionElement) => {
        tableHeadRef.current = ref
        if (tableHeadProps?.ref) {
          // @ts-ignore
          tableHeadProps.ref.current = ref
        }
      }}
    >
      {positionToolbarAlertBanner === 'head-overlay' &&
      (showAlertBanner || getSelectedRowModel().rows.length > 0) ? (
        <TableTr
          className={clsx(
            classes['banner-tr'],
            layoutMode?.startsWith('grid') && classes.grid,
          )}
        >
          <TableTh
            className={clsx(
              classes['banner-th'],
              layoutMode?.startsWith('grid') && classes.grid,
            )}
            colSpan={table.getVisibleLeafColumns().length}
          >
            <MRT_ToolbarAlertBanner table={table} />
          </TableTh>
        </TableTr>
      ) : (
        getHeaderGroups().map((headerGroup) => (
          <MRT_TableHeadRow
            columnVirtualizer={columnVirtualizer}
            headerGroup={headerGroup as any}
            key={headerGroup.id}
            table={table}
          />
        ))
      )}
    </TableThead>
  )
}

import clsx from 'clsx'

import { useMemo, useState } from 'react'

import { Flex, TableTh, useDirection } from '@mantine/core'
import { useHover } from '@mantine/hooks'

import { parseCSSVarId } from '../../utils/style.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_ColumnActionMenu } from '../menus/MRT_ColumnActionMenu'
import { MRT_TableHeadCellFilterContainer } from './MRT_TableHeadCellFilterContainer'
import { MRT_TableHeadCellFilterLabel } from './MRT_TableHeadCellFilterLabel'
import { MRT_TableHeadCellGrabHandle } from './MRT_TableHeadCellGrabHandle'
import { MRT_TableHeadCellResizeHandle } from './MRT_TableHeadCellResizeHandle'
import { MRT_TableHeadCellSortLabel } from './MRT_TableHeadCellSortLabel'

import classes from './MRT_TableHeadCell.module.css'
import type {
  MRT_ColumnVirtualizer,
  MRT_Header,
  MRT_RowData,
  MRT_TableInstance,
} from '../../types'
import type { TableThProps } from '@mantine/core'
import type { CSSProperties, DragEventHandler, ReactNode } from 'react'

interface Props<TData extends MRT_RowData> extends TableThProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
  header: MRT_Header<TData>
  renderedHeaderIndex?: number
  table: MRT_TableInstance<TData>
}

export const MRT_TableHeadCell = <TData extends MRT_RowData>({
  columnVirtualizer,
  header,
  renderedHeaderIndex = 0,
  table,
  ...rest
}: Props<TData>) => {
  const direction = useDirection()
  const {
    state,
    options: {
      columnFilterDisplayMode,
      columnResizeDirection,
      columnResizeMode,
      enableColumnActions,
      enableColumnDragging,
      enableColumnOrdering,
      enableColumnPinning,
      enableGrouping,
      enableHeaderActionsHoverReveal,
      enableMultiSort,
      layoutMode,
      mantineTableHeadCellProps,
    },
    refs: { tableHeadCellRefs },
    setHoveredColumn,
  } = table
  const { columnResizing, draggingColumn, grouping, hoveredColumn } = state
  const { column } = header
  const { columnDef } = column
  const { columnDefType } = columnDef

  const arg = { column, table }
  const tableCellProps = {
    ...parseFromValuesOrFunc(mantineTableHeadCellProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineTableHeadCellProps, arg),
    ...rest,
  }

  const widthStyles: CSSProperties = {
    minWidth: `max(calc(var(--header-${parseCSSVarId(
      header?.id,
    )}-size) * 1px), ${columnDef.minSize ?? 30}px)`,
    width: `calc(var(--header-${parseCSSVarId(header.id)}-size) * 1px)`,
  }
  if (layoutMode === 'grid') {
    widthStyles.flex = `${
      [0, false].includes(columnDef.grow!)
        ? 0
        : `var(--header-${parseCSSVarId(header.id)}-size)`
    } 0 auto`
  } else if (layoutMode === 'grid-no-grow') {
    widthStyles.flex = `${+(columnDef.grow || 0)} 0 auto`
  }

  const isColumnPinned =
    enableColumnPinning &&
    columnDef.columnDefType !== 'group' &&
    column.getIsPinned()

  const isDraggingColumn = draggingColumn?.id === column.id
  const isHoveredColumn = hoveredColumn?.id === column.id

  const { hovered: isHoveredHeadCell, ref: isHoveredHeadCellRef } =
    useHover<HTMLTableCellElement>()

  const [isOpenedColumnActions, setIsOpenedColumnActions] = useState(false)

  const columnActionsEnabled =
    (enableColumnActions || columnDef.enableColumnActions) &&
    columnDef.enableColumnActions !== false

  const showColumnButtons =
    !enableHeaderActionsHoverReveal ||
    isOpenedColumnActions ||
    (isHoveredHeadCell &&
      !table.getVisibleFlatColumns().find((column) => column.getIsResizing()))

  const showDragHandle =
    enableColumnDragging !== false &&
    columnDef.enableColumnDragging !== false &&
    (enableColumnDragging ||
      (enableColumnOrdering && columnDef.enableColumnOrdering !== false) ||
      (enableGrouping &&
        columnDef.enableGrouping !== false &&
        !grouping.includes(column.id))) &&
    showColumnButtons

  const headerPL = useMemo(() => {
    let pl = 0
    if (column.getCanSort()) pl++
    // Only add padding for buttons if they will actually be displayed
    if (showColumnButtons && (columnActionsEnabled || showDragHandle))
      pl += 1.75
    if (showDragHandle) pl += 1.25
    return pl
  }, [showColumnButtons, showDragHandle, columnActionsEnabled])

  const handleDragEnter: DragEventHandler<HTMLTableCellElement> = (_e) => {
    if (enableGrouping && hoveredColumn?.id === 'drop-zone') {
      setHoveredColumn(null)
    }
    if (enableColumnOrdering && draggingColumn && columnDefType !== 'group') {
      setHoveredColumn(columnDef.enableColumnOrdering !== false ? column : null)
    }
  }

  const headerElement =
    columnDef?.Header instanceof Function
      ? columnDef?.Header?.({
          column,
          header,
          table,
        })
      : (columnDef?.Header ?? (columnDef.header as ReactNode))

  return (
    <TableTh
      colSpan={header.colSpan}
      data-column-pinned={isColumnPinned || undefined}
      data-dragging-column={isDraggingColumn || undefined}
      data-first-end-pinned={
        (isColumnPinned === 'end' && column.getIsFirstColumn(isColumnPinned)) ||
        undefined
      }
      data-hovered-column-target={isHoveredColumn || undefined}
      data-index={renderedHeaderIndex}
      data-last-start-pinned={
        (isColumnPinned === 'start' &&
          column.getIsLastColumn(isColumnPinned)) ||
        undefined
      }
      data-resizing={
        (columnResizeMode === 'onChange' &&
          columnResizing?.isResizingColumn === column.id &&
          columnResizeDirection) ||
        undefined
      }
      {...tableCellProps}
      __vars={{
        '--mrt-table-cell-start':
          isColumnPinned === 'start'
            ? `${column.getStart(isColumnPinned)}`
            : undefined,
        '--mrt-table-cell-end':
          isColumnPinned === 'end'
            ? `${column.getAfter(isColumnPinned)}`
            : undefined,
      }}
      align={
        columnDefType === 'group'
          ? 'center'
          : direction.dir === 'rtl'
            ? 'right'
            : 'left'
      }
      className={clsx(
        classes.root,
        layoutMode?.startsWith('grid') && classes['root-grid'],
        enableMultiSort && column.getCanSort() && classes['root-no-select'],
        columnVirtualizer && classes['root-virtualized'],
        tableCellProps?.className,
      )}
      onDragEnter={handleDragEnter}
      ref={(node: HTMLTableCellElement) => {
        if (node) {
          tableHeadCellRefs.current[column.id] = node
          ;(isHoveredHeadCellRef as any).current = node
          if (columnDefType !== 'group') {
            columnVirtualizer?.measureElement?.(node)
          }
        }
      }}
      style={(theme) => ({
        ...widthStyles,
        ...parseFromValuesOrFunc(tableCellProps?.style, theme),
      })}
    >
      {header.isPlaceholder
        ? null
        : (tableCellProps.children ?? (
            <Flex
              className={clsx(
                'mrt-table-head-cell-content',
                classes.content,
                (columnDefType === 'group' ||
                  tableCellProps?.align === 'center') &&
                  classes['content-center'],
                tableCellProps?.align === 'right' && classes['content-right'],
                column.getCanResize() && classes['content-spaced'],
              )}
            >
              <Flex
                __vars={{
                  '--mrt-table-head-cell-labels-padding-left': `${headerPL}`,
                }}
                className={clsx(
                  'mrt-table-head-cell-labels',
                  classes.labels,
                  column.getCanSort() &&
                    columnDefType !== 'group' &&
                    classes['labels-sortable'],
                  tableCellProps?.align === 'right'
                    ? classes['labels-right']
                    : tableCellProps?.align === 'center' &&
                        classes['labels-center'],
                  columnDefType === 'data' && classes['labels-data'],
                )}
                onClick={column.getToggleSortingHandler()}
              >
                <Flex
                  className={clsx(
                    'mrt-table-head-cell-content-wrapper',
                    classes['content-wrapper'],
                    columnDefType === 'data' &&
                      classes['content-wrapper-hidden-overflow'],
                    (columnDef.header?.length ?? 0) < 20 &&
                      classes['content-wrapper-nowrap'],
                  )}
                >
                  {headerElement}
                </Flex>
                {column.getCanFilter() &&
                  (column.getIsFiltered() || showColumnButtons) && (
                    <MRT_TableHeadCellFilterLabel
                      header={header}
                      table={table}
                    />
                  )}
                {column.getCanSort() &&
                  (column.getIsSorted() || showColumnButtons) && (
                    <MRT_TableHeadCellSortLabel header={header} table={table} />
                  )}
              </Flex>
              {columnDefType !== 'group' && (
                <Flex
                  className={clsx(
                    'mrt-table-head-cell-content-actions',
                    classes['content-actions'],
                  )}
                >
                  {showDragHandle && (
                    <MRT_TableHeadCellGrabHandle
                      column={column}
                      table={table}
                      tableHeadCellRef={{
                        current: tableHeadCellRefs.current[column.id],
                      }}
                    />
                  )}
                  {columnActionsEnabled && showColumnButtons && (
                    <MRT_ColumnActionMenu
                      header={header}
                      onChange={setIsOpenedColumnActions}
                      opened={isOpenedColumnActions}
                      table={table}
                    />
                  )}
                </Flex>
              )}
              {column.getCanResize() && (
                <MRT_TableHeadCellResizeHandle header={header} table={table} />
              )}
            </Flex>
          ))}
      {columnFilterDisplayMode === 'subheader' && column.getCanFilter() && (
        <MRT_TableHeadCellFilterContainer header={header} table={table} />
      )}
    </TableTh>
  )
}

import { ActionIcon, Collapse, Flex, Menu, Text, Tooltip } from '@mantine/core'

import { localizedFilterOption } from '../../fns/filterFns'
import { MRT_FilterCheckbox } from '../inputs/MRT_FilterCheckbox'
import { MRT_FilterRangeFields } from '../inputs/MRT_FilterRangeFields'
import { MRT_FilterRangeSlider } from '../inputs/MRT_FilterRangeSlider'
import { MRT_FilterTextInput } from '../inputs/MRT_FilterTextInput'
import { MRT_FilterOptionMenu } from '../menus/MRT_FilterOptionMenu'
import classes from './MRT_TableHeadCellFilterContainer.module.css'
import type { MRT_Header, MRT_RowData, MRT_TableInstance } from '../../types'
import type { FlexProps } from '@mantine/core'

interface Props<TData extends MRT_RowData> extends FlexProps {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_TableHeadCellFilterContainer = <TData extends MRT_RowData>({
  header,
  table,
  ...rest
}: Props<TData>) => {
  const {
    state,
    options: {
      columnFilterDisplayMode,
      columnFilterModeOptions,
      enableColumnFilterModes,
      icons: { IconFilterCog },
      localization,
    },
    refs: { filterInputRefs },
  } = table
  const { showColumnFilters } = state
  const { column } = header
  const { columnDef } = column

  const currentFilterOption = columnDef._filterFn
  const allowedColumnFilterOptions =
    columnDef?.columnFilterModeOptions ?? columnFilterModeOptions
  const showChangeModeButton =
    enableColumnFilterModes &&
    columnDef.enableColumnFilterModes !== false &&
    (allowedColumnFilterOptions === undefined ||
      !!allowedColumnFilterOptions?.length)

  return (
    <Collapse
      expanded={showColumnFilters || columnFilterDisplayMode === 'popover'}
    >
      <Flex direction="column" {...rest}>
        <Flex align="flex-end">
          {columnDef.filterVariant === 'checkbox' ? (
            <MRT_FilterCheckbox column={column} table={table} />
          ) : columnDef.filterVariant === 'range-slider' ? (
            <MRT_FilterRangeSlider header={header} table={table} />
          ) : ['date-range', 'range'].includes(columnDef.filterVariant ?? '') ||
            ['between', 'betweenInclusive', 'inNumberRange'].includes(
              columnDef._filterFn,
            ) ? (
            <MRT_FilterRangeFields header={header} table={table} />
          ) : (
            <MRT_FilterTextInput header={header} table={table} />
          )}
          {showChangeModeButton && (
            <Menu withinPortal={columnFilterDisplayMode !== 'popover'}>
              <Tooltip
                label={localization.changeFilterMode}
                position="bottom-start"
                withinPortal
              >
                <Menu.Target>
                  <ActionIcon
                    aria-label={localization.changeFilterMode}
                    color="gray"
                    size="md"
                    variant="subtle"
                  >
                    <IconFilterCog />
                  </ActionIcon>
                </Menu.Target>
              </Tooltip>
              <MRT_FilterOptionMenu
                header={header}
                onSelect={() =>
                  setTimeout(
                    () => filterInputRefs.current[`${column.id}-0`]?.focus(),
                    100,
                  )
                }
                table={table}
              />
            </Menu>
          )}
        </Flex>
        {showChangeModeButton ? (
          <Text
            c="dimmed"
            className={classes['filter-mode-label']}
            component="label"
          >
            {localization.filterMode.replace(
              '{filterType}',
              localizedFilterOption(localization, currentFilterOption),
            )}
          </Text>
        ) : null}
      </Flex>
    </Collapse>
  )
}

import clsx from 'clsx'

import { useState } from 'react'

import { ActionIcon, Popover, Tooltip, Transition } from '@mantine/core'

import { localizedFilterOption } from '../../fns/filterFns'
import { dataVariable } from '../../utils/style.utils'
import { MRT_TableHeadCellFilterContainer } from './MRT_TableHeadCellFilterContainer'
import classes from './MRT_TableHeadCellFilterLabel.module.css'
import type { MRT_Header, MRT_RowData, MRT_TableInstance } from '../../types'
import type { ActionIconProps } from '@mantine/core'
import type { MouseEvent } from 'react'

interface Props<TData extends MRT_RowData> extends ActionIconProps {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_TableHeadCellFilterLabel = <TData extends MRT_RowData>({
  header,
  table,
  ...rest
}: Props<TData>) => {
  const {
    options: {
      columnFilterDisplayMode,
      icons: { IconFilter },
      localization,
    },
    refs: { filterInputRefs },
    setShowColumnFilters,
  } = table
  const { column } = header
  const { columnDef } = column

  const filterValue = column.getFilterValue()

  const [popoverOpened, setPopoverOpened] = useState(false)

  const isFilterActive =
    (Array.isArray(filterValue) && filterValue.some(Boolean)) ||
    (!!filterValue && !Array.isArray(filterValue))

  const isRangeFilter =
    columnDef.filterVariant === 'range' ||
    columnDef.filterVariant === 'date-range' ||
    ['between', 'betweenInclusive', 'inNumberRange'].includes(
      columnDef._filterFn,
    )
  const currentFilterOption = columnDef._filterFn
  const filterValueFn =
    columnDef.filterTooltipValueFn || ((value) => value as string)
  type FilterValueType = Parameters<typeof filterValueFn>[0]
  const filterTooltip =
    columnFilterDisplayMode === 'popover' && !isFilterActive
      ? localization.filterByColumn?.replace(
          '{column}',
          String(columnDef.header),
        )
      : localization.filteringByColumn
          .replace('{column}', String(columnDef.header))
          .replace(
            '{filterType}',
            localizedFilterOption(localization, currentFilterOption),
          )
          .replace(
            '{filterValue}',
            `"${
              Array.isArray(column.getFilterValue())
                ? (
                    column.getFilterValue() as [
                      FilterValueType,
                      FilterValueType,
                    ]
                  )
                    .map((v) => filterValueFn(v))
                    .join(
                      `" ${isRangeFilter ? localization.and : localization.or} "`,
                    )
                : filterValueFn(column.getFilterValue())
            }"`,
          )
          .replace('" "', '')

  return (
    <>
      <Popover
        keepMounted={columnDef.filterVariant === 'range-slider'}
        onChange={setPopoverOpened}
        onClose={() => setPopoverOpened(false)}
        opened={popoverOpened}
        position="top"
        shadow="xl"
        width={360}
        withinPortal
      >
        <Transition
          mounted={
            columnFilterDisplayMode === 'popover' ||
            (!!column.getFilterValue() && !isRangeFilter) ||
            (isRangeFilter &&
              (!!(column.getFilterValue() as [any, any])?.[0] ||
                !!(column.getFilterValue() as [any, any])?.[1]))
          }
          transition="scale"
        >
          {() => (
            <Popover.Target>
              <Tooltip
                disabled={popoverOpened}
                label={filterTooltip}
                multiline
                w={filterTooltip.length > 40 ? 300 : undefined}
                withinPortal
              >
                <ActionIcon
                  aria-label={filterTooltip}
                  className={clsx(
                    'mrt-table-head-cell-filter-label-icon',
                    classes.root,
                  )}
                  size={18}
                  {...dataVariable('active', isFilterActive)}
                  onClick={(event: MouseEvent<HTMLButtonElement>) => {
                    event.stopPropagation()
                    if (columnFilterDisplayMode === 'popover') {
                      setPopoverOpened((opened) => !opened)
                    } else {
                      setShowColumnFilters(true)
                    }
                    setTimeout(() => {
                      const input = filterInputRefs.current[`${column.id}-0`]
                      input?.focus()
                      input?.select()
                    }, 100)
                  }}
                  {...rest}
                >
                  <IconFilter size="100%" />
                </ActionIcon>
              </Tooltip>
            </Popover.Target>
          )}
        </Transition>
        {columnFilterDisplayMode === 'popover' && (
          <Popover.Dropdown
            onClick={(event) => event.stopPropagation()}
            onKeyDown={(event) =>
              event.key === 'Enter' && setPopoverOpened(false)
            }
            onMouseDown={(event) => event.stopPropagation()}
          >
            <MRT_TableHeadCellFilterContainer header={header} table={table} />
          </Popover.Dropdown>
        )}
      </Popover>
    </>
  )
}

import { reorderColumn } from '../../utils/column.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_GrabHandleButton } from '../buttons/MRT_GrabHandleButton'
import type { DragEvent, RefObject } from 'react'

import type { ActionIconProps } from '@mantine/core'

import type {
  MRT_CellValue,
  MRT_Column,
  MRT_RowData,
  MRT_TableInstance,
} from '../../types'

interface Props<
  TData extends MRT_RowData,
  TValue = MRT_CellValue,
> extends ActionIconProps {
  column: MRT_Column<TData, TValue>
  table: MRT_TableInstance<TData>
  tableHeadCellRef: RefObject<HTMLTableCellElement>
}

export const MRT_TableHeadCellGrabHandle = <TData extends MRT_RowData>({
  column,
  table,
  tableHeadCellRef,
  ...rest
}: Props<TData>) => {
  const {
    state,
    options: { enableColumnOrdering, mantineColumnDragHandleProps },
    setColumnOrder,
    setDraggingColumn,
    setHoveredColumn,
  } = table
  const { columnDef } = column
  const { columnOrder, draggingColumn, hoveredColumn } = state

  const arg = { column, table }
  const actionIconProps = {
    ...parseFromValuesOrFunc(mantineColumnDragHandleProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineColumnDragHandleProps, arg),
    ...rest,
  }

  const handleDragStart = (event: DragEvent<HTMLButtonElement>) => {
    actionIconProps?.onDragStart?.(event)
    setDraggingColumn(column)
    event.dataTransfer.setDragImage(tableHeadCellRef.current, 0, 0)
  }

  const handleDragEnd = (event: DragEvent<HTMLButtonElement>) => {
    actionIconProps?.onDragEnd?.(event)
    if (hoveredColumn?.id === 'drop-zone') {
      column.toggleGrouping()
    } else if (
      enableColumnOrdering &&
      hoveredColumn &&
      hoveredColumn?.id !== draggingColumn?.id
    ) {
      setColumnOrder(
        reorderColumn(column, hoveredColumn as MRT_Column<TData>, columnOrder),
      )
    }
    setDraggingColumn(null)
    setHoveredColumn(null)
  }

  return (
    <MRT_GrabHandleButton
      actionIconProps={actionIconProps}
      onDragEnd={handleDragEnd}
      onDragStart={handleDragStart}
      table={table}
    />
  )
}

import clsx from 'clsx'

import { Box } from '@mantine/core'
import classes from './MRT_TableHeadCellResizeHandle.module.css'
import type { BoxProps } from '@mantine/core'

import type { MRT_Header, MRT_RowData, MRT_TableInstance } from '../../types'

interface Props<TData extends MRT_RowData> extends BoxProps {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_TableHeadCellResizeHandle = <TData extends MRT_RowData>({
  header,
  table,
  ...rest
}: Props<TData>) => {
  const {
    state,
    options: { columnResizeDirection, columnResizeMode },
    setColumnResizing,
  } = table
  const { density } = state
  const { column } = header
  const handler = header.getResizeHandler()

  const offset =
    column.getIsResizing() && columnResizeMode === 'onEnd'
      ? `translateX(${
          (columnResizeDirection === 'rtl' ? -1 : 1) *
          (state.columnResizing.deltaOffset ?? 0)
        }px)`
      : undefined

  return (
    <Box
      onDoubleClick={() => {
        setColumnResizing((old) => ({
          ...old,
          isResizingColumn: false,
        }))
        column.resetSize()
      }}
      onMouseDown={handler}
      onTouchStart={handler}
      role="separator"
      {...rest}
      __vars={{ '--mrt-transform': offset, ...rest.__vars }}
      className={clsx(
        'mrt-table-head-cell-resize-handle',
        classes.root,
        classes[`root-${columnResizeDirection}`],
        !header.subHeaders.length &&
          columnResizeMode === 'onChange' &&
          classes['root-hide'],
        density,
        rest.className,
      )}
    />
  )
}

import clsx from 'clsx'

import { ActionIcon, Indicator, Tooltip } from '@mantine/core'
import { Subscribe } from '@tanstack/react-table'
import { dataVariable } from '../../utils/style.utils'
import classes from './MRT_TableHeadCellSortLabel.module.css'
import type { ActionIconProps } from '@mantine/core'

import type { MRT_Header, MRT_RowData, MRT_TableInstance } from '../../types'

interface Props<TData extends MRT_RowData> extends ActionIconProps {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_TableHeadCellSortLabel = <TData extends MRT_RowData>({
  header,
  table,
  ...rest
}: Props<TData>) => {
  const {
    options: {
      icons: { IconArrowsSort, IconSortAscending, IconSortDescending },
      localization,
    },
  } = table
  const column = header.column
  const { columnDef } = column

  return (
    <Subscribe source={table.atoms.sorting}>
      {(sorting) => {
        const sorted = column.getIsSorted()
        const sortIndex = column.getSortIndex()

        const sortTooltip = sorted
          ? sorted === 'desc'
            ? localization.sortedByColumnDesc.replace(
                '{column}',
                columnDef.header,
              )
            : localization.sortedByColumnAsc.replace(
                '{column}',
                columnDef.header,
              )
          : column.getNextSortingOrder() === 'desc'
            ? localization.sortByColumnDesc.replace(
                '{column}',
                columnDef.header,
              )
            : localization.sortByColumnAsc.replace('{column}', columnDef.header)

        const SortActionButton = (
          <ActionIcon
            aria-label={sortTooltip}
            {...dataVariable('sorted', sorted)}
            {...rest}
            className={clsx(
              'mrt-table-head-sort-button',
              classes['sort-icon'],
              rest.className,
            )}
          >
            {sorted === 'desc' ? (
              <IconSortDescending size="100%" />
            ) : sorted === 'asc' ? (
              <IconSortAscending size="100%" />
            ) : (
              <IconArrowsSort size="100%" />
            )}
          </ActionIcon>
        )

        return (
          <Tooltip label={sortTooltip} openDelay={1000} withinPortal>
            {sorting.length < 2 || sortIndex === -1 ? (
              SortActionButton
            ) : (
              <Indicator
                classNames={{
                  root: clsx(
                    'mrt-table-head-multi-sort-indicator',
                    classes['multi-sort-indicator'],
                  ),
                }}
                inline
                label={sortIndex + 1}
                offset={4}
              >
                {SortActionButton}
              </Indicator>
            )}
          </Tooltip>
        )
      }}
    </Subscribe>
  )
}

import clsx from 'clsx'

import { Box, TableTr } from '@mantine/core'

import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_TableHeadCell } from './MRT_TableHeadCell'
import classes from './MRT_TableHeadRow.module.css'
import type {
  MRT_ColumnVirtualizer,
  MRT_Header,
  MRT_HeaderGroup,
  MRT_RowData,
  MRT_TableInstance,
  MRT_VirtualItem,
} from '../../types'
import type { TableTrProps } from '@mantine/core'

interface Props<TData extends MRT_RowData> extends TableTrProps {
  columnVirtualizer?: MRT_ColumnVirtualizer
  headerGroup: MRT_HeaderGroup<TData>
  table: MRT_TableInstance<TData>
}

export const MRT_TableHeadRow = <TData extends MRT_RowData>({
  columnVirtualizer,
  headerGroup,
  table,
  ...rest
}: Props<TData>) => {
  const {
    state,
    options: { enableStickyHeader, layoutMode, mantineTableHeadRowProps },
  } = table
  const { isFullScreen } = state

  const { virtualColumns, virtualPaddingLeft, virtualPaddingRight } =
    columnVirtualizer ?? {}

  const tableRowProps = {
    ...parseFromValuesOrFunc(mantineTableHeadRowProps, {
      headerGroup,
      table,
    }),
    ...rest,
  }

  return (
    <TableTr
      {...tableRowProps}
      className={clsx(
        classes.root,
        (enableStickyHeader || isFullScreen) && classes.sticky,
        layoutMode?.startsWith('grid') && classes['layout-mode-grid'],
        tableRowProps?.className,
      )}
    >
      {virtualPaddingLeft ? (
        <Box component="th" display="flex" w={virtualPaddingLeft} />
      ) : null}
      {(virtualColumns ?? headerGroup.headers).map(
        (headerOrVirtualHeader, renderedHeaderIndex) => {
          let header = headerOrVirtualHeader as MRT_Header<TData>
          if (columnVirtualizer) {
            renderedHeaderIndex = (headerOrVirtualHeader as MRT_VirtualItem)
              .index
            header = headerGroup.headers[renderedHeaderIndex]
          }

          return (
            <MRT_TableHeadCell
              columnVirtualizer={columnVirtualizer}
              header={header}
              key={header.id}
              renderedHeaderIndex={renderedHeaderIndex}
              table={table}
            />
          )
        },
      )}
      {virtualPaddingRight ? (
        <Box component="th" display="flex" w={virtualPaddingRight} />
      ) : null}
    </TableTr>
  )
}

import { useState } from 'react'
import { MultiSelect, Select, TextInput } from '@mantine/core'
import { parseFromValuesOrFunc } from '../../utils/utils'
import type { FocusEvent, KeyboardEvent } from 'react'

import type {
  MultiSelectProps,
  SelectProps,
  TextInputProps,
} from '@mantine/core'

import type {
  HTMLPropsRef,
  MRT_Cell,
  MRT_CellValue,
  MRT_RowData,
  MRT_TableInstance,
} from '../../types'

interface PropsTextInput<
  TData extends MRT_RowData,
  TValue = MRT_CellValue,
> extends TextInputProps {
  cell: MRT_Cell<TData, TValue>
  table: MRT_TableInstance<TData>
}

interface PropsSelect<
  TData extends MRT_RowData,
  TValue = MRT_CellValue,
> extends SelectProps {
  cell: MRT_Cell<TData, TValue>
  table: MRT_TableInstance<TData>
}

interface PropsMultiSelect<
  TData extends MRT_RowData,
  TValue = MRT_CellValue,
> extends MultiSelectProps {
  cell: MRT_Cell<TData, TValue>
  table: MRT_TableInstance<TData>
}

type MRT_TextInputProps = HTMLPropsRef<HTMLInputElement> & TextInputProps
type MRT_SelectProps = HTMLPropsRef<HTMLInputElement> & SelectProps
type MRT_MultiSelectProps = HTMLPropsRef<HTMLInputElement> & MultiSelectProps

export const MRT_EditCellTextInput = <TData extends MRT_RowData>({
  cell,
  table,
  ...rest
}: PropsMultiSelect<TData> | PropsSelect<TData> | PropsTextInput<TData>) => {
  const {
    state,
    options: {
      createDisplayMode,
      editDisplayMode,
      mantineEditSelectProps,
      mantineEditTextInputProps,
    },
    refs: { editInputRefs },
    setCreatingRow,
    setEditingCell,
    setEditingRow,
  } = table
  const { column, row } = cell
  const { columnDef } = column
  const { creatingRow, editingRow } = state

  const isCreating = creatingRow?.id === row.id
  const isEditing = editingRow?.id === row.id
  const isSelectEdit = columnDef.editVariant === 'select'
  const isMultiSelectEdit = columnDef.editVariant === 'multi-select'

  const [value, setValue] = useState(() => cell.getValue<any>())

  const arg = { cell, column, row, table }
  const textInputProps = {
    ...parseFromValuesOrFunc(mantineEditTextInputProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineEditTextInputProps, arg),
    ...rest,
  } as MRT_TextInputProps

  const selectProps = {
    ...parseFromValuesOrFunc(mantineEditSelectProps, arg),
    ...parseFromValuesOrFunc(columnDef.mantineEditSelectProps, arg),
    ...rest,
  }

  const saveInputValueToRowCache = (newValue: null | string) => {
    // @ts-ignore
    row._valuesCache[column.id] = newValue
    if (isCreating) {
      setCreatingRow(row)
    } else if (isEditing) {
      setEditingRow(row)
    }
  }

  const handleBlur = (event: FocusEvent<HTMLInputElement>) => {
    textInputProps.onBlur?.(event)
    saveInputValueToRowCache(value)
    setEditingCell(null)
  }

  const handleEnterKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    textInputProps.onKeyDown?.(event)
    if (event.key === 'Enter') {
      editInputRefs.current[cell.id]?.blur()
    }
  }

  if (columnDef.Edit) {
    return columnDef.Edit?.({ cell, column, row, table })
  }

  const commonProps = {
    disabled: parseFromValuesOrFunc(columnDef.enableEditing, row) === false,
    label: ['custom', 'modal'].includes(
      (isCreating ? createDisplayMode : editDisplayMode) as string,
    )
      ? column.columnDef.header
      : undefined,
    name: cell.id,
    onClick: (e: any) => {
      e.stopPropagation()
      textInputProps?.onClick?.(e)
    },
    placeholder: !['custom', 'modal'].includes(
      (isCreating ? createDisplayMode : editDisplayMode) as string,
    )
      ? columnDef.header
      : undefined,
    value,
    variant: editDisplayMode === 'table' ? 'unstyled' : 'default',
  } as const

  if (isSelectEdit) {
    return (
      <Select
        {...commonProps}
        searchable
        value={value}
        {...(selectProps as MRT_SelectProps)}
        onBlur={handleBlur}
        onChange={(value, option) => {
          ;(selectProps as MRT_SelectProps).onChange?.(value, option)
          setValue(value)
        }}
        onClick={(e) => {
          e.stopPropagation()
          selectProps?.onClick?.(e)
        }}
        ref={(node) => {
          if (node) {
            editInputRefs.current[cell.id] = node
            if (selectProps.ref && typeof selectProps.ref === 'object') {
              selectProps.ref.current = node
            }
          }
        }}
      />
    )
  }

  if (isMultiSelectEdit) {
    return (
      <MultiSelect
        {...commonProps}
        searchable
        value={value}
        {...(selectProps as MRT_MultiSelectProps)}
        onBlur={handleBlur}
        onChange={(newValue) => {
          ;(selectProps as MRT_MultiSelectProps).onChange?.(value)
          setValue(newValue)
          // Save if not in focus, otherwise it will be handled by onBlur
          if (document.activeElement === editInputRefs.current[cell.id]) return
          saveInputValueToRowCache(newValue as any)
        }}
        onClick={(e) => {
          e.stopPropagation()
          selectProps?.onClick?.(e)
        }}
        ref={(node) => {
          if (node) {
            editInputRefs.current[cell.id] = node
            if (selectProps.ref && typeof selectProps.ref === 'object') {
              selectProps.ref.current = node
            }
          }
        }}
      />
    )
  }

  return (
    <TextInput
      {...commonProps}
      onKeyDown={handleEnterKeyDown}
      value={value ?? ''}
      {...textInputProps}
      onBlur={handleBlur}
      onChange={(event) => {
        textInputProps.onChange?.(event)
        setValue(event.target.value)
      }}
      onClick={(event) => {
        event.stopPropagation()
        textInputProps?.onClick?.(event)
      }}
      ref={(node) => {
        if (node) {
          editInputRefs.current[cell.id] = node
          if (textInputProps.ref) {
            textInputProps.ref.current = node
          }
        }
      }}
    />
  )
}

import clsx from 'clsx'

import { Checkbox, Tooltip } from '@mantine/core'
import { parseFromValuesOrFunc } from '../../utils/utils'
import classes from './MRT_FilterCheckBox.module.css'
