import { useEffect, useRef, useState } from 'react'
import FormHelperText from '@mui/material/FormHelperText'
import Slider from '@mui/material/Slider'
import Stack from '@mui/material/Stack'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { SliderProps } from '@mui/material/Slider'
import type { MRT_Header, MRT_RowData } from '../../types'

export interface MRT_FilterRangeSliderProps<
  TData extends MRT_RowData,
> extends SliderProps {
  header: MRT_Header<TData>
}

export const MRT_FilterRangeSlider = <TData extends MRT_RowData>({
  header,
  ...rest
}: MRT_FilterRangeSliderProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    options: { enableColumnFilterModes, localization, muiFilterSliderProps },
    refs: { filterInputRefs },
  } = table
  const { column } = header
  const { columnDef } = column

  const currentFilterOption = columnDef._filterFn!

  const showChangeModeButton =
    enableColumnFilterModes && columnDef.enableColumnFilterModes !== false

  const sliderProps = {
    ...parseFromValuesOrFunc(muiFilterSliderProps, { column, table }),
    ...parseFromValuesOrFunc(columnDef.muiFilterSliderProps, { column, table }),
    ...rest,
  }

  let [min, max] =
    sliderProps.min !== undefined && sliderProps.max !== undefined
      ? [sliderProps.min, sliderProps.max]
      : (column.getFacetedMinMaxValues() ?? [0, 1])

  // fix potential TanStack Table bugs where min or max is an array
  if (Array.isArray(min)) min = min[0]
  if (Array.isArray(max)) max = max[0]
  if (min === null) min = 0
  if (max === null) max = 1

  const [filterValues, setFilterValues] = useState([min, max])
  const columnFilterValue = column.getFilterValue()

  const isMounted = useRef(false)

  // prevent moving the focus to the next/prev cell when using the arrow keys
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.stopPropagation()
    }
  }

  useEffect(() => {
    if (isMounted.current) {
      if (columnFilterValue === undefined) {
        setFilterValues([min, max])
      } else if (Array.isArray(columnFilterValue)) {
        setFilterValues(columnFilterValue)
      }
    }
    isMounted.current = true
  }, [columnFilterValue, min, max])

  return (
    <Stack>
      <Slider
        disableSwap
        max={max}
        min={min}
        onChange={(_event, values) => {
          setFilterValues(values as [number, number])
        }}
        onChangeCommitted={(_event, value) => {
          if (Array.isArray(value)) {
            if (value[0] <= min && value[1] >= max) {
              // if the user has selected the entire range, remove the filter
              column.setFilterValue(undefined)
            } else {
              column.setFilterValue(value)
            }
          }
        }}
        onKeyDown={handleKeyDown}
        value={filterValues}
        valueLabelDisplay="auto"
        {...sliderProps}
        slotProps={{
          input: {
            ref: (node) => {
              if (node) {
                filterInputRefs.current![`${column.id}-0`] = node
                // @ts-expect-error
                if (sliderProps?.slotProps?.input?.ref) {
                  // @ts-expect-error
                  sliderProps.slotProps.input.ref = node
                }
              }
            },
          },
        }}
        sx={(theme) => ({
          m: 'auto',
          minWidth: `${column.getSize() - 50}px`,
          mt: !showChangeModeButton ? '10px' : '6px',
          px: '4px',
          width: 'calc(100% - 8px)',
          ...(parseFromValuesOrFunc(sliderProps?.sx, theme) as any),
        })}
      />
      {showChangeModeButton ? (
        <FormHelperText
          sx={{
            fontSize: '0.75rem',
            lineHeight: '0.8rem',
            m: '-3px -6px',
            whiteSpace: 'nowrap',
          }}
        >
          {localization.filterMode.replace(
            '{filterType}',
            localization[
              `filter${
                currentFilterOption?.charAt(0)?.toUpperCase() +
                currentFilterOption?.slice(1)
              }` as keyof typeof localization
            ],
          )}
        </FormHelperText>
      ) : null}
    </Stack>
  )
}

import { useEffect, useRef, useState } from 'react'
import Autocomplete from '@mui/material/Autocomplete'
import Box from '@mui/material/Box'
import Checkbox from '@mui/material/Checkbox'
import Chip from '@mui/material/Chip'
import IconButton from '@mui/material/IconButton'
import InputAdornment from '@mui/material/InputAdornment'
import MenuItem from '@mui/material/MenuItem'
import TextField from '@mui/material/TextField'
import Tooltip from '@mui/material/Tooltip'
import { DatePicker } from '@mui/x-date-pickers/DatePicker'
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker'
import { TimePicker } from '@mui/x-date-pickers/TimePicker'
import { useDebouncedCallback } from '@tanstack/react-pacer/debouncer'
import {
  getColumnFilterInfo,
  useDropdownOptions,
} from '../../utils/column.utils'
import { getValueAndLabel, parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_FilterOptionMenu } from '../menus/MRT_FilterOptionMenu'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { DropdownOption, MRT_Header, MRT_RowData } from '../../types'
import type { TextFieldProps } from '@mui/material/TextField'
import type { ChangeEvent, MouseEvent, SyntheticEvent } from 'react'
import type { AutocompleteInputChangeReason } from '@mui/material/Autocomplete'

export interface MRT_FilterTextFieldProps<
  TData extends MRT_RowData,
> extends TextFieldProps<'standard'> {
  header: MRT_Header<TData>
  rangeFilterIndex?: number
}

export const MRT_FilterTextField = <TData extends MRT_RowData>({
  header,
  rangeFilterIndex,
  ...rest
}: MRT_FilterTextFieldProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    options: {
      enableColumnFilterModes,
      icons: { CloseIcon, FilterListIcon },
      localization,
      manualFiltering,
      muiFilterAutocompleteProps,
      muiFilterDatePickerProps,
      muiFilterDateTimePickerProps,
      muiFilterTextFieldProps,
      muiFilterTimePickerProps,
    },
    refs: { filterInputRefs },
    setColumnFilterFns,
  } = table
  const { column } = header
  const { columnDef } = column
  const { filterVariant } = columnDef

  const args = { column, rangeFilterIndex, table }

  const textFieldProps = {
    ...parseFromValuesOrFunc(muiFilterTextFieldProps, args),
    ...parseFromValuesOrFunc(columnDef.muiFilterTextFieldProps, args),
    ...rest,
  }

  const autocompleteProps = {
    ...parseFromValuesOrFunc(muiFilterAutocompleteProps, args),
    ...parseFromValuesOrFunc(columnDef.muiFilterAutocompleteProps, args),
  }

  const datePickerProps = {
    ...parseFromValuesOrFunc(muiFilterDatePickerProps, args),
    ...parseFromValuesOrFunc(columnDef.muiFilterDatePickerProps, args),
  } as any

  const dateTimePickerProps = {
    ...parseFromValuesOrFunc(muiFilterDateTimePickerProps, args),
    ...parseFromValuesOrFunc(columnDef.muiFilterDateTimePickerProps, args),
  } as any

  const timePickerProps = {
    ...parseFromValuesOrFunc(muiFilterTimePickerProps, args),
    ...parseFromValuesOrFunc(columnDef.muiFilterTimePickerProps, args),
  } as any

  const {
    allowedColumnFilterOptions,
    currentFilterOption,
    facetedUniqueValues,
    isAutocompleteFilter,
    isDateFilter,
    isMultiSelectFilter,
    isRangeFilter,
    isSelectFilter,
    isTextboxFilter,
  } = getColumnFilterInfo({ header, table })

  const dropdownOptions = useDropdownOptions({ header, table })

  const filterChipLabel = ['empty', 'notEmpty'].includes(currentFilterOption!)
    ? localization[
        `filter${
          currentFilterOption!.charAt(0)?.toUpperCase() +
          currentFilterOption!.slice(1)
        }` as keyof typeof localization
      ]
    : ''

  const filterPlaceholder = !isRangeFilter
    ? (textFieldProps?.placeholder ??
      localization.filterByColumn?.replace(
        '{column}',
        String(columnDef.header),
      ))
    : rangeFilterIndex === 0
      ? localization.min
      : rangeFilterIndex === 1
        ? localization.max
        : ''

  const showChangeModeButton = !!(
    enableColumnFilterModes &&
    columnDef.enableColumnFilterModes !== false &&
    !rangeFilterIndex &&
    (allowedColumnFilterOptions === undefined ||
      !!allowedColumnFilterOptions?.length)
  )

  const [anchorEl, setAnchorEl] = useState<HTMLElement | null>(null)
  const [filterValue, setFilterValue] = useState<string | Array<string>>(() =>
    isMultiSelectFilter
      ? (column.getFilterValue() as Array<string>) || []
      : isRangeFilter
        ? (column.getFilterValue() as [string, string])?.[
            rangeFilterIndex as number
          ] || ''
        : isAutocompleteFilter
          ? typeof column.getFilterValue() === 'string'
            ? (column.getFilterValue() as string)
            : ''
          : ((column.getFilterValue() as string) ?? ''),
  )
  const [autocompleteValue, setAutocompleteValue] =
    useState<DropdownOption | null>(() =>
      isAutocompleteFilter
        ? ((column.getFilterValue() || null) as DropdownOption | null)
        : null,
    )

  const handleChangeDebounced = useDebouncedCallback(
    (newValue: any) => {
      if (isRangeFilter) {
        column.setFilterValue((old: Array<Date | null | number | string>) => {
          const newFilterValues = old ?? ['', '']
          newFilterValues[rangeFilterIndex as number] = newValue ?? undefined
          return newFilterValues
        })
      } else {
        column.setFilterValue(newValue ?? undefined)
      }
    },
    { wait: isTextboxFilter ? (manualFiltering ? 400 : 200) : 1 },
  )

  const handleChange = (newValue: any) => {
    setFilterValue(newValue ?? '')
    handleChangeDebounced(newValue)
  }

  const handleTextFieldChange = (event: ChangeEvent<HTMLInputElement>) => {
    const newValue =
      textFieldProps.type === 'date'
        ? event.target.valueAsDate
        : textFieldProps.type === 'number'
          ? event.target.valueAsNumber
          : event.target.value
    handleChange(newValue)
    textFieldProps?.onChange?.(event)
  }

  const handleAutocompleteInputChange = (
    _event: SyntheticEvent,
    newValue: string,
    _reason: AutocompleteInputChangeReason,
  ) => {
    handleChange(newValue)
  }

  const handleAutocompleteChange = (newValue: DropdownOption | null) => {
    setAutocompleteValue(newValue)
    handleChangeDebounced(getValueAndLabel(newValue).value)
  }

  const handleClear = () => {
    if (isMultiSelectFilter) {
      setFilterValue([])
      column.setFilterValue([])
    } else if (isRangeFilter) {
      setFilterValue('')
      column.setFilterValue((old: [string | undefined, string | undefined]) => {
        const newFilterValues = (Array.isArray(old) && old) || ['', '']
        newFilterValues[rangeFilterIndex as number] = undefined
        return newFilterValues
      })
    } else if (isAutocompleteFilter) {
      setAutocompleteValue(null)
      setFilterValue('')
      // when using 'autocomplete' this function is called only inside effect and only if the filterValue === undefined
      // so the following call is excessive; should be uncommented if the handleClear becomes part of the Autocomplete component callbacks
      // column.setFilterValue(undefined)
    } else {
      setFilterValue('')
      column.setFilterValue(undefined)
    }
  }

  const handleClearEmptyFilterChip = () => {
    setFilterValue('')
    column.setFilterValue(undefined)
    setColumnFilterFns((prev) => ({
      ...prev,
      [header.id]: allowedColumnFilterOptions?.[0] ?? 'fuzzy',
    }))
  }

  const handleFilterMenuOpen = (event: MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget)
  }

  const isMounted = useRef(false)

  useEffect(() => {
    if (isMounted.current) {
      const filterValue = column.getFilterValue()
      if (filterValue === undefined) {
        handleClear()
      } else if (isRangeFilter && rangeFilterIndex !== undefined) {
        setFilterValue((filterValue as [string, string])[rangeFilterIndex])
      } else {
        setFilterValue(filterValue as string)
      }
    }
    isMounted.current = true
  }, [column.getFilterValue()])

  if (columnDef.Filter) {
    return (
      <>{columnDef.Filter?.({ column, header, rangeFilterIndex, table })}</>
    )
  }

  const endAdornment =
    !isAutocompleteFilter && !isDateFilter && !filterChipLabel ? (
      <InputAdornment
        position="end"
        sx={{
          mr: isSelectFilter || isMultiSelectFilter ? '20px' : undefined,
          visibility: (filterValue?.length ?? 0) > 0 ? 'visible' : 'hidden',
        }}
      >
        <Tooltip placement="right" title={localization.clearFilter ?? ''}>
          <span>
            <IconButton
              aria-label={localization.clearFilter}
              disabled={!filterValue?.toString()?.length}
              onClick={handleClear}
              size="small"
              sx={{
                height: '2rem',
                transform: 'scale(0.9)',
                width: '2rem',
              }}
            >
              <CloseIcon />
            </IconButton>
          </span>
        </Tooltip>
      </InputAdornment>
    ) : null

  const startAdornment = showChangeModeButton ? (
    <InputAdornment position="start">
      <Tooltip title={localization.changeFilterMode}>
        <span>
          <IconButton
            aria-label={localization.changeFilterMode}
            onClick={handleFilterMenuOpen}
            size="small"
            sx={{ height: '1.75rem', width: '1.75rem' }}
          >
            <FilterListIcon />
          </IconButton>
        </span>
      </Tooltip>
      {filterChipLabel && (
        <Chip label={filterChipLabel} onDelete={handleClearEmptyFilterChip} />
      )}
    </InputAdornment>
  ) : null

  const commonTextFieldProps: TextFieldProps<any> = {
    fullWidth: true,
    helperText: showChangeModeButton ? (
      <label>
        {localization.filterMode.replace(
          '{filterType}',
          localization[
            `filter${
              currentFilterOption!.charAt(0)?.toUpperCase() +
              currentFilterOption!.slice(1)
            }` as keyof typeof localization
          ],
        )}
      </label>
    ) : null,
    inputRef: (inputRef) => {
      filterInputRefs.current![`${column.id}-${rangeFilterIndex ?? 0}`] =
        inputRef
      if (textFieldProps.inputRef) {
        textFieldProps.inputRef = inputRef
      }
    },
    margin: 'none',
    placeholder:
      filterChipLabel || isSelectFilter || isMultiSelectFilter
        ? undefined
        : filterPlaceholder,
    variant: 'standard',
    ...textFieldProps,
    slotProps: {
      ...textFieldProps.slotProps,
      formHelperText: {
        sx: {
          fontSize: '0.75rem',
          lineHeight: '0.8rem',
          whiteSpace: 'nowrap',
        },
        ...textFieldProps.slotProps?.formHelperText,
      },
      input: endAdornment // hack because mui looks for presence of endAdornment key instead of undefined
        ? { endAdornment, startAdornment, ...textFieldProps.slotProps?.input }
        : { startAdornment, ...textFieldProps.slotProps?.input },
      htmlInput: {
        'aria-label': filterPlaceholder,
        autoComplete: 'off',
        disabled: !!filterChipLabel,
        sx: {
          textOverflow: 'ellipsis',
          width: filterChipLabel ? 0 : undefined,
        },
        title: filterPlaceholder,
        ...textFieldProps.slotProps?.htmlInput,
      },
    },
    onKeyDown: (e) => {
      e.stopPropagation()
      textFieldProps.onKeyDown?.(e)
    },
    sx: (theme) => ({
      minWidth: isDateFilter
        ? '160px'
        : enableColumnFilterModes && rangeFilterIndex === 0
          ? '110px'
          : isRangeFilter
            ? '100px'
            : !filterChipLabel
              ? '120px'
              : 'auto',
      mx: '-2px',
      p: 0,
      width: 'calc(100% + 4px)',
      ...(parseFromValuesOrFunc(textFieldProps?.sx, theme) as any),
    }),
  }

  const commonDatePickerProps = {
    onChange: (newDate: any) => {
      handleChange(newDate)
    },
    value: filterValue || null,
  }

  return (
    <>
      {filterVariant?.startsWith('time') ? (
        <TimePicker
          {...commonDatePickerProps}
          {...timePickerProps}
          slotProps={{
            ...timePickerProps?.slotProps,
            field: {
              clearable: true,
              onClear: () => handleClear(),
              ...timePickerProps?.slotProps?.field,
            },
            textField: {
              ...commonTextFieldProps,
              ...timePickerProps?.slotProps?.textField,
            },
          }}
        />
      ) : filterVariant?.startsWith('datetime') ? (
        <DateTimePicker
          {...commonDatePickerProps}
          {...dateTimePickerProps}
          slotProps={{
            ...dateTimePickerProps?.slotProps,
            field: {
              clearable: true,
              onClear: () => handleClear(),
              ...dateTimePickerProps?.slotProps?.field,
            },
            textField: {
              ...commonTextFieldProps,
              ...dateTimePickerProps?.slotProps?.textField,
            },
          }}
        />
      ) : filterVariant?.startsWith('date') ? (
        <DatePicker
          {...commonDatePickerProps}
          {...datePickerProps}
          slotProps={{
            ...datePickerProps?.slotProps,
            field: {
              clearable: true,
              onClear: () => handleClear(),
              ...datePickerProps?.slotProps?.field,
            },
            textField: {
              ...commonTextFieldProps,
              ...datePickerProps?.slotProps?.textField,
            },
          }}
        />
      ) : isAutocompleteFilter ? (
        <Autocomplete
          freeSolo
          getOptionLabel={(option: DropdownOption) =>
            getValueAndLabel(option).label
          }
          onChange={(_e, newValue) =>
            handleAutocompleteChange(newValue as DropdownOption | null)
          }
          options={
            dropdownOptions?.map((option) => getValueAndLabel(option)) ?? []
          }
          inputValue={filterValue as string}
          onInputChange={handleAutocompleteInputChange}
          {...autocompleteProps}
          renderInput={(builtinTextFieldProps: TextFieldProps) => (
            <TextField
              {...commonTextFieldProps}
              {...builtinTextFieldProps}
              slotProps={{
                ...builtinTextFieldProps.slotProps,
                ...commonTextFieldProps.slotProps,
                input: {
                  ...(builtinTextFieldProps.slotProps as any)?.input,
                  startAdornment: (commonTextFieldProps?.slotProps as any)
                    ?.input?.startAdornment,
                },
                htmlInput: {
                  ...(builtinTextFieldProps.slotProps as any)?.htmlInput,
                  ...(commonTextFieldProps?.slotProps as any)?.htmlInput,
                },
              }}
              onClick={(e: MouseEvent<HTMLInputElement>) => e.stopPropagation()}
            />
          )}
          value={autocompleteValue}
        />
      ) : (
        <TextField
          select={isSelectFilter || isMultiSelectFilter}
          {...commonTextFieldProps}
          slotProps={{
            ...commonTextFieldProps.slotProps,
            inputLabel: {
              shrink: isSelectFilter || isMultiSelectFilter,
              ...(commonTextFieldProps.slotProps?.inputLabel as any),
            },
            select: {
              MenuProps: { disableScrollLock: true },
              displayEmpty: true,
              multiple: isMultiSelectFilter,
              renderValue: isMultiSelectFilter
                ? (selected: any) =>
                    !Array.isArray(selected) || selected?.length === 0 ? (
                      <Box sx={{ opacity: 0.5 }}>{filterPlaceholder}</Box>
                    ) : (
                      <Box
                        sx={{ display: 'flex', flexWrap: 'wrap', gap: '2px' }}
                      >
                        {selected.map((value: string) => {
                          const selectedValue = dropdownOptions?.find(
                            (option) =>
                              getValueAndLabel(option).value === value,
                          )
                          return (
                            <Chip
                              key={value}
                              label={getValueAndLabel(selectedValue).label}
                            />
                          )
                        })}
                      </Box>
                    )
                : undefined,
              ...commonTextFieldProps.slotProps?.select,
            },
          }}
          onChange={handleTextFieldChange}
          onClick={(e: MouseEvent<HTMLInputElement>) => e.stopPropagation()}
          value={
            isMultiSelectFilter
              ? Array.isArray(filterValue)
                ? filterValue
                : []
              : filterValue
          }
        >
          {(isSelectFilter || isMultiSelectFilter) && [
            <MenuItem disabled divider hidden key="p" value="">
              <Box sx={{ opacity: 0.5 }}>{filterPlaceholder}</Box>
            </MenuItem>,
            ...[
              textFieldProps.children ??
                dropdownOptions?.map((option, index) => {
                  const { label, value } = getValueAndLabel(option)
                  return (
                    <MenuItem
                      key={`${index}-${value}`}
                      sx={{
                        alignItems: 'center',
                        display: 'flex',
                        gap: '0.5rem',
                        m: 0,
                      }}
                      value={value}
                    >
                      {isMultiSelectFilter && (
                        <Checkbox
                          checked={(
                            (column.getFilterValue() ?? []) as Array<string>
                          ).includes(value)}
                          sx={{ mr: '0.5rem' }}
                        />
                      )}
                      {label}{' '}
                      {!columnDef.filterSelectOptions &&
                        `(${facetedUniqueValues.get(value)})`}
                    </MenuItem>
                  )
                }),
            ],
          ]}
        </TextField>
      )}
      <MRT_FilterOptionMenu
        anchorEl={anchorEl}
        header={header}
        setAnchorEl={setAnchorEl}
        setFilterValue={setFilterValue}
      />
    </>
  )
}

import { useEffect, useRef, useState } from 'react'
import Collapse from '@mui/material/Collapse'
import IconButton from '@mui/material/IconButton'
import InputAdornment from '@mui/material/InputAdornment'
import TextField from '@mui/material/TextField'
import Tooltip from '@mui/material/Tooltip'
import { useDebouncedCallback } from '@tanstack/react-pacer/debouncer'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_FilterOptionMenu } from '../menus/MRT_FilterOptionMenu'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { MRT_RowData } from '../../types'
import type { TextFieldProps } from '@mui/material/TextField'
import type { ChangeEvent, MouseEvent } from 'react'

export interface MRT_GlobalFilterTextFieldProps extends TextFieldProps<'standard'> {}

export const MRT_GlobalFilterTextField = <TData extends MRT_RowData>({
  ...rest
}: MRT_GlobalFilterTextFieldProps) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: {
      enableGlobalFilterModes,
      icons: { CloseIcon, SearchIcon },
      localization,
      manualFiltering,
      muiSearchTextFieldProps,
    },
    refs: { searchInputRef },
    setGlobalFilter,
  } = table
  const { globalFilter, showGlobalFilter } = state

  const textFieldProps = {
    ...parseFromValuesOrFunc(muiSearchTextFieldProps, {
      table,
    }),
    ...rest,
  }

  const isMounted = useRef(false)
  const [anchorEl, setAnchorEl] = useState<HTMLElement | null>(null)
  const [searchValue, setSearchValue] = useState(globalFilter ?? '')

  const handleChangeDebounced = useDebouncedCallback(
    (value: string) => {
      setGlobalFilter(value ?? undefined)
    },
    { wait: manualFiltering ? 500 : 250 },
  )

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    setSearchValue(event.target.value)
    handleChangeDebounced(event.target.value)
  }

  const handleGlobalFilterMenuOpen = (event: MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget)
  }

  const handleClear = () => {
    setSearchValue('')
    setGlobalFilter(undefined)
  }

  useEffect(() => {
    if (isMounted.current) {
      if (globalFilter === undefined) {
        handleClear()
      } else {
        setSearchValue(globalFilter)
      }
    }
    isMounted.current = true
  }, [globalFilter])

  return (
    <Collapse
      in={showGlobalFilter}
      mountOnEnter
      orientation="horizontal"
      unmountOnExit
    >
      <TextField
        onChange={handleChange}
        placeholder={localization.search}
        size="small"
        value={searchValue ?? ''}
        variant="outlined"
        {...textFieldProps}
        slotProps={{
          ...(textFieldProps.slotProps as any),
          input: {
            endAdornment: (
              <InputAdornment position="end">
                <Tooltip title={localization.clearSearch ?? ''}>
                  <span>
                    <IconButton
                      aria-label={localization.clearSearch}
                      disabled={!searchValue?.length}
                      onClick={handleClear}
                      size="small"
                    >
                      <CloseIcon />
                    </IconButton>
                  </span>
                </Tooltip>
              </InputAdornment>
            ),
            startAdornment: enableGlobalFilterModes ? (
              <InputAdornment position="start">
                <Tooltip title={localization.changeSearchMode}>
                  <IconButton
                    aria-label={localization.changeSearchMode}
                    onClick={handleGlobalFilterMenuOpen}
                    size="small"
                    sx={{ height: '1.75rem', width: '1.75rem' }}
                  >
                    <SearchIcon />
                  </IconButton>
                </Tooltip>
              </InputAdornment>
            ) : (
              <SearchIcon style={{ marginRight: '4px' }} />
            ),
            ...(textFieldProps.slotProps as any)?.input,
            sx: (theme: any) => ({
              mb: 0,
              ...parseFromValuesOrFunc(
                (textFieldProps.slotProps as any)?.input?.sx,
                theme,
              ),
            }),
          },
          htmlInput: {
            autoComplete: 'off',
            ...(textFieldProps.slotProps as any)?.htmlInput,
          },
        }}
        inputRef={(inputRef) => {
          searchInputRef.current = inputRef
          if (textFieldProps?.inputRef) {
            ;(textFieldProps as any).inputRef = inputRef
          }
        }}
      />
      <MRT_FilterOptionMenu
        anchorEl={anchorEl}
        onSelect={handleClear}
        setAnchorEl={setAnchorEl}
      />
    </Collapse>
  )
}

import Checkbox from '@mui/material/Checkbox'
import Radio from '@mui/material/Radio'
import Tooltip from '@mui/material/Tooltip'
import {
  getIsRowSelected,
  getMRT_RowSelectionHandler,
  getMRT_SelectAllHandler,
} from '../../utils/row.utils'
import { getCommonTooltipProps } from '../../utils/style.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { MRT_Row, MRT_RowData } from '../../types'
import type { Theme } from '@mui/material/styles'
import type { RadioProps } from '@mui/material/Radio'
import type { CheckboxProps } from '@mui/material/Checkbox'
import type { MouseEvent } from 'react'

export interface MRT_SelectCheckboxProps<
  TData extends MRT_RowData,
> extends CheckboxProps {
  row?: MRT_Row<TData>
  staticRowIndex?: number
}

export const MRT_SelectCheckbox = <TData extends MRT_RowData>({
  row,
  staticRowIndex,
  ...rest
}: MRT_SelectCheckboxProps<TData>) => {
  const table = useMRTContext<TData>()
  const {
    state,
    options: {
      enableMultiRowSelection,
      localization,
      muiSelectAllCheckboxProps,
      muiSelectCheckboxProps,
      selectAllMode,
    },
  } = table
  const { density, isLoading } = state

  const selectAll = !row

  const allRowsSelected = selectAll
    ? selectAllMode === 'page'
      ? table.getIsAllPageRowsSelected()
      : table.getIsAllRowsSelected()
    : undefined

  const isChecked = selectAll
    ? allRowsSelected
    : getIsRowSelected({ row, table })

  const checkboxProps = {
    ...(selectAll
      ? parseFromValuesOrFunc(muiSelectAllCheckboxProps, { table })
      : parseFromValuesOrFunc(muiSelectCheckboxProps, {
          row,
          staticRowIndex,
          table,
        })),
    ...rest,
  }

  const onSelectionChange = row
    ? getMRT_RowSelectionHandler({
        row,
        staticRowIndex,
        table,
      })
    : undefined

  const onSelectAllChange = getMRT_SelectAllHandler({ table })

  const commonProps = {
    'aria-label': selectAll
      ? localization.toggleSelectAll
      : localization.toggleSelectRow,
    checked: isChecked,
    disabled:
      isLoading || (row && !row.getCanSelect()) || row?.id === 'mrt-row-create',
    slotProps: {
      input: {
        'aria-label': selectAll
          ? localization.toggleSelectAll
          : localization.toggleSelectRow,
      },
    },
    onChange: (event) => {
      event.stopPropagation()
      selectAll ? onSelectAllChange(event) : onSelectionChange!(event)
    },
    size: density === 'compact' ? 'small' : 'medium',
    ...checkboxProps,
    onClick: (e: MouseEvent<HTMLButtonElement>) => {
      e.stopPropagation()
      checkboxProps?.onClick?.(e)
    },
    sx: (theme: Theme) => ({
      height: density === 'compact' ? '1.75rem' : '2.5rem',
      m: density !== 'compact' ? '-0.4rem' : undefined,
      width: density === 'compact' ? '1.75rem' : '2.5rem',
      zIndex: 0,
      ...parseFromValuesOrFunc(checkboxProps?.sx, theme),
    }),
    title: undefined,
  } as CheckboxProps | RadioProps

  return (
    <Tooltip
      {...getCommonTooltipProps()}
      title={
        checkboxProps?.title ??
        (selectAll
          ? localization.toggleSelectAll
          : localization.toggleSelectRow)
      }
    >
      {enableMultiRowSelection === false ? (
        <Radio {...(commonProps as any)} />
      ) : (
        <Checkbox
          indeterminate={
            !isChecked && selectAll
              ? table.getIsSomeRowsSelected()
              : row?.getIsSomeSelected() && row.getCanSelectSubRows()
          }
          {...commonProps}
        />
      )}
    </Tooltip>
  )
}

