import Paper from '@mui/material/Paper'
import { useTheme } from '@mui/material/styles'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { MRT_BottomToolbar } from '../toolbar/MRT_BottomToolbar'
import { MRT_TopToolbar } from '../toolbar/MRT_TopToolbar'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_TableContainer } from './MRT_TableContainer'
import type { PaperProps } from '@mui/material/Paper'

export interface MRT_TablePaperProps extends PaperProps {}

export const MRT_TablePaper = ({ ...rest }: MRT_TablePaperProps) => {
  const table = useMRTContext()
  const {
    state,
    options: {
      enableBottomToolbar,
      enableTopToolbar,
      mrtTheme: { baseBackgroundColor },
      muiTablePaperProps,
      renderBottomToolbar,
      renderTopToolbar,
    },
    refs: { tablePaperRef },
  } = table
  const { isFullScreen } = state

  const paperProps = {
    ...parseFromValuesOrFunc(muiTablePaperProps, { table }),
    ...rest,
  }

  const theme = useTheme()

  return (
    <Paper
      elevation={2}
      onKeyDown={(e) => e.key === 'Escape' && table.setIsFullScreen(false)}
      {...paperProps}
      ref={(ref: HTMLDivElement) => {
        tablePaperRef.current = ref
        if (paperProps?.ref) {
          // @ts-expect-error
          paperProps.ref.current = ref
        }
      }}
      style={{
        ...(isFullScreen
          ? {
              bottom: 0,
              height: '100dvh',
              left: 0,
              margin: 0,
              maxHeight: '100dvh',
              maxWidth: '100dvw',
              padding: 0,
              position: 'fixed',
              right: 0,
              top: 0,
              width: '100dvw',
              zIndex: theme.zIndex.modal,
            }
          : {}),
        ...paperProps?.style,
      }}
      sx={(theme) => ({
        backgroundColor: baseBackgroundColor,
        backgroundImage: 'unset',
        overflow: 'hidden',
        transition: 'all 100ms ease-in-out',
        ...(parseFromValuesOrFunc(paperProps?.sx, theme) as any),
      })}
    >
      {enableTopToolbar &&
        (parseFromValuesOrFunc(renderTopToolbar, { table }) ?? (
          <MRT_TopToolbar />
        ))}
      <MRT_TableContainer />
      {enableBottomToolbar &&
        (parseFromValuesOrFunc(renderBottomToolbar, { table }) ?? (
          <MRT_BottomToolbar />
        ))}
    </Paper>
  )
}

import Box from '@mui/material/Box'
import { alpha } from '@mui/material/styles'
import useMediaQuery from '@mui/material/useMediaQuery'
import { getCommonToolbarStyles } from '../../utils/style.utils'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import { MRT_LinearProgressBar } from './MRT_LinearProgressBar'
import { MRT_TablePagination } from './MRT_TablePagination'
import { MRT_ToolbarAlertBanner } from './MRT_ToolbarAlertBanner'
import { MRT_ToolbarDropZone } from './MRT_ToolbarDropZone'
import type { BoxProps } from '@mui/material/Box'

export interface MRT_BottomToolbarProps extends BoxProps {}

export const MRT_BottomToolbar = ({ ...rest }: MRT_BottomToolbarProps) => {
  const table = useMRTContext()
  const {
    state,
    options: {
      enablePagination,
      muiBottomToolbarProps,
      positionPagination,
      positionToolbarAlertBanner,
      positionToolbarDropZone,
      renderBottomToolbarCustomActions,
    },
    refs: { bottomToolbarRef },
  } = table
  const { isFullScreen } = state

  const isMobile = useMediaQuery('(max-width:720px)')

  const toolbarProps = {
    ...parseFromValuesOrFunc(muiBottomToolbarProps, { table }),
    ...rest,
  }

  const stackAlertBanner = isMobile || !!renderBottomToolbarCustomActions

  return (
    <Box
      {...toolbarProps}
      ref={(node: HTMLDivElement) => {
        if (node) {
          bottomToolbarRef.current = node
          if (toolbarProps?.ref) {
            // @ts-expect-error
            toolbarProps.ref.current = node
          }
        }
      }}
      sx={(theme) => ({
        ...getCommonToolbarStyles({ table, theme }),
        bottom: isFullScreen ? '0' : undefined,
        boxShadow: `0 1px 2px -1px ${alpha(
          theme.palette.grey[700],
          0.5,
        )} inset`,
        left: 0,
        position: isFullScreen ? 'fixed' : 'relative',
        right: 0,
        ...(parseFromValuesOrFunc(toolbarProps?.sx, theme) as any),
      })}
    >
      <MRT_LinearProgressBar isTopToolbar={false} />
      {positionToolbarAlertBanner === 'bottom' && (
        <MRT_ToolbarAlertBanner stackAlertBanner={stackAlertBanner} />
      )}
      {['both', 'bottom'].includes(positionToolbarDropZone ?? '') && (
        <MRT_ToolbarDropZone />
      )}
      <Box
        sx={{
          alignItems: 'center',
          boxSizing: 'border-box',
          display: 'flex',
          justifyContent: 'space-between',
          p: '0.5rem',
          width: '100%',
        }}
      >
        {renderBottomToolbarCustomActions ? (
          renderBottomToolbarCustomActions({ table })
        ) : (
          <span />
        )}
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'flex-end',
            position: stackAlertBanner ? 'relative' : 'absolute',
            right: 0,
            top: 0,
          }}
        >
          {enablePagination &&
            ['both', 'bottom'].includes(positionPagination ?? '') && (
              <MRT_TablePagination position="bottom" />
            )}
        </Box>
      </Box>
    </Box>
  )
}

import Collapse from '@mui/material/Collapse'
import LinearProgress from '@mui/material/LinearProgress'
import { parseFromValuesOrFunc } from '../../utils/utils'
import { useMRTContext } from '../../hooks/mrtTableHook'
import type { LinearProgressProps } from '@mui/material/LinearProgress'

export interface MRT_LinearProgressBarProps extends LinearProgressProps {
  isTopToolbar: boolean
}

export const MRT_LinearProgressBar = ({
  isTopToolbar,
  ...rest
}: MRT_LinearProgressBarProps) => {
  const table = useMRTContext()
  const {
    state,
    options: { muiLinearProgressProps },
  } = table
  const { isSaving, showProgressBars } = state

  const linearProgressProps = {
    ...parseFromValuesOrFunc(muiLinearProgressProps, {
      isTopToolbar,
      table,
    }),
    ...rest,
  }

  return (
    <Collapse
      in={showProgressBars !== false && (showProgressBars || isSaving)}
      mountOnEnter
      sx={{
        bottom: isTopToolbar ? 0 : undefined,
