import { getCanRankRows } from '../utils/row.utils'
import type { MRT_RowData, MRT_SortingState, MRT_TableInstance } from '../types'

export const useMRT_Effects = <TData extends MRT_RowData>(
  table: MRT_TableInstance<TData>,
) => {
  const {
    getIsSomeRowsPinned,
    getPrePaginatedRowModel,
    state,
    options: { enablePagination, enableRowPinning, rowCount },
  } = table
  const {
    columnOrder,
    density,
    globalFilter,
    isFullScreen,
    isLoading,
    pagination,
    showSkeletons,
    sorting,
  } = state

  const totalColumnCount = table.options.columns.length
  const totalRowCount = rowCount ?? getPrePaginatedRowModel().rows.length

  const rerender = useReducer(() => ({}), {})[1]
  const initialBodyHeight = useRef<string>(null)
  const previousTop = useRef<number>(null)

  useEffect(() => {
    if (typeof window !== 'undefined') {
      initialBodyHeight.current = document.body.style.height
    }
  }, [])

  // hide scrollbars when table is in full screen mode, preserve body scroll position after full screen exit
  useEffect(() => {
    if (typeof window !== 'undefined') {
      if (isFullScreen) {
        previousTop.current = document.body.getBoundingClientRect().top // save scroll position
        document.body.style.height = '100dvh' // hide page scrollbars when table is in full screen mode
      } else {
        document.body.style.height = initialBodyHeight.current as string
        if (!previousTop.current) return
        // restore scroll position
        window.scrollTo({
          behavior: 'instant',
          top: -1 * previousTop.current,
        })
      }
    }
  }, [isFullScreen])

  // recalculate column order when columns change or features are toggled on/off
  useEffect(() => {
    if (totalColumnCount !== columnOrder.length) {
      table.setColumnOrder(
        getDefaultColumnOrderIds({
          ...table.options,
          state,
        }),
      )
    }
  }, [totalColumnCount])

  // if page index is out of bounds, set it to the last page
  useEffect(() => {
    if (!enablePagination || isLoading || showSkeletons) return
    const { pageIndex, pageSize } = pagination
    const totalPages: number =
      totalRowCount > 0 ? Math.ceil(totalRowCount / pageSize) : 1
    const isOutOfBounds: boolean = pageIndex < 0 || pageIndex >= totalPages

    if (isOutOfBounds) {
      table.setPageIndex(totalPages - 1)
    }
  }, [totalRowCount, enablePagination, isLoading, showSkeletons])

  // turn off sort when global filter is looking for ranked results
  const appliedSort = useRef<MRT_SortingState>(sorting)
  useEffect(() => {
    if (sorting.length) {
      appliedSort.current = sorting
    }
  }, [sorting])

  useEffect(() => {
    if (!getCanRankRows(table)) return
    if (globalFilter) {
      table.setSorting([])
    } else {
      table.setSorting(() => appliedSort.current || [])
    }
  }, [globalFilter])

  // fix pinned row top style when density changes
  useEffect(() => {
    if (enableRowPinning && getIsSomeRowsPinned()) {
      setTimeout(() => {
        rerender()
      }, 150)
    }
  }, [density])
}

import { useCallback, useMemo } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { parseFromValuesOrFunc } from '../utils/utils'
import { extraIndexRangeExtractor } from '../utils/virtualization.utils'
import type { Range } from '@tanstack/react-virtual'
import type {
  MRT_Row,
  MRT_RowData,
  MRT_RowVirtualizer,
  MRT_TableInstance,
} from '../types'

export const useMRT_RowVirtualizer = <
  TData extends MRT_RowData,
  TScrollElement extends Element | Window = HTMLDivElement,
  TItemElement extends Element = HTMLTableRowElement,
>(
  table: MRT_TableInstance<TData>,
  rows?: Array<MRT_Row<TData>>,
): MRT_RowVirtualizer<TScrollElement, TItemElement> | undefined => {
  const {
    getRowModel,
    state,
    options: {
      enableRowVirtualization,
      renderDetailPanel,
      rowVirtualizerInstanceRef,
      rowVirtualizerOptions,
    },
    refs: { tableContainerRef },
  } = table
  const { density, draggingRow, expanded } = state

  if (!enableRowVirtualization) return undefined

  const rowVirtualizerProps = parseFromValuesOrFunc(rowVirtualizerOptions, {
    table,
  })

  const realRows = rows ?? getRowModel().rows
  /**
   * when filtering, should find the correct index in filtered rows
   */
  const draggingRowIndex = useMemo(
    () =>
      draggingRow?.id
        ? realRows.findIndex((r) => r.id === draggingRow?.id)
        : undefined,
    [realRows, draggingRow?.id],
  )

  const rowCount = realRows.length

  const normalRowHeight =
    density === 'compact' ? 37 : density === 'comfortable' ? 58 : 73

  const rowVirtualizer = useVirtualizer({
    count: renderDetailPanel ? rowCount * 2 : rowCount,
    estimateSize: (index) =>
      renderDetailPanel && index % 2 === 1
        ? expanded === true
          ? 100
          : 0
        : normalRowHeight,
    getScrollElement: () => tableContainerRef.current,
    measureElement:
      typeof window !== 'undefined' &&
      navigator.userAgent.indexOf('Firefox') === -1
        ? (element) => element?.getBoundingClientRect().height
        : undefined,
    overscan: 4,
    rangeExtractor: useCallback(
      (range: Range) => {
        return extraIndexRangeExtractor(range, draggingRowIndex)
      },
      [draggingRowIndex],
    ),
    ...rowVirtualizerProps,
  }) as unknown as MRT_RowVirtualizer<TScrollElement, TItemElement>

  rowVirtualizer.virtualRows = rowVirtualizer.getVirtualItems()

  if (rowVirtualizerInstanceRef) {
    // @ts-expect-error
    rowVirtualizerInstanceRef.current = rowVirtualizer
  }

  return rowVirtualizer
}

import { useMemo, useRef } from 'react'
import {
  getAllLeafColumnDefs,
  getColumnId,
  getDefaultColumnFilterFn,
  prepareColumns,
} from '../utils/column.utils'
import {
  getDefaultColumnOrderIds,
  showRowActionsColumn,
  showRowDragColumn,
  showRowExpandColumn,
  showRowNumbersColumn,
  showRowPinningColumn,
  showRowSelectionColumn,
  showRowSpacerColumn,
} from '../utils/displayColumn.utils'
import { useAppTable } from './mrtTableHook'
import { getMRT_RowActionsColumnDef } from './display-columns/getMRT_RowActionsColumnDef'
import { getMRT_RowDragColumnDef } from './display-columns/getMRT_RowDragColumnDef'
import { getMRT_RowExpandColumnDef } from './display-columns/getMRT_RowExpandColumnDef'
import { getMRT_RowNumbersColumnDef } from './display-columns/getMRT_RowNumbersColumnDef'
import { getMRT_RowPinningColumnDef } from './display-columns/getMRT_RowPinningColumnDef'
import { getMRT_RowSelectColumnDef } from './display-columns/getMRT_RowSelectColumnDef'
import { getMRT_RowSpacerColumnDef } from './display-columns/getMRT_RowSpacerColumnDef'
import { useMRT_Effects } from './useMRT_Effects'
import type {
  MRT_ColumnDef,
  MRT_ColumnFilterFnsState,
  MRT_DefinedTableOptions,
  MRT_RowData,
  MRT_StatefulTableOptions,
  MRT_TableInstance,
  MRT_TableState,
} from '../types'

/**
 * Wraps the TanStack v9 `useTable` hook, adding the MRT display-column
 * injection, skeleton-row fabrication, and initial-state massaging that can't
 * live inside a feature.
 *
 * All MRT-only state, setters, and refs now come from the custom features
 * bundled in `mrtFeatures` (see `../features`). `useTable` constructs a base
 * atom for every feature-contributed state key, so `table.state.density`,
 * `table.setDensity`, `table.refs`, etc. are all provided natively — the
 * hand-rolled atoms, setter aliases, and `table.state` patching that MRT
 * previously maintained here are gone.
 */
export const useMRT_TableInstance = <TData extends MRT_RowData>(
  definedTableOptions: MRT_DefinedTableOptions<TData>,
): MRT_TableInstance<TData> => {
  const tableRef = useRef<MRT_TableInstance<TData> | null>(null)
  const columnDefsRef = useRef<Array<MRT_ColumnDef<TData>>>([])
  const columnPreparationDepsRef = useRef<Array<unknown> | undefined>(undefined)

  // ---------------------------------------------------------------------------
  // Initial state — the column-order default and the per-column filter-fn map
  // both need the column defs, which a feature's `getInitialState` can't see, so
  // they're computed here and flow in via `initialState` (overriding the empty
  // defaults the filter-modes feature seeds).
  // ---------------------------------------------------------------------------
  const initialState = useMemo<Partial<MRT_TableState<TData>>>(() => {
    const initState = definedTableOptions.initialState ?? {}

    const columnFilterFns: MRT_ColumnFilterFnsState = {
      ...initState.columnFilterFns,
    }
    for (const col of getAllLeafColumnDefs(
      definedTableOptions.columns as Array<MRT_ColumnDef<TData>>,
    )) {
      const id = getColumnId(col)
      if (columnFilterFns[id] == null) {
        columnFilterFns[id] =
          col.filterFn instanceof Function
            ? (col.filterFn.name ?? 'custom')
            : (col.filterFn ?? getDefaultColumnFilterFn(col))
      }
    }
    initState.columnFilterFns = columnFilterFns

    initState.columnOrder =
      initState.columnOrder ??
      getDefaultColumnOrderIds({
        ...definedTableOptions,
        state: {
          ...definedTableOptions.initialState,
          ...definedTableOptions.state,
        },
      } as MRT_StatefulTableOptions<TData>)
    // Core's `globalFilterFn` option also admits a raw `FilterFn`; MRT's state
    // slice only stores the string fn name, so narrow it here.
    initState.globalFilterFn =
      typeof definedTableOptions.globalFilterFn === 'string'
        ? definedTableOptions.globalFilterFn
        : 'fuzzy'
    return initState
  }, [])

  // `initialState` is readonly on the resolved core options type; assign through
  // a cast (the hook owns this options object).
  ;(
    definedTableOptions as { initialState?: Partial<MRT_TableState<TData>> }
  ).initialState = initialState

  // ---------------------------------------------------------------------------
  // State used only for the option-time transforms below (display-column
  // injection, the resize/drag column freeze, skeleton data). It's sourced from
  // the previous render's `table.state` (the full-state selector re-renders this
  // hook on every change) and falls back to initial state on the first render.
  // It is NOT passed to `useTable` as controlled `state` — only the client's own
  // `state` option controls slices; everything else is owned by core/feature
  // base atoms.
  // ---------------------------------------------------------------------------
  const transformStateDefaults = {
    columnOrder: [],
    columnResizing: {},
    creatingRow: null,
    draggingColumn: null,
    draggingRow: null,
    grouping: [],
    isLoading: false,
    pagination: { pageIndex: 0, pageSize: 10 },
    showSkeletons: false,
  }
  const stateForTransforms = {
    ...transformStateDefaults,
    ...initialState,
    ...definedTableOptions.state,
    ...(tableRef.current?.state ?? {}),
  } as MRT_TableState<TData>

  const optionsForTransforms = {
    ...definedTableOptions,
    state: stateForTransforms,
  } as MRT_StatefulTableOptions<TData>

  // Column preparation mutates/augments definitions and must rerun when an
  // input that affects those definitions changes. Keep the resulting array
  // stable across unrelated state updates such as pagination.
  const columnPreparationDeps: Array<unknown> = [
    optionsForTransforms.columns,
    optionsForTransforms.defaultColumn,
    optionsForTransforms.defaultDisplayColumn,
    optionsForTransforms.displayColumnDefOptions,
    (optionsForTransforms as any).filterFns,
    (optionsForTransforms as any).sortFns,
    optionsForTransforms.localization,
    stateForTransforms.columnFilterFns,
    stateForTransforms.creatingRow,
    stateForTransforms.grouping,
    optionsForTransforms.createDisplayMode,
    optionsForTransforms.editDisplayMode,
    optionsForTransforms.enableEditing,
    optionsForTransforms.enableExpandAll,
    optionsForTransforms.enableExpanding,
    optionsForTransforms.enableGrouping,
    optionsForTransforms.enableMultiRowSelection,
    optionsForTransforms.enableRowActions,
    optionsForTransforms.enableRowDragging,
    optionsForTransforms.enableRowNumbers,
    optionsForTransforms.enableRowOrdering,
    optionsForTransforms.enableRowPinning,
    optionsForTransforms.enableRowSelection,
    optionsForTransforms.enableSelectAll,
    optionsForTransforms.groupedColumnMode,
    optionsForTransforms.layoutMode,
    optionsForTransforms.positionExpandColumn,
    optionsForTransforms.renderDetailPanel,
    optionsForTransforms.rowNumberDisplayMode,
    optionsForTransforms.rowPinningDisplayMode,
  ]
  const previousColumnPreparationDeps = columnPreparationDepsRef.current
  const columnPreparationChanged =
    !previousColumnPreparationDeps ||
    columnPreparationDeps.length !== previousColumnPreparationDeps.length ||
    columnPreparationDeps.some(
      (dependency, index) =>
        !Object.is(dependency, previousColumnPreparationDeps[index]),
    )
  const freezePreparedColumns =
    !!columnDefsRef.current.length &&
    (stateForTransforms.columnResizing.isResizingColumn ||
      !!stateForTransforms.draggingColumn ||
      !!stateForTransforms.draggingRow)

  if (columnPreparationChanged && !freezePreparedColumns) {
    columnDefsRef.current = prepareColumns({
      columnDefs: [
        ...([
          showRowPinningColumn(optionsForTransforms) &&
            getMRT_RowPinningColumnDef(optionsForTransforms),
          showRowDragColumn(optionsForTransforms) &&
            getMRT_RowDragColumnDef(optionsForTransforms),
          showRowActionsColumn(optionsForTransforms) &&
            getMRT_RowActionsColumnDef(optionsForTransforms),
          showRowExpandColumn(optionsForTransforms) &&
            getMRT_RowExpandColumnDef(optionsForTransforms),
          showRowSelectionColumn(optionsForTransforms) &&
            getMRT_RowSelectColumnDef(optionsForTransforms),
          showRowNumbersColumn(optionsForTransforms) &&
            getMRT_RowNumbersColumnDef(optionsForTransforms),
        ].filter(Boolean) as Array<MRT_ColumnDef<TData>>),
        ...optionsForTransforms.columns,
        ...([
          showRowSpacerColumn(optionsForTransforms) &&
            getMRT_RowSpacerColumnDef(optionsForTransforms),
        ].filter(Boolean) as Array<MRT_ColumnDef<TData>>),
      ],
      tableOptions: optionsForTransforms,
    })
    columnPreparationDepsRef.current = columnPreparationDeps
  }
  const preparedColumns = columnDefsRef.current

  // If loading with empty data, generate blank rows to show skeleton loaders.
  const data = useMemo(
    () =>
      (stateForTransforms.isLoading || stateForTransforms.showSkeletons) &&
      !definedTableOptions.data.length
        ? [
            ...Array(Math.min(stateForTransforms.pagination.pageSize, 20)).fill(
              null,
            ),
          ].map(() =>
            Object.assign(
              {},
              ...getAllLeafColumnDefs(preparedColumns).map((col) => ({
                [getColumnId(col)]: null,
              })),
            ),
          )
        : definedTableOptions.data,
    [
      definedTableOptions.data,
      stateForTransforms.isLoading,
      stateForTransforms.showSkeletons,
    ],
  )

  // `useAppTable` (from `createTableHook`) owns the `mrtFeatures` bundle and
  // attaches the App* context wrappers. MRT's option-time transforms above are
  // applied before handing the options over, and the previous render's
  // `table.state` (via the full-state selector) feeds the next render's
  // transforms through `tableRef`.
  const table = useAppTable(
    {
      ...(definedTableOptions as any),
      columns: preparedColumns,
      data,
      initialState,
      globalFilterFn: (stateForTransforms.globalFilterFn ?? 'fuzzy') as any,
    },
    (state) => state, // full-state selector; MRT reads table.state.X synchronously
  ) as unknown as MRT_TableInstance<TData>

  tableRef.current = table

  useMRT_Effects(table)

  return table
}

import {
  getMRT_RowSelectionHandler,
  getMRT_SelectAllHandler,
} from './row.utils'
import { parseFromValuesOrFunc } from './utils'
import type {
  MRT_Cell,
  MRT_Header,
  MRT_RowData,
  MRT_TableInstance,
} from '../types'

const isWinCtrlMacMeta = (event: React.KeyboardEvent<HTMLTableCellElement>) => {
  return (
    (event.ctrlKey && navigator.platform.toLowerCase().includes('win')) ||
    (event.metaKey && navigator.platform.toLowerCase().includes('mac'))
  )
}

export const isCellEditable = <TData extends MRT_RowData>({
  cell,
  table,
}: {
  cell: MRT_Cell<TData>
  table: MRT_TableInstance<TData>
}) => {
  const { enableEditing } = table.options
  const {
    column: { columnDef },
    row,
  } = cell
  return (
    !cell.getIsPlaceholder() &&
    parseFromValuesOrFunc(enableEditing, row) &&
    parseFromValuesOrFunc(columnDef.enableEditing, row) !== false
  )
}

export const openEditingCell = <TData extends MRT_RowData>({
  cell,
  table,
}: {
  cell: MRT_Cell<TData>
  table: MRT_TableInstance<TData>
}) => {
  const {
    options: { editDisplayMode },
    refs: { editInputRefs },
  } = table
  const { column } = cell

  if (isCellEditable({ cell, table }) && editDisplayMode === 'cell') {
    table.setEditingCell(cell)
    queueMicrotask(() => {
      const textField = editInputRefs.current?.[column.id]
      if (textField) {
        textField.focus()
        textField.select?.()
      }
    })
  }
}

export const cellKeyboardShortcuts = <TData extends MRT_RowData = MRT_RowData>({
  cell,
  cellElements,
  cellValue,
  containerElement,
  event,
  header,
  parentElement,
  table,
}: {
  cell?: MRT_Cell<TData>
  header?: MRT_Header<TData>
  cellElements?: Array<HTMLTableCellElement>
  cellValue?: string
  containerElement?: HTMLTableElement
  event: React.KeyboardEvent<HTMLTableCellElement>
  parentElement?: HTMLTableRowElement
  table: MRT_TableInstance<TData>
}) => {
  if (!table.options.enableKeyboardShortcuts) return
  if (event.isPropagationStopped()) return
  const currentCell = event.currentTarget

  if (cellValue && isWinCtrlMacMeta(event) && event.key === 'c') {
    navigator.clipboard.writeText(cellValue)
  } else if (['Enter', ' '].includes(event.key)) {
    if (cell?.column?.id === 'mrt-row-select') {
      event.preventDefault()
      getMRT_RowSelectionHandler({
        row: cell.row,
        table,
        // @ts-expect-error
        staticRowIndex: +event.target.getAttribute('data-index'),
      })(event as any)
    } else if (
      header?.column?.id === 'mrt-row-select' &&
      table.options.enableSelectAll
    ) {
      event.preventDefault()
      getMRT_SelectAllHandler({
        table,
      })(event as any)
    } else if (
      cell?.column?.id === 'mrt-row-expand' &&
      (cell.row.getCanExpand() ||
        table.options.renderDetailPanel?.({ row: cell.row, table }))
    ) {
      event.preventDefault()
      cell.row.toggleExpanded()
    } else if (
      header?.column?.id === 'mrt-row-expand' &&
      table.options.enableExpandAll
    ) {
      event.preventDefault()
      table.toggleAllRowsExpanded()
    } else if (cell?.column.id === 'mrt-row-pin') {
      event.preventDefault()
      cell.row.getIsPinned()
        ? cell.row.pin(false)
        : cell.row.pin(
            table.options.rowPinningDisplayMode?.includes('bottom')
              ? 'bottom'
              : 'top',
          )
    } else if (header && isWinCtrlMacMeta(event)) {
      const actionsButton = currentCell.querySelector(
        `button[aria-label="${table.options.localization.columnActions}"]`,
      )
      if (actionsButton) {
        ;(actionsButton as HTMLButtonElement).click()
      }
    } else if (header?.column?.getCanSort()) {
      event.preventDefault()
      header.column.toggleSorting()
    }
  } else if (
    [
      'ArrowRight',
      'ArrowLeft',
      'ArrowUp',
      'ArrowDown',
      'Home',
      'End',
      'PageUp',
      'PageDown',
    ].includes(event.key)
  ) {
    event.preventDefault()

    const currentRow = parentElement || currentCell.closest('tr')
    const tableElement = containerElement || currentCell.closest('table')
    const allCells =
      cellElements || Array.from(tableElement?.querySelectorAll('th, td') || [])
    const currentCellIndex = allCells.indexOf(currentCell)

    const currentIndex = parseInt(currentCell.getAttribute('data-index') || '0')
    let nextCell: HTMLElement | undefined = undefined

    // home/end first or last cell in row
    const findEdgeCell = (rowIndex: 'c' | 'f' | 'l', edge: 'f' | 'l') => {
      const row =
        rowIndex === 'c'
          ? currentRow
          : rowIndex === 'f'
            ? tableElement?.querySelector('tr')
            : tableElement?.lastElementChild?.lastElementChild
      const rowCells = Array.from(row?.children || [])
      const targetCell =
        edge === 'f' ? rowCells[0] : rowCells[rowCells.length - 1]
      return targetCell as HTMLElement
    }

    // page up/down first or last cell in column
    const findBottomTopCell = (columnIndex: number, edge: 'b' | 't') => {
      const row =
        edge === 't'
          ? tableElement?.querySelector('tr')
          : tableElement?.lastElementChild?.lastElementChild
      const rowCells = Array.from(row?.children || [])
      const targetCell = rowCells[columnIndex]
      return targetCell as HTMLElement
    }

    const findAdjacentCell = (
      columnIndex: number,
      searchDirection: 'f' | 'b',
    ) => {
      const searchArray =
        searchDirection === 'f'
          ? allCells.slice(currentCellIndex + 1)
          : allCells.slice(0, currentCellIndex).reverse()
      return searchArray.find((cell) =>
        cell.matches(`[data-index="${columnIndex}"]`),
      ) as HTMLElement | undefined
    }

    switch (event.key) {
      case 'ArrowRight':
        nextCell = findAdjacentCell(currentIndex + 1, 'f')
        break
      case 'ArrowLeft':
        nextCell = findAdjacentCell(currentIndex - 1, 'b')
        break
      case 'ArrowUp':
        nextCell = findAdjacentCell(currentIndex, 'b')
        break
      case 'ArrowDown':
        nextCell = findAdjacentCell(currentIndex, 'f')
        break
      case 'Home':
        nextCell = findEdgeCell(isWinCtrlMacMeta(event) ? 'f' : 'c', 'f')
        break
      case 'End':
        nextCell = findEdgeCell(isWinCtrlMacMeta(event) ? 'l' : 'c', 'l')
        break
      case 'PageUp':
        nextCell = findBottomTopCell(currentIndex, 't')
        break
      case 'PageDown':
        nextCell = findBottomTopCell(currentIndex, 'b')
        break
    }

    if (nextCell) {
      nextCell.focus()
    }
  }
}

import { useMemo } from 'react'
import type {
  DropdownOption,
  MRT_Column,
  MRT_ColumnDef,
  MRT_ColumnOrderState,
  MRT_DefinedColumnDef,
  MRT_DefinedTableOptions,
  MRT_FilterOption,
  MRT_Header,
  MRT_RowData,
  MRT_TableInstance,
} from '../types'

// `MRT_ColumnDef` is now the core `ColumnDef` union, so accessor-key / group /
// MRT-specific fields live on individual union members. This resolution code
// reads and mutates them freely, so it operates on a loose view via `any`.
export const getColumnId = <TData extends MRT_RowData>(
  columnDef: MRT_ColumnDef<TData>,
): string => {
  const def = columnDef as any
  return def.id ?? def.accessorKey?.toString?.() ?? def.header
}

export const getAllLeafColumnDefs = <TData extends MRT_RowData>(
  columns: Array<MRT_ColumnDef<TData>>,
): Array<MRT_ColumnDef<TData>> => {
  const allLeafColumnDefs: Array<MRT_ColumnDef<TData>> = []
  const getLeafColumns = (cols: Array<MRT_ColumnDef<TData>>) => {
    cols.forEach((col) => {
      const subCols = (col as any).columns as
        Array<MRT_ColumnDef<TData>> | undefined
      if (subCols) {
        getLeafColumns(subCols)
      } else {
        allLeafColumnDefs.push(col)
      }
    })
  }
  getLeafColumns(columns)
  return allLeafColumnDefs
}

export const prepareColumns = <TData extends MRT_RowData>({
  columnDefs,
  tableOptions,
}: {
  columnDefs: Array<MRT_ColumnDef<TData>>
  tableOptions: MRT_DefinedTableOptions<TData>
}): Array<MRT_DefinedColumnDef<TData>> => {
  // `filterFns` / `sortFns` are carried on the options object
  // at runtime (client-supplied custom fns), but aren't declared as core options
  // (they're feature-slot registries), so read them off a loose view.
  const {
    defaultDisplayColumn,
    filterFns = {},
    sortFns = {},
    state: { columnFilterFns = {} } = {},
  } = tableOptions as any
  return columnDefs.map((columnDef) => {
    const def = columnDef as any
    // assign columnId
    if (!def.id) def.id = getColumnId(columnDef)
    // assign columnDefType
    if (!def.columnDefType) def.columnDefType = 'data'
    if (def.columns?.length) {
      def.columnDefType = 'group'
      // recursively prepare columns if this is a group column
      def.columns = prepareColumns({
        columnDefs: def.columns,
        tableOptions,
      })
    } else if (def.columnDefType === 'data') {
      // assign filterFns
      if (Object.keys(filterFns).includes(columnFilterFns[def.id])) {
        def.filterFn = filterFns[columnFilterFns[def.id]] ?? filterFns.fuzzy
        def._filterFn = columnFilterFns[def.id]
      }

      // assign sortFns
      if (Object.keys(sortFns).includes(def.sortFn as string)) {
        def.sortFn = sortFns[def.sortFn as string]
      }
    } else if (def.columnDefType === 'display') {
      columnDef = {
        ...(defaultDisplayColumn as MRT_ColumnDef<TData>),
        ...columnDef,
      }
    }
    return columnDef
  }) as Array<MRT_DefinedColumnDef<TData>>
}

export const reorderColumn = <TData extends MRT_RowData>(
  draggedColumn: MRT_Column<TData>,
  targetColumn: MRT_Column<TData>,
  columnOrder: MRT_ColumnOrderState,
): MRT_ColumnOrderState => {
  if (draggedColumn.getCanPin()) {
    draggedColumn.pin(targetColumn.getIsPinned())
  }
  const newColumnOrder = [...columnOrder]
  newColumnOrder.splice(
    newColumnOrder.indexOf(targetColumn.id),
    0,
    newColumnOrder.splice(newColumnOrder.indexOf(draggedColumn.id), 1)[0],
  )
  return newColumnOrder
}

export const getDefaultColumnFilterFn = <TData extends MRT_RowData>(
  columnDef: MRT_ColumnDef<TData>,
): MRT_FilterOption => {
  const { filterVariant } = columnDef
  if (filterVariant === 'multi-select') return 'arrIncludesSome'
  if (filterVariant?.includes('range')) return 'betweenInclusive'
  if (filterVariant === 'select' || filterVariant === 'checkbox')
    return 'equals'
  return 'fuzzy'
}

export const getColumnFilterInfo = <TData extends MRT_RowData>({
  header,
  table,
}: {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}) => {
  const {
    options: { columnFilterModeOptions },
  } = table
  const { column } = header
  const { columnDef } = column
  const { filterVariant } = columnDef

  const isDateFilter = !!(
    filterVariant?.startsWith('date') || filterVariant?.startsWith('time')
  )
  const isAutocompleteFilter = filterVariant === 'autocomplete'
  const isRangeFilter =
    filterVariant?.includes('range') ||
    ['between', 'betweenInclusive', 'inNumberRange'].includes(
      columnDef._filterFn!,
    )
  const isSelectFilter = filterVariant === 'select'
  const isMultiSelectFilter = filterVariant === 'multi-select'
  const isTextboxFilter =
    ['autocomplete', 'text'].includes(filterVariant!) ||
    (!isSelectFilter && !isMultiSelectFilter)
  const currentFilterOption = columnDef._filterFn

  const allowedColumnFilterOptions =
    columnDef?.columnFilterModeOptions ?? columnFilterModeOptions

  const facetedUniqueValues = column.getFacetedUniqueValues()

  return {
    allowedColumnFilterOptions,
    currentFilterOption,
    facetedUniqueValues,
    isAutocompleteFilter,
    isDateFilter,
    isMultiSelectFilter,
    isRangeFilter,
    isSelectFilter,
    isTextboxFilter,
  } as const
}

export const useDropdownOptions = <TData extends MRT_RowData>({
  header,
  table,
}: {
  header: MRT_Header<TData>
  table: MRT_TableInstance<TData>
}): Array<DropdownOption> | undefined => {
  const { column } = header
  const { columnDef } = column
  const {
    facetedUniqueValues,
    isAutocompleteFilter,
    isMultiSelectFilter,
    isSelectFilter,
  } = getColumnFilterInfo({ header, table })

  return useMemo<Array<DropdownOption> | undefined>(
    () =>
      columnDef.filterSelectOptions ??
      ((isSelectFilter || isMultiSelectFilter || isAutocompleteFilter) &&
      facetedUniqueValues
        ? Array.from(facetedUniqueValues.keys())
            .filter((value) => value !== null && value !== undefined)
            .sort((a, b) => a.localeCompare(b))
        : undefined),
    [
      columnDef.filterSelectOptions,
      facetedUniqueValues,
      isMultiSelectFilter,
      isSelectFilter,
    ],
  )
}

import { getAllLeafColumnDefs, getColumnId } from './column.utils'
import type {
  MRT_DefinedTableOptions,
  MRT_DisplayColumnIds,
  MRT_Localization,
  MRT_RowData,
  MRT_StatefulTableOptions,
} from '../types'

export function defaultDisplayColumnProps<TData extends MRT_RowData>({
  header,
  id,
  size,
  tableOptions,
}: {
  header?: keyof MRT_Localization
  id: MRT_DisplayColumnIds
  size: number
  tableOptions: MRT_DefinedTableOptions<TData>
}) {
  const { defaultDisplayColumn, displayColumnDefOptions, localization } =
    tableOptions
  return {
    ...defaultDisplayColumn,
    header: header ? localization[header] : '',
    size,
    ...displayColumnDefOptions?.[id],
    id,
  } as const
}

export const showRowPinningColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const { enableRowPinning, rowPinningDisplayMode } = tableOptions
  return !!(enableRowPinning && !rowPinningDisplayMode?.startsWith('select'))
}

export const showRowDragColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const { enableRowDragging, enableRowOrdering } = tableOptions
  return !!(enableRowDragging || enableRowOrdering)
}

export const showRowExpandColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const {
    enableExpanding,
    enableGrouping,
    renderDetailPanel,
    state: { grouping },
  } = tableOptions
  return !!(
    enableExpanding ||
    (enableGrouping && grouping?.length) ||
    renderDetailPanel
  )
}

export const showRowActionsColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => {
  const {
    createDisplayMode,
    editDisplayMode,
    enableEditing,
    enableRowActions,
    state: { creatingRow },
  } = tableOptions
  return !!(
    enableRowActions ||
    (creatingRow && createDisplayMode === 'row') ||
    (enableEditing && ['modal', 'row'].includes(editDisplayMode ?? ''))
  )
}

export const showRowSelectionColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => !!tableOptions.enableRowSelection

export const showRowNumbersColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => !!tableOptions.enableRowNumbers

export const showRowSpacerColumn = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
): boolean => tableOptions.layoutMode === 'grid-no-grow'

export const getLeadingDisplayColumnIds = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
) =>
  [
    showRowPinningColumn(tableOptions) && 'mrt-row-pin',
    showRowDragColumn(tableOptions) && 'mrt-row-drag',
    tableOptions.positionActionsColumn === 'first' &&
      showRowActionsColumn(tableOptions) &&
      'mrt-row-actions',
    tableOptions.positionExpandColumn === 'first' &&
      showRowExpandColumn(tableOptions) &&
      'mrt-row-expand',
    showRowSelectionColumn(tableOptions) && 'mrt-row-select',
    showRowNumbersColumn(tableOptions) && 'mrt-row-numbers',
  ].filter(Boolean) as Array<MRT_DisplayColumnIds>

export const getTrailingDisplayColumnIds = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
) =>
  [
    tableOptions.positionActionsColumn === 'last' &&
      showRowActionsColumn(tableOptions) &&
      'mrt-row-actions',
    tableOptions.positionExpandColumn === 'last' &&
      showRowExpandColumn(tableOptions) &&
      'mrt-row-expand',
    showRowSpacerColumn(tableOptions) && 'mrt-row-spacer',
  ].filter(Boolean) as Array<MRT_DisplayColumnIds>

export const getDefaultColumnOrderIds = <TData extends MRT_RowData>(
  tableOptions: MRT_StatefulTableOptions<TData>,
  reset = false,
) => {
  const {
    state: { columnOrder: currentColumnOrderIds = [] },
  } = tableOptions

  const leadingDisplayColIds: Array<string> =
    getLeadingDisplayColumnIds(tableOptions)
  const trailingDisplayColIds: Array<string> =
    getTrailingDisplayColumnIds(tableOptions)

  const defaultColumnDefIds = getAllLeafColumnDefs(
    tableOptions.columns as any,
  ).map((columnDef) => getColumnId(columnDef))

  let allLeafColumnDefIds = reset
    ? defaultColumnDefIds
    : Array.from(new Set([...currentColumnOrderIds, ...defaultColumnDefIds]))

  allLeafColumnDefIds = allLeafColumnDefIds.filter(
    (colId) =>
      !leadingDisplayColIds.includes(colId) &&
      !trailingDisplayColIds.includes(colId),
  )

  return [
    ...leadingDisplayColIds,
    ...allLeafColumnDefIds,
    ...trailingDisplayColIds,
  ]
}

import { rankGlobalFuzzy } from '../fns/sortingFns'
import { parseFromValuesOrFunc } from './utils'
import type { ChangeEvent, MouseEvent } from 'react'
import type { MRT_Row, MRT_RowData, MRT_TableInstance } from '../types'

export const getMRT_Rows = <TData extends MRT_RowData>(
  table: MRT_TableInstance<TData>,
  all?: boolean,
): Array<MRT_Row<TData>> => {
  const {
    getCenterRows,
    getPrePaginatedRowModel,
    getRowModel,
    state,
    getTopRows,
    options: {
      createDisplayMode,
      enablePagination,
      enableRowPinning,
      manualPagination,
      positionCreatingRow,
      rowPinningDisplayMode,
    },
  } = table
  const { creatingRow, pagination } = state

  const isRankingRows = getIsRankingRows(table)

  let rows: Array<MRT_Row<TData>> = []
  if (!isRankingRows) {
    rows =
      !enableRowPinning || rowPinningDisplayMode?.includes('sticky')
        ? all
          ? getPrePaginatedRowModel().rows
          : getRowModel().rows
        : getCenterRows()
  } else {
    // fuzzy ranking adjustments
    rows = getPrePaginatedRowModel().rows.sort((a, b) => rankGlobalFuzzy(a, b))
    if (enablePagination && !manualPagination && !all) {
      const start = pagination.pageIndex * pagination.pageSize
      rows = rows.slice(start, start + pagination.pageSize)
    }
    if (enableRowPinning && !rowPinningDisplayMode?.includes('sticky')) {
      // "re-center-ize" the rows (no top or bottom pinned rows unless sticky)
      rows = rows.filter((row) => !row.getIsPinned())
    }
  }
  // row pinning adjustments
  if (enableRowPinning && rowPinningDisplayMode?.includes('sticky')) {
    const centerPinnedRowIds = rows
      .filter((row) => row.getIsPinned())
      .map((r) => r.id)

    rows = [
      ...getTopRows().filter((row) => !centerPinnedRowIds.includes(row.id)),
      ...rows,
    ]
  }
  // blank inserted creating row adjustments
  if (
    positionCreatingRow !== undefined &&
    creatingRow &&
    createDisplayMode === 'row'
  ) {
    const creatingRowIndex = !isNaN(+positionCreatingRow)
      ? +positionCreatingRow
      : positionCreatingRow === 'top'
        ? 0
        : rows.length
    rows = [
      ...rows.slice(0, creatingRowIndex),
      creatingRow as MRT_Row<TData>,
      ...rows.slice(creatingRowIndex),
    ]
  }

  return rows
}

export const getCanRankRows = <TData extends MRT_RowData>(
  table: MRT_TableInstance<TData>,
) => {
  const {
    state,
    options: {
      enableGlobalFilterRankedResults,
      manualExpanding,
      manualFiltering,
      manualGrouping,
      manualSorting,
    },
  } = table
  const { expanded, globalFilterFn } = state

  return (
    !manualExpanding &&
    !manualFiltering &&
    !manualGrouping &&
    !manualSorting &&
    enableGlobalFilterRankedResults &&
    globalFilterFn === 'fuzzy' &&
    expanded !== true &&
    !Object.values(expanded).some(Boolean)
  )
}

export const getIsRankingRows = <TData extends MRT_RowData>(
  table: MRT_TableInstance<TData>,
) => {
  const { globalFilter, sorting } = table.state

  return (
    getCanRankRows(table) &&
    globalFilter &&
    !Object.values(sorting).some(Boolean)
  )
}

export const getIsRowSelected = <TData extends MRT_RowData>({
  row,
  table,
}: {
  row: MRT_Row<TData>
  table: MRT_TableInstance<TData>
}) => {
  const {
    options: { enableRowSelection },
  } = table

  return (
    row.getIsSelected() ||
    (parseFromValuesOrFunc(enableRowSelection, row) &&
      row.getCanSelectSubRows() &&
      row.getIsAllSubRowsSelected())
  )
}

export const getMRT_RowSelectionHandler =
  <TData extends MRT_RowData>({
    row,
    staticRowIndex = 0,
    table,
  }: {
    row: MRT_Row<TData>
    staticRowIndex?: number
    table: MRT_TableInstance<TData>
  }) =>
  (
    event: ChangeEvent<HTMLInputElement> | MouseEvent<HTMLTableRowElement>,
    value?: boolean,
  ) => {
    const {
      state,
      options: {
        enableBatchRowSelection,
        enableMultiRowSelection,
        enableRowPinning,
        manualPagination,
        rowPinningDisplayMode,
      },
      refs: { lastSelectedRowId: lastSelectedRowId },
    } = table
    const {
      pagination: { pageIndex, pageSize },
    } = state

    const paginationOffset = manualPagination ? 0 : pageSize * pageIndex

    const wasCurrentRowChecked = getIsRowSelected({ row, table })

    // toggle selection of this row
    row.toggleSelected(value ?? !wasCurrentRowChecked)

    const changedRowIds = new Set<string>([row.id])

    // if shift key is pressed, select all rows between last selected and this one
    if (
      enableBatchRowSelection &&
      enableMultiRowSelection &&
      (event as any).nativeEvent.shiftKey &&
      lastSelectedRowId.current !== null
    ) {
      const rows = getMRT_Rows(table, true)

      const lastIndex = rows.findIndex(
        (r) => r.id === lastSelectedRowId.current,
      )

      if (lastIndex !== -1) {
        const isLastIndexChecked = getIsRowSelected({
          row: rows?.[lastIndex],
          table,
        })

        const currentIndex = staticRowIndex + paginationOffset
        const [start, end] =
          lastIndex < currentIndex
            ? [lastIndex, currentIndex]
            : [currentIndex, lastIndex]

        // toggle selection of all rows between last selected and this one
        // but only if the last selected row is not the same as the current one
        if (wasCurrentRowChecked !== isLastIndexChecked) {
          for (let i = start; i <= end; i++) {
            rows[i].toggleSelected(!wasCurrentRowChecked)
            changedRowIds.add(rows[i].id)
          }
        }
      }
    }

    // record the last selected row id
    lastSelectedRowId.current = row.id

    // if all sub rows were selected, unselect them
    if (row.getCanSelectSubRows() && row.getIsAllSubRowsSelected()) {
      row.subRows?.forEach((r) => r.toggleSelected(false))
    }

    if (enableRowPinning && rowPinningDisplayMode?.includes('select')) {
      changedRowIds.forEach((rowId) => {
        const rowToTogglePin = table.getRow(rowId)
        rowToTogglePin.pin(
          !wasCurrentRowChecked // was not previously pinned or selected
            ? rowPinningDisplayMode?.includes('bottom')
              ? 'bottom'
              : 'top'
            : false,
        )
      })
    }
  }

export const getMRT_SelectAllHandler =
  <TData extends MRT_RowData>({ table }: { table: MRT_TableInstance<TData> }) =>
  (
    event: ChangeEvent<HTMLInputElement> | MouseEvent<HTMLButtonElement>,
    value?: boolean,
    forceAll?: boolean,
  ) => {
    const {
      options: { enableRowPinning, rowPinningDisplayMode, selectAllMode },
      refs: { lastSelectedRowId },
    } = table

    selectAllMode === 'all' || forceAll
      ? table.toggleAllRowsSelected(value ?? (event as any).target.checked)
      : table.toggleAllPageRowsSelected(value ?? (event as any).target.checked)
    if (enableRowPinning && rowPinningDisplayMode?.includes('select')) {
      table.setRowPinning({ bottom: [], top: [] })
    }
    lastSelectedRowId.current = null
  }

import { alpha, darken, lighten } from '@mui/material/styles'
import { parseFromValuesOrFunc } from './utils'
import type { CSSProperties } from 'react'
import type { TableCellProps } from '@mui/material/TableCell'
import type { TooltipProps } from '@mui/material/Tooltip'
import type { Theme } from '@mui/material/styles'
import type {
  MRT_Column,
  MRT_Header,
  MRT_RowData,
  MRT_TableInstance,
  MRT_TableOptions,
  MRT_Theme,
} from '../types'

export const parseCSSVarId = (id: string) => id.replace(/[^a-zA-Z0-9]/g, '_')

export const getMRTTheme = <TData extends MRT_RowData>(
  mrtTheme: MRT_TableOptions<TData>['mrtTheme'],
  muiTheme: Theme,
): MRT_Theme => {
  const mrtThemeOverrides = parseFromValuesOrFunc(mrtTheme, muiTheme)
  const baseBackgroundColor =
    mrtThemeOverrides?.baseBackgroundColor ??
    (muiTheme.palette.mode === 'dark'
      ? lighten(muiTheme.palette.background.default, 0.05)
      : muiTheme.palette.background.default)
  return {
    baseBackgroundColor,
    cellNavigationOutlineColor: muiTheme.palette.primary.main,
    draggingBorderColor: muiTheme.palette.primary.main,
    matchHighlightColor:
      muiTheme.palette.mode === 'dark'
        ? darken(muiTheme.palette.warning.dark, 0.25)
        : lighten(muiTheme.palette.warning.light, 0.5),
    menuBackgroundColor: lighten(baseBackgroundColor, 0.07),
    pinnedRowBackgroundColor: alpha(muiTheme.palette.primary.main, 0.1),
    selectedRowBackgroundColor: alpha(muiTheme.palette.primary.main, 0.2),
    ...mrtThemeOverrides,
  }
}

export const commonCellBeforeAfterStyles = {
  content: '""',
  height: '100%',
  left: 0,
  position: 'absolute',
  top: 0,
  width: '100%',
  zIndex: -1,
}

export const getCommonPinnedCellStyles = <TData extends MRT_RowData>({
  column,
  table,
  theme,
}: {
  column?: MRT_Column<TData>
  table: MRT_TableInstance<TData>
  theme: Theme
}) => {
  const { baseBackgroundColor } = table.options.mrtTheme
  const isPinned = column?.getIsPinned()

  return {
    '&[data-pinned="true"]': {
      '&:before': {
        backgroundColor: alpha(
          darken(
            baseBackgroundColor,
            theme.palette.mode === 'dark' ? 0.05 : 0.01,
          ),
          0.97,
        ),
        boxShadow: column
          ? isPinned === 'start' && column.getIsLastColumn(isPinned)
            ? `-4px 0 4px -4px ${alpha(theme.palette.grey[700], 0.5)} inset`
            : isPinned === 'end' && column.getIsFirstColumn(isPinned)
              ? `4px 0 4px -4px ${alpha(theme.palette.grey[700], 0.5)} inset`
              : undefined
          : undefined,
        ...commonCellBeforeAfterStyles,
      },
    },
  }
}

export const getCommonMRTCellStyles = <TData extends MRT_RowData>({
  column,
  header,
  table,
  tableCellProps,
  theme,
}: {
  column: MRT_Column<TData>
  header?: MRT_Header<TData>
  table: MRT_TableInstance<TData>
  tableCellProps: TableCellProps
  theme: Theme
}) => {
  const {
    state,
    options: { enableColumnVirtualization, layoutMode },
  } = table
  const { draggingColumn } = state
  const { columnDef } = column
  const { columnDefType } = columnDef

  const isColumnPinned =
    columnDef.columnDefType !== 'group' && column.getIsPinned()

  const widthStyles: CSSProperties = {
    minWidth: `max(calc(var(--${header ? 'header' : 'col'}-${parseCSSVarId(
      header?.id ?? column.id,
    )}-size) * 1px), ${columnDef.minSize ?? 30}px)`,
    width: `calc(var(--${header ? 'header' : 'col'}-${parseCSSVarId(
      header?.id ?? column.id,
    )}-size) * 1px)`,
  }

  if (layoutMode === 'grid') {
    widthStyles.flex = `${
      [0, false].includes(columnDef.grow!)
        ? 0
        : `var(--${header ? 'header' : 'col'}-${parseCSSVarId(
            header?.id ?? column.id,
          )}-size)`
    } 0 auto`
  } else if (layoutMode === 'grid-no-grow') {
    widthStyles.flex = `${+(columnDef.grow || 0)} 0 auto`
  }

  const pinnedStyles = isColumnPinned
    ? {
        ...getCommonPinnedCellStyles({ column, table, theme }),
        insetInlineStart:
          isColumnPinned === 'start'
            ? `${column.getStart('start')}px`
            : undefined,
        opacity: 0.97,
        position: 'sticky',
        insetInlineEnd:
          isColumnPinned === 'end' ? `${column.getAfter('end')}px` : undefined,
      }
    : {}

  return {
    backgroundColor: 'inherit',
    backgroundImage: 'inherit',
    display: layoutMode?.startsWith('grid') ? 'flex' : undefined,
    justifyContent:
      columnDefType === 'group'
        ? 'center'
        : layoutMode?.startsWith('grid')
          ? tableCellProps.align
          : undefined,
    opacity:
      table.state.draggingColumn?.id === column.id ||
      table.state.hoveredColumn?.id === column.id
        ? 0.5
        : 1,
    position: 'relative',
    transition: enableColumnVirtualization
      ? 'none'
      : `padding 150ms ease-in-out`,
    zIndex:
      column.getIsResizing() || draggingColumn?.id === column.id
        ? 2
        : columnDefType !== 'group' && isColumnPinned
          ? 1
          : 0,
    '&:focus-visible': {
      outline: `2px solid ${table.options.mrtTheme.cellNavigationOutlineColor}`,
      outlineOffset: '-2px',
    },
    ...pinnedStyles,
    ...widthStyles,
    ...(parseFromValuesOrFunc(tableCellProps?.sx, theme) as any),
  }
}

export const getCommonToolbarStyles = <TData extends MRT_RowData>({
  table,
}: {
  table: MRT_TableInstance<TData>
  theme: Theme
}) => ({
  alignItems: 'flex-start',
  backgroundColor: table.options.mrtTheme.baseBackgroundColor,
  display: 'grid',
  flexWrap: 'wrap-reverse',
  minHeight: '3.5rem',
  overflow: 'hidden',
  position: 'relative',
  transition: 'all 150ms ease-in-out',
  zIndex: 1,
})

export const flipIconStyles = (theme: Theme) =>
  theme.direction === 'rtl' ? { style: { transform: 'scaleX(-1)' } } : undefined

export const getCommonTooltipProps = (
  placement?: TooltipProps['placement'],
): Partial<TooltipProps> => ({
  disableInteractive: true,
  enterDelay: 1000,
  enterNextDelay: 1000,
  placement,
})

import type { DropdownOption } from '../types'

export const parseFromValuesOrFunc = <T, U>(
  fn: ((arg: U) => T) | T | undefined,
  arg: U,
): T | undefined => (fn instanceof Function ? fn(arg) : fn)

export const getValueAndLabel = (
  option?: DropdownOption | null,
): { label: string; value: string } => {
  let label = ''
  let value = ''
  if (option) {
    if (typeof option !== 'object') {
      label = option
      value = option
    } else {
      label = option.label ?? option.value
      value = option.value ?? label
    }
  }
  return { label, value }
}

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return { errors, server }
}

async function getFirstEmailText(page: Page) {
  const text = await page.getByText(/@/).first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    await expect(
      page.getByRole('heading', { name: /Material React Table/i }),
    ).toBeVisible()
    await expect(page.getByText('First Name').first()).toBeVisible()
    await expect(page.getByText('Last Name').first()).toBeVisible()
    await expect(page.getByText('Email').first()).toBeVisible()
    expect(errors).toEqual([])
  } finally {
    await server.close()
  }
})

test('regenerates table data', async ({ page }) => {
  const { errors, server } = await openExample(page)

  try {
    const regenerateButton = page.getByRole('button', {
      name: /^Regenerate Data$/i,
