                                  </div>
                                )}
                              </th>
                            )}
                          </table.AppHeader>
                        ))}
                      </tr>
                    ))}
                  </thead>
                  <tbody>
                    {table.getRowModel().rows.map((row) => (
                      <tr key={row.id}>
                        {row.getAllCells().map((cell) => (
                          <td key={cell.id}>
                            <table.FlexRender cell={cell} />
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <table.PaginationControls />
              <table.RowCount />
            </>
          )}
        </table.AppTable>
      </form>
    </section>
  )
}

