export const Route = createFileRoute('/')({
  component: UsersPage,
  validateSearch: () => ({}) as UserFilters,
})

function UsersPage() {
  const { filters, resetFilters, setFilters } = useFilters(Route.fullPath)

  const { data } = useQuery({
    queryKey: ['users', filters],
    queryFn: () => fetchUsers(filters),
    placeholderData: keepPreviousData,
  })

  const paginationState = {
    pageIndex: filters.pageIndex ?? DEFAULT_PAGE_INDEX,
    pageSize: filters.pageSize ?? DEFAULT_PAGE_SIZE,
  }
  const sortingState = sortByToState(filters.sortBy)
  const columns = useMemo(() => USER_COLUMNS, [])

  return (
    <div className="router-root">
      <h1 className="page-title">TanStack Table + Query + Router</h1>
      <Table
        data={data?.result ?? []}
        columns={columns}
        pagination={paginationState}
        paginationOptions={{
          onPaginationChange: (pagination) => {
            setFilters(
              typeof pagination === 'function'
                ? pagination(paginationState)
                : pagination,
            )
          },
          rowCount: data?.rowCount,
        }}
        filters={filters}
        onFilterChange={(filters) =>
          setFilters({ ...filters, pageIndex: DEFAULT_PAGE_INDEX })
        }
        sorting={sortingState}
        onSortingChange={(updaterOrValue) => {
          const newSortingState =
            typeof updaterOrValue === 'function'
              ? updaterOrValue(sortingState)
              : updaterOrValue
          return setFilters({
            sortBy: stateToSortBy(newSortingState),
            pageIndex: DEFAULT_PAGE_INDEX,
          })
        }}
      />
      <div className="controls">
        {data?.rowCount?.toLocaleString()} users found
        <button
          className="demo-button demo-button-sm disabled-button"
          onClick={resetFilters}
          disabled={Object.keys(filters).length === 0}
        >
          Reset Filters
        </button>
      </div>
      <pre>{JSON.stringify(filters, null, 2)}</pre>
    </div>
  )
}

import { DEFAULT_PAGE_INDEX, DEFAULT_PAGE_SIZE } from '../components/table'

export const cleanEmptyParams = <T extends Record<string, unknown>>(
  search: T,
): T => {
  const newSearch = { ...search }
  Object.keys(newSearch).forEach((key) => {
    const value = newSearch[key]
    if (
      value === undefined ||
      value === '' ||
      (typeof value === 'number' && isNaN(value))
    )
      delete newSearch[key]
  })

  if (search.pageIndex === DEFAULT_PAGE_INDEX) delete newSearch.pageIndex
  if (search.pageSize === DEFAULT_PAGE_SIZE) delete newSearch.pageSize

  return newSearch
}

import type { SortingState } from '@tanstack/react-table'
import type { SortParams } from '../api/types'

export const stateToSortBy = (sorting: SortingState | undefined) => {
  if (!sorting || sorting.length == 0) return undefined

  const sort = sorting[0]

  return `${sort.id}.${sort.desc ? 'desc' : 'asc'}` as const
}

export const sortByToState = (sortBy: SortParams['sortBy'] | undefined) => {
  if (!sortBy) return []

  const [id, desc] = sortBy.split('.')
  return [{ id, desc: desc === 'desc' }]
}

