import { createVirtualizer } from '@tanstack/solid-virtual'
import { createEffect, createMemo } from 'solid-js'
import type { Accessor } from 'solid-js'
import type { TradingRow } from './trading-table-features'

export const TRADING_ROW_HEIGHT = 32
export const TRADING_ROW_OVERSCAN = 10
export const DEFAULT_VIRTUALIZATION_ROW_COUNT = 200
export const FORCED_VIRTUALIZATION_ROW_COUNT = 1_500

export type VirtualScrollMode = 'tanstack' | 'none'
export type VirtualScrollPreference = VirtualScrollMode | 'auto'

export interface TradingRowVirtualizationOptions {
  rows: Accessor<Array<TradingRow>>
  scrollElement: Accessor<HTMLDivElement | null>
  enabled: Accessor<boolean>
  onRenderedRowCount: (count: number) => void
}

export function createTradingRowVirtualization(
  options: TradingRowVirtualizationOptions,
) {
  const virtualizer = createVirtualizer<HTMLDivElement, HTMLTableRowElement>({
    get count() {
      return options.rows().length
    },
    estimateSize: () => TRADING_ROW_HEIGHT,
    getScrollElement: options.scrollElement,
    getItemKey: (index) => options.rows()[index]?.id ?? index,
    overscan: TRADING_ROW_OVERSCAN,
    get enabled() {
      return options.enabled()
    },
  })
  const virtualRows = virtualizer.getVirtualItems
  const visibleRange = createMemo(() => {
    const items = virtualRows()
    const rowCount = options.rows().length
    if (!options.enabled() || rowCount === 0 || items.length === 0) return null

    const lastRowIndex = rowCount - 1
    const start = Math.min(items[0]!.index, lastRowIndex)
    return {
      start,
      end: Math.min(items[items.length - 1]!.index, lastRowIndex),
    }
  })
  const bodyHeight = createMemo(() =>
    options.enabled()
      ? `${options.rows().length * TRADING_ROW_HEIGHT}px`
      : undefined,
  )

  createEffect(() => {
    options.onRenderedRowCount(
      options.enabled() ? virtualRows().length : options.rows().length,
    )
  })

  return { bodyHeight, virtualizer, virtualRows, visibleRange }
}

export type TradingRowVirtualization = ReturnType<
  typeof createTradingRowVirtualization
>

export function resolveVirtualScrollMode(
  requestedMode: VirtualScrollPreference,
  instrumentCount: number,
): VirtualScrollMode {
  if (instrumentCount >= FORCED_VIRTUALIZATION_ROW_COUNT) return 'tanstack'
  if (requestedMode !== 'auto') return requestedMode
  return instrumentCount >= DEFAULT_VIRTUALIZATION_ROW_COUNT
    ? 'tanstack'
    : 'none'
}

import { Index, Show, createMemo } from 'solid-js'
import { createTradingGridSelectionHandlers } from './table-interactions'
import { TradingTableRow } from './trading-table-row'
import type { Accessor, JSX } from 'solid-js'
import type { TradingColumnSet } from './table-config/trading-columns'
import type { TradingRowVirtualization } from './trading-row-virtualizer'
import type { TradingRow, TradingTableInstance } from './trading-table-features'

export interface TradingTableBodyProps {
  table: TradingTableInstance
  rows: Accessor<Array<TradingRow>>
  columnVersion: Accessor<TradingColumnSet>
  selectedSymbol: Accessor<string | null>
  virtualized: Accessor<boolean>
  virtualization: TradingRowVirtualization
  selectSymbol: (symbol: string) => void
}

export function TradingTableBody(props: TradingTableBodyProps) {
  const bodyProps = createTradingTableBodyProps(props)

  return (
    <tbody {...bodyProps}>
      <Show when={props.virtualized()} fallback={<FullTableRows {...props} />}>
        <VirtualTableRows {...props} />
      </Show>
    </tbody>
  )
}

function FullTableRows(props: TradingTableBodyProps) {
  return (
    <Index each={props.rows()}>
      {(row) => (
        <TradingTableRow
          row={row()}
          columnVersion={props.columnVersion()}
          selectedSymbol={props.selectedSymbol()}
        />
      )}
    </Index>
  )
}

function VirtualTableRows(props: TradingTableBodyProps) {
  return (
    <Index each={props.virtualization.virtualRows()}>
      {(virtualRow) => {
        const row = createMemo(() => props.rows()[virtualRow().index])
        return (
          <TradingTableRow
            row={row()}
            columnVersion={props.columnVersion()}
            selectedSymbol={props.selectedSymbol()}
            virtualItem={virtualRow()}
          />
        )
      }}
    </Index>
  )
}

function createTradingTableBodyProps(
  options: TradingTableBodyProps,
): JSX.IntrinsicElements['tbody'] {
  const selectionHandlers = createTradingGridSelectionHandlers(
    options.table,
    options.selectSymbol,
  )

  return {
    ...selectionHandlers,
    get classList() {
      return { 'virtual-table-body': options.virtualized() }
    },
    get style() {
      const height = options.virtualization.bodyHeight()
      return height === undefined ? undefined : { height }
    },
  }
}

import { createEffect, onCleanup, onMount } from 'solid-js'
import type { Accessor } from 'solid-js'
import type { TradingTableInstance } from './trading-table-features'

export function createFeedCommitTracking(
  quotes: Accessor<unknown>,
  completeCommit: () => void,
): void {
  const runtime = { queued: false, disposed: false }

  createEffect(() => {
    quotes()
    if (runtime.queued) return

    runtime.queued = true
    queueMicrotask(() => {
      runtime.queued = false
      if (!runtime.disposed) completeCommit()
    })
  })

  onCleanup(() => {
    runtime.disposed = true
  })
}

export function createTableAutoFit(
  table: TradingTableInstance,
  scrollElement: Accessor<HTMLDivElement | null>,
): void {
  const runtime = { manuallyResized: false }

  onMount(() => {
    const fitAvailableWidth = (): void => {
      const element = scrollElement()
      if (!element || runtime.manuallyResized) return

      const currentWidth = table.getTotalSize()
      const availableWidth = element.clientWidth
      if (availableWidth <= currentWidth + 1 || currentWidth <= 0) return

      const ratio = availableWidth / currentWidth
      table.setColumnSizing(
        Object.fromEntries(
          table
            .getVisibleLeafColumns()
            .map((column) => [column.id, column.getSize() * ratio]),
        ),
      )
    }
    const resizeObserver = new ResizeObserver(fitAvailableWidth)
    const resizingSubscription = table.atoms.columnResizing.subscribe(
      (state) => {
        if (state.isResizingColumn !== false) {
          runtime.manuallyResized = true
        }
      },
    )
    const element = scrollElement()
    if (element) resizeObserver.observe(element)
    fitAvailableWidth()

    onCleanup(() => {
      resizeObserver.disconnect()
      resizingSubscription.unsubscribe()
    })
  })
}

import { Show } from 'solid-js'
import type { Accessor } from 'solid-js'
import type { TradingRowVirtualization } from './trading-row-virtualizer'
import type { TradingRow, TradingTableInstance } from './trading-table-features'

export interface TradingTableFooterProps {
  table: TradingTableInstance
  rows: Accessor<Array<TradingRow>>
  virtualized: Accessor<boolean>
  virtualization: TradingRowVirtualization
}

function visibleRangeLabel(virtualization: TradingRowVirtualization): string {
  const items = virtualization.virtualRows()
  if (items.length === 0) return 'Current · rows —'
  return `Current · rows ${items[0]!.index}..${items[items.length - 1]!.index}`
}

export function TradingTableFooter(props: TradingTableFooterProps) {
  return (
    <Show when={props.virtualized()}>
      <footer class="virtual-scroll-footer" data-testid="virtual-scroll-footer">
        <span>
          TanStack · Total · {props.rows().length} rows ·{' '}
          {props.table.getVisibleLeafColumns().length} columns
        </span>
        <span data-testid="visible-row-range">
          {visibleRangeLabel(props.virtualization)}
        </span>
      </footer>
    </Show>
  )
}

import { FlexRender } from '@tanstack/solid-table'
import { For, Show } from 'solid-js'
import { createColumnDrag } from './create-column-drag'
import { sortAriaValue, sortIndicator } from './table-interactions'
import type { JSX } from 'solid-js'
import type { ColumnDrag } from './create-column-drag'
import type {
  TradingHeader,
  TradingTableInstance,
} from './trading-table-features'

export interface TradingTableHeaderProps {
  table: TradingTableInstance
}

export function TradingTableHeader(props: TradingTableHeaderProps) {
  const columnDrag = createColumnDrag(props.table)

  return (
    <thead>
      <For each={props.table.getHeaderGroups()}>
        {(headerGroup) => (
          <tr>
            <For each={headerGroup.headers}>
              {(header) => (
                <TradingHeaderCell header={header} columnDrag={columnDrag} />
              )}
            </For>
          </tr>
        )}
      </For>
    </thead>
  )
}

interface TradingHeaderCellProps {
  header: TradingHeader
  columnDrag: ColumnDrag
}

function TradingHeaderCell(props: TradingHeaderCellProps) {
  const isLeaf = () => props.header.subHeaders.length === 0
  const headerCellProps = createHeaderCellProps(
    () => props.header,
    isLeaf,
    props.columnDrag,
  )

  return (
    <th {...headerCellProps}>
      <Show when={!props.header.isPlaceholder}>
        <Show when={isLeaf()} fallback={<FlexRender header={props.header} />}>
          <TradingLeafHeader
            header={props.header}
            columnDrag={props.columnDrag}
          />
        </Show>
      </Show>
    </th>
  )
}

function TradingLeafHeader(props: TradingHeaderCellProps) {
  const dropZoneProps = props.columnDrag.createDropZoneProps(
    props.header.column.id,
  )
  const dragHandleProps = props.columnDrag.createHandleProps(
    props.header.column.id,
  )
  const sortButtonProps = createSortButtonProps(() => props.header)
  const resizeHandleProps = createResizeHandleProps(() => props.header)

  return (
    <>
      <div class="leaf-header-content" {...dropZoneProps}>
        <button type="button" class="column-drag-handle" {...dragHandleProps}>
          ⋮⋮
        </button>
        <button {...sortButtonProps}>
          <span class="header-label">
            <FlexRender header={props.header} />
          </span>
          <Show when={props.header.column.getCanSort()}>
            <span
              class="sort-indicator"
              classList={{
                'is-active': !!props.header.column.getIsSorted(),
              }}
              aria-hidden="true"
            >
              {sortIndicator(props.header.column.getIsSorted())}
            </span>
          </Show>
        </button>
      </div>
      <Show when={props.header.column.getCanResize()}>
        <div {...resizeHandleProps} />
      </Show>
    </>
  )
}

function createHeaderCellProps(
  header: () => TradingHeader,
  isLeaf: () => boolean,
  columnDrag: ColumnDrag,
): JSX.IntrinsicElements['th'] {
  return {
    get colSpan() {
      return header().colSpan
    },
    get style() {
      return {
        width: `calc(var(--header-${header().id}-size) * 1px)`,
      }
    },
    get ['aria-sort']() {
      return isLeaf() ? sortAriaValue(header().column.getIsSorted()) : undefined
    },
    get classList() {
      const columnId = header().column.id
      return {
        'column-group-header': !isLeaf(),
        'numeric-header': isLeaf() && !isTextColumn(columnId),
        'is-column-dragging': columnDrag.isDragging(columnId),
        'is-column-drop-target': columnDrag.isDropTarget(columnId),
      }
    },
  }
}

function createSortButtonProps(
  header: () => TradingHeader,
): JSX.IntrinsicElements['button'] {
  return {
    type: 'button',
    class: 'sort-header-button',
    get classList() {
      return { 'is-sortable': header().column.getCanSort() }
    },
    get disabled() {
      return !header().column.getCanSort()
    },
    onClick: header().column.getToggleSortingHandler(),
  }
}

function createResizeHandleProps(
  header: () => TradingHeader,
): JSX.IntrinsicElements['div'] {
  return {
    class: 'column-resize-handle',
    get classList() {
      return { 'is-resizing': header().column.getIsResizing() }
    },
    role: 'separator',
    'aria-orientation': 'vertical',
    onDblClick: () => header().column.resetSize(),
    onMouseDown: header().getResizeHandler(),
    onTouchStart: header().getResizeHandler(),
  }
}

function isTextColumn(columnId: string): boolean {
  return columnId === 'market' || columnId === 'name' || columnId === 'symbol'
}

import { FlexRender } from '@tanstack/solid-table'
import { Index, createMemo } from 'solid-js'
import { TradingRowDataProvider } from './trading-row-data-context'
import type { VirtualItem } from '@tanstack/solid-virtual'
import type { TradingColumnSet } from './table-config/trading-columns'
import type { TradingCell, TradingRow } from './trading-table-features'

export interface TradingTableRowProps {
  row: TradingRow
  columnVersion: TradingColumnSet
  selectedSymbol: string | null
  virtualItem?: VirtualItem
}

interface TradingTableCellProps {
  cell: TradingCell
  renderCell: TradingCell
}

export function TradingTableRow(props: TradingTableRowProps) {
  const currentCells = createMemo(() => props.row.getVisibleCells())
  const renderState = createMemo(
    () => ({
      rowId: props.row.id,
      columns: props.columnVersion,
      cells: currentCells(),
    }),
    undefined,
    {
      equals: (previous, next) =>
        previous.rowId === next.rowId &&
        previous.columns === next.columns &&
        haveSameCellOrder(previous.cells, next.cells),
    },
  )

  return (
    <TradingRowDataProvider quote={() => props.row.original}>
      <tr
        classList={{ 'virtual-table-row': props.virtualItem !== undefined }}
        style={
          props.virtualItem
            ? { transform: `translateY(${props.virtualItem.start}px)` }
            : undefined
        }
        data-virtual-index={props.virtualItem?.index}
        data-symbol={props.row.original.symbol}
        data-row-id={props.row.id}
        data-symbol-selected={
          props.selectedSymbol === props.row.original.symbol
            ? 'true'
            : undefined
        }
        title={props.virtualItem ? undefined : props.row.original.company}
        aria-selected={props.row.getIsSelected()}
      >
        <Index each={currentCells()}>
          {(cell, index) => (
            <TradingTableCell
              cell={cell()}
              renderCell={renderState().cells[index]}
            />
          )}
        </Index>
      </tr>
    </TradingRowDataProvider>
  )
}

function TradingTableCell(props: TradingTableCellProps) {
  const selection = createMemo(() => ({
    edges: props.cell.getSelectionEdges(),
    focused: props.cell.getIsFocused(),
    selected: props.cell.getIsSelected(),
    tabIndex: props.cell.getTabIndex(),
  }))

  return (
    <td
      style={{
        width: `calc(var(--col-${props.cell.column.id}-size) * 1px)`,
      }}
      data-column-id={props.cell.column.id}
      data-cell-focused={selection().focused ? 'true' : undefined}
      data-selection-top={selection().edges.top ? 'true' : undefined}
      data-selection-right={selection().edges.right ? 'true' : undefined}
      data-selection-bottom={selection().edges.bottom ? 'true' : undefined}
      data-selection-left={selection().edges.left ? 'true' : undefined}
      aria-selected={selection().selected}
      tabindex={selection().tabIndex}
    >
      <FlexRender cell={props.renderCell} />
    </td>
  )
}

function haveSameCellOrder(
  previous: ReadonlyArray<TradingCell>,
  next: ReadonlyArray<TradingCell>,
): boolean {
  return (
    previous.length === next.length &&
    previous.every((cell, index) => cell.column.id === next[index]?.column.id)
  )
}

import { createSignal } from 'solid-js'
import {
  useMarketFeedController,
  useTradingShellController,
} from '../shell/trading-shell-context'
import { createTradingTableModel } from './create-trading-table-model'
import {
  createTradingGridProps,
  createTradingTableElementProps,
} from './trading-grid-props'
import {
  createFeedCommitTracking,
  createTableAutoFit,
} from './trading-table-effects'
import { createTradingRowVirtualization } from './trading-row-virtualizer'
import { TradingTableBody } from './trading-table-body'
import { TradingTableFooter } from './trading-table-footer'
import { TradingTableHeader } from './trading-table-header'

export function TradingTable() {
  const feed = useMarketFeedController()
  const { state, actions } = useTradingShellController()
  const [scrollElement, setScrollElement] = createSignal<HTMLDivElement | null>(
    null,
  )
  const virtualized = () => state.virtualScrollMode() === 'tanstack'
  const model = createTradingTableModel({
    quotes: feed.state.quotes,
    rendererMode: state.rendererMode,
    onSelectSymbol: actions.selectSymbol,
  })
  const virtualization = createTradingRowVirtualization({
    rows: model.rows,
    scrollElement,
    enabled: virtualized,
    onRenderedRowCount: actions.setRenderedRowCount,
  })
  const elementOptions = { table: model.table, virtualized }
  const gridProps = createTradingGridProps(elementOptions)
  const tableProps = createTradingTableElementProps(
    elementOptions,
    model.tableStyle,
  )

  createFeedCommitTracking(feed.state.quotes, feed.completeRender)
  createTableAutoFit(model.table, scrollElement)

  return (
    <>
      <div
        {...gridProps}
        ref={(element) => {
          setScrollElement(element)
        }}
      >
        <table {...tableProps}>
          <TradingTableHeader table={model.table} />
          <TradingTableBody
            table={model.table}
            rows={model.rows}
            columnVersion={model.columns}
            selectedSymbol={state.selectedSymbol}
            virtualized={virtualized}
            virtualization={virtualization}
            selectSymbol={actions.selectSymbol}
          />
        </table>
      </div>
      <TradingTableFooter
        table={model.table}
        rows={model.rows}
        virtualized={virtualized}
        virtualization={virtualization}
      />
    </>
  )
}

import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import {
  setRangeValue,
  scrollTradingTable,
  pauseTradingFeed,
  resumeTradingFeed,
  pausedFeedUrl,
} from '../../../../../tests/e2e/helpers/setRangeValue'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

function collectPageErrors(page: Page) {
  const errors: Array<string> = []
  page.on('pageerror', (error) => errors.push(error.message))
  page.on('console', (message) => {
    if (message.type() === 'error') errors.push(message.text())
  })
  return errors
}

test('runs the Solid realtime trading workload', async ({ page }) => {
  test.setTimeout(120_000)
  const server = await startExampleServer(exampleDir)
  const errors = collectPageErrors(page)

  try {
    await page.goto(pausedFeedUrl(server.url))

    const table = page.getByTestId('trading-table')
    const instrumentCount = page.getByTestId('instrument-count-select')
    const virtualScrollSelect = page.getByTestId('virtual-scroll-select')
