          Sort Z → A
        </button>
        <button
          type="button"
          disabled={!props.column.getIsSorted()}
          onClick={() => {
            props.column.clearSorting()
            props.onClose()
          }}
        >
          Clear sort
        </button>
        <div class="column-menu-separator" />
        <label>
          Filter values containing
          <input
            autofocus
            value={filterValue()}
            onInput={(event) =>
              props.column.setFilterValue(event.currentTarget.value)
