// Date filter values cross the FilterList boundary as ISO strings (the
// calendar's DateValue is converted before it lands in columnFilters).

export const fuzzyFilter: FilterFn<typeof features, any> = (
  row,
  columnId,
  value,
  addMeta,
) => {
  const itemRank = rankItem(row.getValue(columnId), value)

  addMeta?.({ itemRank })

  return itemRank.passed
}

function isFalsy(val: unknown) {
  return (
    val === undefined ||
    val === null ||
    val === '' ||
    (Array.isArray(val) && val.length === 0)
  )
}

function isValidDate(value: unknown): boolean {
  if (value instanceof Date) return !isNaN(value.getTime())
  if (typeof value === 'string') return !isNaN(Date.parse(value))
  return false
}

function toDate(value: unknown): Date | null {
  if (value instanceof Date) return value
  if (typeof value === 'string') {
    const date = new Date(value)
    return !isNaN(date.getTime()) ? date : null
  }
  return null
}

function isSameDay(date1: Date, date2: Date): boolean {
  const date1Str = date1.toISOString().split('T')[0]
  const date2Str = date2.toISOString().split('T')[0]
  return date1Str === date2Str
}

const filterFn_enhancedEquals: FilterFn<typeof features, any> = (
  row,
  columnId: string,
  filterValue: unknown,
) => {
  const rowValue = row.getValue(columnId)

  if (Array.isArray(filterValue)) {
    return filterFn_arrIncludes(row, columnId, filterValue)
  }

  if (isValidDate(rowValue) && isValidDate(filterValue)) {
    const rowDate = toDate(rowValue)
    const filterDate = toDate(filterValue)

    if (rowDate && filterDate) {
      return isSameDay(rowDate, filterDate)
    }
  }

  return filterFn_equals(row, columnId, filterValue)
}

filterFn_enhancedEquals.resolveFilterValue = (val: any) => isFalsy(val)

const filterFn_enhancedGreaterThan: FilterFn<typeof features, any> = (
  row,
  columnId: string,
  filterValue: unknown,
) => {
  const rowValue = row.getValue(columnId)

  if (isValidDate(rowValue) && isValidDate(filterValue)) {
    const rowDate = toDate(rowValue)
    const filterDate = toDate(filterValue)

    if (rowDate && filterDate) {
      return rowDate.getTime() > filterDate.getTime()
    }
  }

  return filterFn_greaterThan(row, columnId, filterValue)
}

filterFn_enhancedGreaterThan.resolveFilterValue = (val: any) => isFalsy(val)

const filterFn_enhancedGreaterThanOrEqualTo: FilterFn<typeof features, any> = (
  row,
  columnId: string,
  filterValue: unknown,
) => {
  const rowValue = row.getValue(columnId)

  if (isValidDate(rowValue) && isValidDate(filterValue)) {
