    if (rowDate && filterDate) {
      return rowDate.getTime() >= filterDate.getTime()
    }
  }

  return filterFn_greaterThanOrEqualTo(row, columnId, filterValue)
}

filterFn_enhancedGreaterThanOrEqualTo.resolveFilterValue = (val: any) =>
  isFalsy(val)

