import path from 'node:path'
import { expect, test } from '@playwright/test'
import { startExampleServer } from '../../../../../tests/e2e/helpers/startExampleServer'
import type { Page } from '@playwright/test'

const exampleDir = path.resolve()

const TOTAL_ROWS = 1_000

/** Header cell index per column, matching the column order in `src/main.tsx`. */
const COLUMN = {
  rowNumber: 0,
  firstName: 1,
  lastName: 2,
  age: 3,
  visits: 4,
  status: 5,
  progress: 6,
  birthDate: 7,
} as const

let server: Awaited<ReturnType<typeof startExampleServer>> | undefined

test.beforeAll(async () => {
  // One server for the whole file. A cold Vite start costs more than a test.
  test.setTimeout(180_000)
  server = await startExampleServer(exampleDir)
})

test.afterAll(async () => {
  await server?.close()
})

function collectPageErrors(page: Page) {
  const errors: Array<string> = []

  page.on('pageerror', (error) => {
    errors.push(error.message)
  })

  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })

  return errors
}

async function openExample(page: Page) {
  if (!server) throw new Error('Example server failed to start')

  const errors = collectPageErrors(page)

  await page.route(
    'https://unpkg.com/react-scan/dist/auto.global.js',
    (route) =>
      route.fulfill({
        contentType: 'application/javascript',
        body: '',
      }),
  )

  await page.goto(server.url)

  return errors
}

/** Columns are grouped here, so header controls live in the leaf row. */
function headerCell(page: Page, column: keyof typeof COLUMN) {
  return page.locator('thead tr').last().locator('th').nth(COLUMN[column])
}

function textFilter(page: Page, column: 'firstName' | 'lastName' | 'status') {
  return headerCell(page, column).locator('input[type="text"]')
}

function rangeFilter(
  page: Page,
  column: 'age' | 'visits' | 'progress',
  bound: 'Min' | 'Max',
) {
  return headerCell(page, column).getByPlaceholder(bound)
}

function dateRangeFilter(page: Page, bound: 'min' | 'max') {
  return headerCell(page, 'birthDate').locator(
    `input[aria-label="birthDate ${bound}"]`,
  )
}

function globalFilterInput(page: Page) {
  return page.getByPlaceholder('Search all columns...')
}

/** The pre-paginated count, so it reflects filtering but not the page window. */
function rowCountLine(page: Page) {
  return page.locator('div').filter({ hasText: /^\s*[\d,]+ Rows\s*$/ })
}

async function readFilteredRowCount(page: Page) {
  const text = await rowCountLine(page).textContent()
  return Number((text ?? '').replace(/\D/g, ''))
}

/** Row data is random faker output, so `table.state` is the stable oracle. */
async function readState(page: Page) {
  const text = await page.getByTestId('table-state').textContent()

  return JSON.parse(text ?? '{}') as {
    columnFilters?: Array<{ id: string; value: unknown }>
    pagination?: { pageIndex: number; pageSize: number }
  }
}

async function readColumnFilters(page: Page) {
  return (await readState(page)).columnFilters ?? []
}

async function expectColumnFilters(
  page: Page,
  expected: Array<{ id: string; value: unknown }>,
) {
  // Every filter control debounces by 500ms, so poll rather than sleeping.
  await expect.poll(() => readColumnFilters(page)).toEqual(expected)
}

async function readBodyColumn(page: Page, column: keyof typeof COLUMN) {
  const cells = await page
    .locator(`tbody tr td:nth-child(${COLUMN[column] + 1})`)
    .allTextContents()

  return cells.map((cell) => cell.trim())
}

async function getFirstBodyRowText(page: Page) {
  const text = await page.locator('tbody tr').first().textContent()
  return text?.replace(/\s+/g, ' ').trim() ?? ''
}

test('renders the table without crashing', async ({ page }) => {
  const errors = await openExample(page)
  const table = page.locator('table').first()

  await expect(table).toBeVisible()
  await expect(page.locator('thead tr').last().locator('th')).toHaveCount(8)
  await expect(page.locator('tbody tr')).toHaveCount(10)
  await expect(rowCountLine(page)).toHaveText('1,000 Rows')
  await expectColumnFilters(page, [])

  expect(errors).toEqual([])
})

test('regenerates table data', async ({ page }) => {
  const errors = await openExample(page)
  const regenerateButton = page.getByRole('button', {
    name: /^Regenerate Data$/i,
  })

  await expect(page.locator('tbody tr').first()).toBeVisible()

  const firstRowBefore = await getFirstBodyRowText(page)

  await regenerateButton.click()

  await expect.poll(() => getFirstBodyRowText(page)).not.toBe(firstRowBefore)
  await expect(page.locator('tbody tr')).toHaveCount(10)

  expect(errors).toEqual([])
})

test('renders a filter control for every filterable column', async ({
  page,
}) => {
  const errors = await openExample(page)

  // Three text columns, three range columns with a Min and a Max, one date
  // column with a min and a max date input.
  await expect(page.locator('thead input[type="text"]')).toHaveCount(3)
  await expect(page.locator('thead input[type="number"]')).toHaveCount(6)
  await expect(page.locator('thead input[type="date"]')).toHaveCount(2)
  // Status filters as free text here rather than through a select.
  await expect(page.locator('thead select')).toHaveCount(0)

  // Placeholders carry the faceted unique-value count for that column.
  await expect(textFilter(page, 'firstName')).toHaveAttribute(
    'placeholder',
    /^Search\.\.\./,
  )
  // The row number column has no accessor, so it cannot be filtered.
  await expect(
    headerCell(page, 'rowNumber').locator('input, select'),
  ).toHaveCount(0)

  expect(errors).toEqual([])
})

test('filters by text after the debounce', async ({ page }) => {
  const errors = await openExample(page)

  // A fragment of a name that is actually present, so a match is guaranteed
  // even though the data is regenerated randomly on every load.
  const firstNames = await readBodyColumn(page, 'firstName')
  const fragment = (firstNames[0] ?? '').slice(0, 3).toLowerCase()
  expect(fragment).not.toBe('')

  await textFilter(page, 'firstName').fill(fragment)

  await expectColumnFilters(page, [{ id: 'firstName', value: fragment }])

  const filtered = await readFilteredRowCount(page)
  expect(filtered).toBeGreaterThan(0)
  expect(filtered).toBeLessThan(TOTAL_ROWS)

  for (const name of await readBodyColumn(page, 'firstName')) {
    expect(name.toLowerCase()).toContain(fragment)
  }

  // Emptying a text filter drops it from state rather than keeping a blank.
  await textFilter(page, 'firstName').fill('')

  await expectColumnFilters(page, [])
  await expect(rowCountLine(page)).toHaveText('1,000 Rows')

  expect(errors).toEqual([])
})

test('waits for the debounce before applying the filter', async ({ page }) => {
  const errors = await openExample(page)

  await textFilter(page, 'firstName').fill('zzz')

  // The 500ms debounce has not elapsed, so state is still untouched.
  expect(await readColumnFilters(page)).toEqual([])

  await expectColumnFilters(page, [{ id: 'firstName', value: 'zzz' }])

  expect(errors).toEqual([])
})

test('filters a numeric column by range', async ({ page }) => {
  const errors = await openExample(page)

  await rangeFilter(page, 'age', 'Min').fill('20')

  // This example coerces the bound to a number; an unset bound serialises as
  // null, leaving the range open ended.
  await expectColumnFilters(page, [{ id: 'age', value: [20, null] }])

  const minOnly = await readFilteredRowCount(page)
  expect(minOnly).toBeLessThan(TOTAL_ROWS)

  for (const age of await readBodyColumn(page, 'age')) {
    expect(Number(age)).toBeGreaterThanOrEqual(20)
  }

  await rangeFilter(page, 'age', 'Max').fill('25')

  await expectColumnFilters(page, [{ id: 'age', value: [20, 25] }])
  expect(await readFilteredRowCount(page)).toBeLessThan(minOnly)

  for (const age of await readBodyColumn(page, 'age')) {
    expect(Number(age)).toBeGreaterThanOrEqual(20)
    expect(Number(age)).toBeLessThanOrEqual(25)
  }

  // Clearing one bound keeps the filter, with that end left open.
  await rangeFilter(page, 'age', 'Min').fill('')

  await expect
    .poll(async () => (await readColumnFilters(page))[0]?.id)
    .toBe('age')

  for (const age of await readBodyColumn(page, 'age')) {
    expect(Number(age)).toBeLessThanOrEqual(25)
  }

  await rangeFilter(page, 'age', 'Max').fill('')

  await expect.poll(() => readFilteredRowCount(page)).toBe(TOTAL_ROWS)

  expect(errors).toEqual([])
})

test('filters a date column by range', async ({ page }) => {
  const errors = await openExample(page)

  // Cells render ISO dates (YYYY-MM-DD), so string order is date order. Use
  // a bound from the visible data so a match is guaranteed despite random rows.
  const dates = (await readBodyColumn(page, 'birthDate')).sort()
  const minDate = dates[Math.floor(dates.length / 2)]!
  expect(minDate).toMatch(/^\d{4}-\d{2}-\d{2}$/)

  await dateRangeFilter(page, 'min').fill(minDate)

  // An unset bound serialises as null, leaving the range open ended.
  await expectColumnFilters(page, [{ id: 'birthDate', value: [minDate, null] }])

  const minOnly = await readFilteredRowCount(page)
  expect(minOnly).toBeGreaterThan(0)
  expect(minOnly).toBeLessThan(TOTAL_ROWS)

  for (const date of await readBodyColumn(page, 'birthDate')) {
    expect(date >= minDate).toBe(true)
  }

  // The largest visible date keeps the range ordered and non-empty.
  const maxDate = dates[dates.length - 1]!
  await dateRangeFilter(page, 'max').fill(maxDate)

  await expectColumnFilters(page, [
    { id: 'birthDate', value: [minDate, maxDate] },
  ])

  for (const date of await readBodyColumn(page, 'birthDate')) {
    expect(date >= minDate).toBe(true)
    expect(date <= maxDate).toBe(true)
  }

  // Clearing both bounds auto-removes the filter entirely.
  await dateRangeFilter(page, 'min').fill('')
  await dateRangeFilter(page, 'max').fill('')

  await expectColumnFilters(page, [])
  await expect(rowCountLine(page)).toHaveText('1,000 Rows')

  expect(errors).toEqual([])
})

test('filters every column at once with the global filter', async ({
  page,
}) => {
  const errors = await openExample(page)

  const firstNames = await readBodyColumn(page, 'firstName')
  const fragment = (firstNames[0] ?? '').slice(0, 3).toLowerCase()
  expect(fragment).not.toBe('')

  await globalFilterInput(page).fill(fragment)

  // The global filter is not a column filter, so it narrows the rows without
  // adding anything to `columnFilters`.
  await expect.poll(() => readFilteredRowCount(page)).toBeLessThan(TOTAL_ROWS)
  expect(await readColumnFilters(page)).toEqual([])

  await globalFilterInput(page).fill('')

  await expect.poll(() => readFilteredRowCount(page)).toBe(TOTAL_ROWS)

  expect(errors).toEqual([])
})

test('combines filters and returns to the first page', async ({ page }) => {
  const errors = await openExample(page)

  await page.getByRole('button', { name: '>', exact: true }).click()
  await page.getByRole('button', { name: '>', exact: true }).click()
  await expect
    .poll(async () => (await readState(page)).pagination?.pageIndex)
    .toBe(2)

  await textFilter(page, 'status').fill('single')

  await expectColumnFilters(page, [{ id: 'status', value: 'single' }])
  // `autoResetPageIndex` defaults to true, so filtering rewinds to page one.
  await expect
    .poll(async () => (await readState(page)).pagination?.pageIndex)
    .toBe(0)

  const statusOnly = await readFilteredRowCount(page)

  await rangeFilter(page, 'age', 'Min').fill('20')

  await expectColumnFilters(page, [
    { id: 'status', value: 'single' },
    { id: 'age', value: [20, null] },
  ])
  // Filters intersect, so adding one can only narrow the result.
  expect(await readFilteredRowCount(page)).toBeLessThanOrEqual(statusOnly)

  for (const cell of await readBodyColumn(page, 'status')) {
    expect(cell).toBe('single')
  }

import { defineComponent, ref } from 'vue'
import { FlexRender, tableFeatures, useTable } from '@tanstack/vue-table'
import { makeData } from './makeData'
import type {
  Cell,
  ColumnDef,
  Header,
  HeaderGroup,
  Row,
} from '@tanstack/vue-table'
import type { Person } from './makeData'

const features = tableFeatures({})

// A traditional header group setup: every leaf column sits under a top-level
// group, so the tree is even (2 header rows) and no placeholder headers are
// created.
const basicColumns: Array<ColumnDef<typeof features, Person>> = [
  {
    header: 'Name',
    columns: [
      {
        accessorKey: 'firstName',
        header: 'First Name',
        footer: 'First Name',
      },
      {
        accessorFn: (row) => row.lastName,
        id: 'lastName',
        header: 'Last Name',
        footer: 'Last Name',
      },
    ],
  },
  {
    header: 'Stats',
    columns: [
      {
        accessorKey: 'age',
        header: 'Age',
        footer: 'Age',
      },
      {
        accessorKey: 'visits',
        header: 'Visits',
        footer: 'Visits',
      },
    ],
  },
  {
    header: 'Profile',
    columns: [
      {
        accessorKey: 'status',
        header: 'Status',
        footer: 'Status',
      },
      {
        accessorKey: 'progress',
        header: 'Profile Progress',
        footer: 'Profile Progress',
      },
    ],
  },
]

// Groups nested inside groups, with every leaf column at the same depth. The
// tree stays even, so there are three header rows and still no placeholders,
// and each group's colSpan is the sum of its descendants.
const nestedColumns: Array<ColumnDef<typeof features, Person>> = [
  {
    header: 'Person',
    columns: [
      {
        header: 'Name',
        columns: [
          { accessorKey: 'firstName', header: 'First Name' },
          {
            accessorFn: (row) => row.lastName,
            id: 'lastName',
            header: 'Last Name',
          },
        ],
      },
      {
        header: 'Demographics',
        columns: [{ accessorKey: 'age', header: 'Age' }],
      },
    ],
  },
  {
    header: 'Activity',
    columns: [
      {
        header: 'Engagement',
        columns: [
          { accessorKey: 'visits', header: 'Visits' },
          { accessorKey: 'status', header: 'Status' },
        ],
      },
      {
        header: 'Progress',
        columns: [{ accessorKey: 'progress', header: 'Profile Progress' }],
      },
    ],
  },
]

const columns: Array<ColumnDef<typeof features, Person>> = [
  {
    header: 'Name',
    footer: (props) => props.column.id,
    columns: [
      {
        accessorKey: 'firstName',
        cell: (info) => info.getValue(),
        footer: (props) => props.column.id,
      },
      {
        accessorFn: (row) => row.lastName,
        id: 'lastName',
        cell: (info) => info.getValue(),
        header: () => <span>Last Name</span>,
        footer: (props) => props.column.id,
      },
    ],
  },
  {
    header: 'Info',
    footer: (props) => props.column.id,
    columns: [
      {
        accessorKey: 'age',
        header: () => 'Age',
        footer: (props) => props.column.id,
      },
      {
        header: 'More Info',
        columns: [
          {
            accessorKey: 'visits',
            header: () => <span>Visits</span>,
            footer: (props) => props.column.id,
          },
          {
            accessorKey: 'status',
            header: 'Status',
            footer: (props) => props.column.id,
          },
          {
            accessorKey: 'progress',
            header: 'Profile Progress',
            footer: (props) => props.column.id,
          },
        ],
      },
    ],
  },
]

// An uneven column tree: `fullName` and `progress` are top-level leaf columns
// while their siblings nest two and three levels deep. The placeholder at the
// top of each column's placeholder chain carries the chain's full
// `header.rowSpan`, and the headers it covers report a rowSpan of 0 so the
// renderer can skip them.
const unevenColumns: Array<ColumnDef<typeof features, Person>> = [
  {
    accessorFn: (row) =>
      [row.firstName, row.lastName].filter(Boolean).join(' '),
    id: 'fullName',
    header: 'Full Name',
    cell: (info) => info.getValue(),
  },
  {
    header: 'Info',
    columns: [
      {
        accessorKey: 'age',
        header: () => 'Age',
      },
      {
        header: 'More Info',
        columns: [
          {
            accessorKey: 'visits',
            header: () => <span>Visits</span>,
          },
          {
            accessorKey: 'status',
            header: 'Status',
          },
        ],
      },
    ],
  },
  {
    accessorKey: 'progress',
    header: 'Profile Progress',
  },
]

export default defineComponent({
  name: 'HeaderGroupsExample',
